(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[9107],{3683:(e,t,a)=>{"use strict";a.d(t,{CoreRulesBrowser:()=>w});var i=a(5155),o=a(2115),n=a(7877);let s=["en","de","es","fr","it","ja","ko","zh"],r={en:"English",de:"Deutsch",es:"Espa\xf1ol",fr:"Fran\xe7ais",it:"Italiano",ja:"日本語",ko:"한국어",zh:"中文"},l="rules-locale";function h(e){var t;let{title:a,description:h,searchPlaceholder:x,eager:d,loaders:c,stratagemBodies:u,tableShapesByRef:m,pdfCalloutsByRef:f,extraGroups:g,sourceOf:b}=e,[y,p]=function(){let[e,t]=(0,o.useState)("en");return(0,o.useEffect)(()=>{try{let e=window.localStorage.getItem(l);null!==e&&s.includes(e)&&t(e)}catch(e){}},[]),[e,e=>{t(e);try{window.localStorage.setItem(l,e)}catch(e){}}]}(),[w,v]=(0,o.useState)({en:d}),[k,T]=(0,o.useState)(!1);(0,o.useEffect)(()=>{if(w[y])return;let e=c[y];if(!e)return;let t=!1;return T(!0),e().then(e=>{t||v(t=>({...t,[y]:e}))}).finally(()=>{t||T(!1)}),()=>{t=!0}},[y,w,c]);let A=null!=(t=w[y])?t:d,S=(0,o.useMemo)(()=>{let e=A.map(e=>({id:e.number,badge:e.number,title:e.title,entries:e.subsections.map((t,a)=>{var i;let o=t.text;0===o.length&&(null==u?void 0:u[t.ref])&&(o=u[t.ref]);let s=null==f?void 0:f[t.ref];return s&&(o=[...o,...s.map(e=>(0,n.B)(e.title,e.body))]),{id:t.ref||"".concat(e.number,"-").concat(a),label:t.ref||void 0,title:t.title,text:o,tables:function(e,t){let a=e.tables;if(!a||0===a.length)return;if(!t)return a;let[i,...o]=a,{headRow:n,endRow:s=i.rows.length}=t;if(n<=0||n>=i.rows.length-1||s<=n+1||s>i.rows.length)return a;let r=[...i.rows.slice(0,n),...i.rows.slice(s)];return[{...i,rows:r},{head:i.rows[n],rows:i.rows.slice(n+1,s)},...o]}(t,null==m?void 0:m[t.ref]),accordions:null==(i=t.accordions)?void 0:i.map(e=>({id:e.ref,label:e.ref||void 0,title:e.title,text:e.text,tables:e.tables}))}})}));return g?[...e,...g]:e},[A,u,m,f,g]),E=(0,i.jsxs)("label",{className:"flex flex-col gap-2",children:[(0,i.jsx)("span",{className:"font-mono text-[0.625rem] uppercase tracking-[0.16em] text-muted-foreground",children:"Language"}),(0,i.jsx)("select",{value:y,onChange:e=>p(e.target.value),"aria-busy":k,className:"w-full rounded-md border border-border bg-card px-2 py-1.5 text-[0.8125rem] text-foreground focus:border-primary focus:outline-none focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring",children:s.map(e=>(0,i.jsxs)("option",{value:e,children:[r[e],k&&e===y?" …":""]},e))}),(0,i.jsx)("span",{role:"status",className:"sr-only",children:k?"Loading ".concat(r[y],"…"):""})]});return(0,i.jsx)(n.RulesBrowser,{title:a,description:h,searchPlaceholder:x,groups:S,toolbar:E,sourceOf:b,settingsActive:"en"!==y})}let x=[{number:"01",title:"Core Concepts",subsections:[{ref:"01.01",title:"Armies",text:["Each player in a game of Warhammer 40,000 commands an army made up of units of models. You control all of the models in your army. If a rule refers to the ‘controlling player’, it is referring to the player who controls the models being affected by that rule."],accordions:[{ref:"01.01.01",title:"You",text:["If a rule refers to ‘you’, it is referring to you the person, as the controlling player."]}]},{ref:"01.02",title:"Units and Models",text:["A unit can contain one or more models. These models move and fight together as a single group. Most models have a base, which is also part of that model for all rules purposes.","Rules sometimes affect ‘friendly’ or ‘enemy’ models or units, which are defined as follows:","• Friendly units and models are those in your army.","• Enemy units and models are those in your opponent’s army.","If a rule affects units or models without specifying that they are friendly or enemy, that rule affects any unit or model, regardless of whose army they are in. When an effect or ability applies to a unit, it applies to every model in that unit."],accordions:[{ref:"01.02.01",title:"Starting Strength and Half-Strength",text:["The number of models a unit contains at the start of the first battle round is its \x05starting strength\x06. The \x05starting strength\x06 of an attached unit is the number of models that unit contains at the start of the first battle round.","Some rules refer to units being \x05below starting strength\x06, or at – or below – \x05half‑strength\x06. The meaning of these terms varies depending on a unit’s \x05starting strength\x06, as shown below.","\x05Example:\x06 \x07A Captain (1 model) is attached to a unit of Intercessors (5 models). This \x05attached unit\x06 has a \x05starting strength\x06 of 6. If three Intercessors were \x05destroyed\x06, the unit would be at \x05half‑strength\x06. If four Intercessors were \x05destroyed\x06, the unit would be \x05below half‑strength\x06. If all of the Intercessors were \x05destroyed\x06, the remaining Captain would be \x05below half‑strength\x06, despite having his full wounds remaining.\b"],tables:[{head:["","\x05STARTING STRENGTH OF 1\x06","\x05STARTING STRENGTH OF 2 OR MORE\x06"],rows:[["\x05BELOW STARTING STRENGTH\x06","Model's remaining wounds are \x01less than\x02 its \x05W\x06 characteristic.","Number of remaining models in the unit is \x01less than\x02 its \x05starting strength\x06."],["\x05AT HALF-STRENGTH\x06","Model's remaining wounds are \x01half\x02 of its \x05W\x06 characteristic.","Number of remaining models in the unit is \x01half\x02 of its \x05starting strength\x06."],["\x05BELOW HALF-STRENGTH\x06","Model's remaining wounds are \x01less than half\x02 of its \x05W\x06 characteristic.","Number of remaining models in the unit is \x01less than half\x02 of its \x05starting strength\x06."]]}]},{ref:"01.02.02",title:"Persisting Rules Effects",text:["Some rules apply an effect that lasts until a certain duration has passed (e.g. until the start of your next turn). Such effects are known as persisting effects.","If a persisting effect applies to a unit when you place it in \x05strategic reserves\x06 or when it embarks within a \x03TRANSPORT\x04, make a note of that effect and its duration; if that unit is set up on the battlefield again, any persisting effects continue to apply to that unit for their full duration.","If you have a rule that specifies when it is triggered (e.g. 'In the Shooting phase') and it does not specify how long it is active for, it is only active for the duration of that specified period (e.g. until the end of that Shooting phase). After that period, that effect is no longer applicable/active.","If a rule or effect is given to a unit and it does not specify how long it is active for, it is only active for the phase in which it was given."]},{ref:"01.02.03",title:"Revived and Adding Models to a Unit",text:["When a rule \x05revives\x06, resurrects, returns or adds models to a unit, the specified number of models are added to the unit.","• If a rule \x05revives\x06, resurrects or returns models to a unit, it does so through \x05destroyed\x06 models from that unit.","• This cannot expand a unit beyond its \x05starting strength\x06.","• Unless otherwise stated, such models are added with all wargear and enhancements they started the battle with, and with their full \x05W\x06 remaining.","Models returned to a unit on the battlefield must be set up as follows:","• They must be set up in \x05coherency\x06 with models in that unit that started that phase on the battlefield.","• They can be set up \x05engaged\x06 with one or more enemy units, but only if those enemy units were already \x05engaged\x06 with the unit that model is being returned to.","If a \x05leader\x06 or \x05support\x06 model in an \x05attached\x06 unit is \x05destroyed\x06 and subsequently revived, they are still part of that \x05attached\x06 unit and they must be returned to it if possible.","When a model \x05revives\x06, resurrects, returns or is added to an embarked unit, if that \x03TRANSPORT\x04 has sufficient remaining \x05transport capacity\x06 for that model, that model is returned to that unit and is embarked. Otherwise, that model is \x05destroyed\x06, but it does not trigger rules that apply when a model is \x05destroyed\x06."]},{ref:"01.02.04",title:"Not On The Battlefield",text:["A unit that is embarked within a \x03TRANSPORT\x04 or that is in \x05strategic reserves\x06 is not on the battlefield. The following applies to such units:","• That unit is \x01not\x02 \x05visible\x06 to any \x01other\x02 units (units are \x05visible\x06 to themselves).","• Any other unit is \x01not\x02 \x05visible\x06 to that unit.","• Players cannot measure distances to or from that unit (units are within range of their own abilities).","This means units not on the battlefield cannot be selected or targeted by any attack or rule that requires a unit to be \x05visible\x06or within a certain distance (other than their own abilities).","Such units can still use their other rules, and are still units in the controlling player's army and so can be affected by rules that require a player to select a unit from an army, as well as rules that affect all units in an army.","The controlling player must make \x05battle-shock rolls\x06 for units that are not on the battlefield in their Command phase if they are \x05battle-shocked\x06, or if they are at or below \x05half-strength\x06."]},{ref:"01.02.05",title:"Other Model / Unit",text:["When a rule refers to models or units ‘other’ than the one with that rule (or one already mentioned by that rule), it means a different model or unit to that original one.","Different instances of the same datasheet are still considered to be ‘other’ units."]},{ref:"01.02.06",title:"Splitting Units",text:["Some rules allow you to split units into smaller units (e.g. the Transport ability of Drukhari Venoms). When using such rules:","• The same models can only be subdivided in this way once (e.g. those smaller units cannot themselves be split further).","• If a rule is used to split a unit into multiple units before the battle, the \x05starting strength\x06 of each individual unit is changed to be equal to the number of models in that unit.","• A unit must be split into two units, each containing as equal a number of models as possible (when splitting a unit in this way, make a note of which models form each of the two new units).  If a rule states a specific \x05starting strength\x06 of the split units, but this is not possible based on the number of models in the unit being split (e.g. due to \x05attached Leader/Support\x06 models), split the unit as stated above."]},{ref:"01.02.07",title:"Describing Units",text:["When a rule mentions a unit, it may have a descriptor for the unit (e.g. \x03Terminator\x04 unit, \x05hidden\x06 unit, \x05battle-shocked\x06 unit, \x05visible\x06 unit, controlling unit). For such descriptors to apply to a unit, that unit must have at least one model in that unit that meets that descriptor.","This does not give that rule to every model in the unit, unless that rule specifically states that it gives that rule to the unit, in which case every model in that unit gains that rule, as described in Units and Models (01.02).","\x05Example:\x06 \x07A \x05hidden\x06 unit would be a unit that has a model in it that is \x05hidden\x06.\b"]},{ref:"01.02.08",title:"A (Unit/Model/Object)",text:["Some rules may refer to 'a' unit/model/object without specifying an exact number. In such cases, the meaning is 'one or more', rather than exactly one.","\x05Example:\x06 If a rule has a condition that requires a unit to be 'within range of an \x05objective\x06', that condition is still met if that unit is within range of more than one \x05objective\x06."]},{ref:"01.02.09",title:"Tokens",text:["Tokens are gaming aids that some rules instruct you to place next to model/unit to remind you and your opponent that a model/unit either has a limited-use ability or is under the effects of a particular rule. Tokens are not counted as models for any purposes (even if they are being represented by a model). If another model needs to move into the space occupied by a token, reposition the token to allow that move to be made."]},{ref:"01.02.10",title:"Adding a new unit to your army",text:["Some rules add a new unit to your army during a battle. That unit’s \x05starting strength\x06 is determined when it is added to your army, but is otherwise determined in the same way as for other units."]},{ref:"01.02.11",title:"All Types of Model",text:["When a rule mentions ‘all types of model’, this is inclusive of friendly and enemy models and all keywords, e.g. \x03MONSTER/VEHICLE\x04 models."]}]},{ref:"01.03",title:"Active Player and Opposing Player",text:["At any given time, one player is the ‘active player’ and their opponent is the ‘opposing player’. Which player is which changes throughout the battle, but both players are always one or the other; whenever a player becomes the active player, their opponent becomes the opposing player, and vice versa.","While it is neither player’s turn (e.g. at the start or end of the battle round), the player who takes the first turn in each battle round is the active player.","While it is a player’s turn, that player is the active player, with the following exceptions:","• Each time a unit is \x05selected to move\x06, that unit’s controlling player is the active player until that move ends.","• Each time a unit is \x05selected to shoot\x06 or \x05selected to fight\x06, that unit’s controlling player is the active player until those attacks are resolved."],accordions:[{ref:"01.03.01",title:"Player's Rules",text:["During the game, players will sometimes need to know which rules are theirs, as opposed to their opponent’s. The following are considered a player’s rules:","• Any \x05army rules\x06 they have.","• Any \x05detachments\x06 in their army.","• Any \x05stratagems\x06 they use.","• Any \x05enhancements\x06 that units or models in their army have.","• Any abilities or rules found on their units’ datasheets.","• Rules that have restrictions (e.g. 'Once per battle/turn/phase') only apply to the player whose rule it is.","Some missions may introduce additional rules that take effect in the battle. Where this is the case:","• If the rule is used by a player, it is treated as one of that player’s rules.","• If it is not used by a player, and always takes effect, such a rule is resolved before any of the active player’s rules, in an order of their choosing."]},{ref:"01.03.02",title:"Rules Sequencing",text:["At any point in the game, the players will have rules that they can or must use, which may occur at the same time another player can or must use a rule. Unless otherwise stated, these are activated in the following order:","\x051.\x06 All of the active player’s rules that must be used, in an order of their choosing.","\x052.\x06 All of the active player’s rules that they can optionally use and wish to use, in an order of their choosing.","\x053.\x06 All of the opposing player’s rules that must be used, in an order of their choosing.","\x054.\x06 All of the opposing player’s rules that they can optionally use and wish to use, in an order of their choosing.","If another rule could be used after a rule has resolved during this sequence but before other rules in that same timing have resolved, those new rules do not trigger until all the remaining rules to be resolved in that same timing have been resolved.","\x05Example:\x06 \x07The active player's unit has an ability enabling it to make a \x05normal move\x06 after it has shot. An enemy unit targeted by that unit has an ability enabling it to shoot back at a unit that shot at it. The active player's rule is resolved first, followed by the opposing player's rule.\b"]}]},{ref:"01.04",title:"Measuring Distances",text:['Distances in Warhammer 40,000 are measured in inches ("). You can measure distances whenever you want to.',"When a rule refers to a model’s position in relation to anything else on the battlefield, unless otherwise stated, measure to or from the closest part of that model’s base."],accordions:[{ref:"01.04.01",title:"Within / Wholly Within",text:["Rules in Warhammer 40,000 will often apply to models or units that are within or wholly within a certain distance. The following definitions explain what these terms mean:",'• \x05Within:\x06 If a rule says it applies ‘within’ a specified distance, it applies at any distance that is not more than that distance. For example, within 1" means any distance that is not more than 1" away',"• \x05Model/Unit Within:\x06 A model is within a specified distance if any part of its base is within that distance. A unit is within a specified distance if one or more of its models are within that distance.","• \x05Model/Unit Wholly Within:\x06 A model is wholly within a specified distance if every part of its base is within that distance. A unit is wholly within if every model in that unit is wholly within the specified distance. A model with the \x03frame\x04 keyword is wholly within a specified distance if all parts of that model are within the specified distance.","\x05Example\x06: \x07A model is wholly within a \x05terrain area\x06 if no part of its base extends beyond the footprint of that \x05terrain area\x06. A unit is wholly within a specified distance if every model in that unit is wholly within that distance.\b"]},{ref:"01.04.02",title:"Closest Or Nearest Model/Unit",text:["When a rule refers to the closest or nearest model or unit, this is the closest model or unit to the model or unit using that rule.","If two or more are equally close, the controlling player of the model or unit using that rule selects which is the closest for the purposes of that rule."]},{ref:"01.04.03",title:"As Close As Possible",text:["If a rule instructs you to move a model as close as possible to a unit or model you must end that model’s move in base contact with that unit or model if its move is sufficient to do so without breaking any other restrictions (such as \x05coherency\x06), or as close as you can achieve if its move is not sufficient.","• If a model is already as close as possible to a unit or model when it is instructed to make a move as close as possible towards a unit or model, that model cannot be moved, but still counts as having made the move in question.","If a rule instructs you to move a model as close as possible to an \x05objective\x06 you must end that model’s move within range of an \x05objective\x06 if its move is sufficient to do so without breaking any other restrictions (such as \x05coherency\x06), or as close as you can achieve if its move is not sufficient.","• If that model is already within range of an \x05objective\x06 it can move up to the \x05maximum distance\x06 of that move but must end its move still within range of that \x05objective\x06."]},{ref:"01.04.04",title:"Base Contact or Base to Base Contact",text:["When two models’ bases are touching, they are in base contact – also known as base-to-base contact – and are as close as possible (01.04.03).","When moving a model from your army into base contact with an enemy model during a move, if that enemy model overhangs its base such that it is not physically possible to be in base contact with that model, until the end of the turn, those models are considered to be in base contact with each other while all of the following are true:","• The distance your model could move was sufficient to move it into base contact with the enemy model if there was no overhang.","• The models are as close as possible together.",'• Any part of one model is within 1" of any part of the other model.']},{ref:"01.04.05",title:"Table Quarters",text:["When a rule refers to a table quarter, or table quarters, divide the battlefield with imaginary lines 1mm thick drawn lengthwise and widthwise through the centre of the battlefield to create four equal rectangles. These rectangles are the table quarters."]}]},{ref:"01.05",title:"Dice",text:["You will require some six-sided dice (often abbreviated to D6). There are many ways dice rolls are referred to, including:","• \x052+, 3+, and so on:\x06 2+ means a result of 2 or more, 3+ means a result of 3 or more, and so on.","• \x051-3, 4-6, and so on:\x06 Any result within the specified range will interact with the rule stated.","• \x052D6, 3D6, and so on:\x06 Roll the stated number of D6 and add the individual values together (e.g. to roll 2D6, roll two D6 and add the values together).","• \x05D3:\x06 Roll one D6 and halve the result (rounding up).","• \x05D6+1, 2D6+3, and so on:\x06 Roll the stated number of dice and add the stated value to the result."],accordions:[{ref:"01.05.01",title:"Automatically Successful/Passes/Hits/Wounds",text:["When a dice roll or test is automatically successful or automatically passes/hits/wounds, do not roll the dice and instead move to the next step of the sequence for that roll as if the required result had been rolled. Any rules that take effect on a particular dice result or roll result do not take effect.","\x05Example\x06: \x07If a \x05hit roll\x06 is automatically successful, move straight to the Wound Rolls step for that attack. Such a \x05hit roll\x06 is not a \x05critical hit\x06.\b","\x05Example\x06: \x07If a \x05wound roll\x06 is automatically successful, move straight to the Save Rolls step for that attack. Such a \x05wound roll\x06 is not a \x05critical wound\x06.\b"]},{ref:"01.05.02",title:"Re-rolls",text:["Some rules allow you to re-roll a dice roll, which means you get to roll some or all of the dice again. When a rule lets you re-roll one or more dice, the following points apply:","• If a rule allows you to re-roll a dice roll that was made by adding several dice together (e.g. 2D6, 3D6, etc.) then you must re-roll all of those dice again.","• You can never re-roll a dice more than once, and re-rolls happen before modifiers (if any) are applied.","• A re-rolled dice is still considered to be a dice roll and, as such, any rules that can be triggered by a dice roll can also be triggered by a re-rolled dice."]},{ref:"01.05.03",title:"Modifying Dice Rolls",text:["See Modifiers (02.02.01)."]},{ref:"01.05.04",title:"Ignoring Roll Modifiers",text:["See Ignore Modifiers (02.02.02)"]},{ref:"01.05.05",title:"Roll Off",text:["Some rules instruct players to roll off.","• To do so, both players roll one D6, and whoever rolls highest wins the roll-off.","• If there is a tie for the highest roll, roll off again."]},{ref:"01.05.06",title:"Doubles Or Triples",text:["When making a dice roll, a double is a roll that includes any two dice of the same result, and a triple is a roll that includes any three dice of the same result."]},{ref:"01.05.07",title:"Highest or Lowest Dice Result",text:["If a rule refers to the highest dice result and a dice roll involves multiple dice, if more than one of those dice have the same value, and that value is the highest, the active player must select one of those dice to be the highest dice result.","If a rule refers to the lowest dice result and a dice roll involves multiple dice, if more than one of those dice have the same value, and that value is the lowest, the active player must select one of those dice to be the lowest dice result."]},{ref:"01.05.08",title:"Treated As, Set To (Dice Roll)",text:["When a dice result is ‘treated as’ or 'set' to another value, any rules that would take effect if that value had been rolled take effect.","This may result in a value that is greater than a value that could be rolled on a D6 dice."]}]},{ref:"01.06",title:"Leadership Rolls",text:["To make a \x05leadership roll\x06 for a unit, its controlling player rolls 2D6: if the result is equal to or greater than one or more of the \x05Ld\x06 characteristics in that unit, that roll succeeds. Otherwise, that roll fails. The rule that instructed you to make that \x05leadership roll\x06 will describe the effects of that roll succeeding or failing."],accordions:[{ref:"01.06.01",title:"Leadership Test",text:["Some rules may use the term Leadership test, this is the same as \x05leadership roll\x06."]}]},{ref:"01.07",title:"Battle-shock Rolls",text:["To make a \x05battle-shock roll\x06 for a unit, its controlling player makes a \x05leadership roll\x06 for it (01.06).","• If that roll \x01succeeds\x02, that unit does not become \x05battle-shocked.\x06","• If that roll \x01fails\x02, that unit, and each model in it, is \x05battle-shocked\x06.","While a unit is \x05battle-shocked\x06:","• The Objective Control (\x05OC\x06) characteristic of all of its models is modified to ‘-’ (02.02).","• Its controlling player cannot target that unit with \x05stratagems\x06 (15).","• It is \x01not\x02 \x05eligible to start an action\x06 (16), and any \x05action\x06 it has started cannot be completed."],accordions:[{ref:"01.07.01",title:"Battlefield Morale",text:["The morale and organisation of troops can waver and break during battle. This is checked using \x05battle-shock rolls\x06, most commonly in the Command phase. Failing such a roll represents the unit’s courage faltering due to taking casualties or through other disruption, reducing its battlefield effectiveness. Similarly, some rules will require you to check a unit’s readiness by making a \x05leadership roll\x06."]},{ref:"01.07.02",title:"Battle-shock Test",text:["The term Battle-shock test is the same as \x05battle-shock roll\x06."]}]}]},{number:"02",title:"Datasheets",subsections:[{ref:"02.01",title:"Datasheet Name",text:["Here you will find the name of the unit."],accordions:[{ref:"02.01.01",title:"Datasheet Name and Keywords",text:["As well as the keywords listed in each datasheet’s Keywords section, each datasheet name acts as an additional keyword for that unit."]}]},{ref:"02.02",title:"Profiles",text:["These contain the following characteristics that tell you how mighty the models in the unit are:","\x05Move (M)\x06: The speed at which a model traverses the battlefield. If a model has an \x05M\x06 characteristic of ‘-’, it can be set up on the battlefield but otherwise cannot be moved.","\x05Toughness (T)\x06: The model’s resilience against harm.","\x05Save (Sv)\x06: Presented as a dice result (e.g. 4+), this indicates the protection a model’s armour gives it.","\x05Invulnerable Save (InSv)\x06: Presented as a dice result (e.g. 4+). Some models are protected by esoteric means in addition to physical armour, such as force fields or preternatural reflexes. Not all models have an \x05InSv\x06 characteristic, but if they do, it will be listed here.","\x05Wounds (W)\x06: Wounds represent how much damage a model can sustain before it is \x05destroyed\x06. If a model’s wounds are reduced to 0 or fewer, that model is \x05destroyed\x06.","\x05Leadership (Ld)\x06: Presented as a dice result (e.g. 7+), this reveals how courageous, determined or self‑controlled a model is.","\x05Objective Control (OC)\x06: How effectively a model can control an \x05objective\x06 on the battlefield. If a model has an \x05OC\x06 characteristic of ‘-’ it is unable to control \x05objectives\x06 at all."],accordions:[{ref:"02.02.01",title:"Modifiers",text:["\x05WHAT ARE MODIFIERS?\x06","Many rules in the game modify a value, characteristic or roll elsewhere in the game. A rule that does so is known as a modifier. A value that has been changed is a modified rule (e.g. modified characteristic, modified roll, modified value, etc).","One of the most common ways for modifiers to be presented is as +1 or -1 to a characteristic, roll or value.","If the rule has +1 to a characteristic, it improves it by the value after the '+' symbol.","\x05Example:\x06 \x07'This weapon has +1 \x05AP\x06' would improve an \x05AP\x06 characteristic of -2 to -3.\b","If the rule has -1 to a characteristic, it worsens it by the value after the '-' symbol.","\x05Example:\x06 \x07'This unit has -1 \x05Sv\x06' would worsen a \x05Sv\x06 characteristic of 3+ to 4+.\b","\x05APPLYING MODIFIERS\x06","This section presents the various ways rules may be modified. All modifiers are cumulative.","When a value is modified (e.g. characteristic, dice roll, distance), do so in the following order.","\x051.\x06 If a rule instructs you to change or replace one value with a specified value, you must first change the relevant value to the new value.","Note that rules that modify a characteristic in this step to a new value of ‘0’, ‘-’ or ‘*’ cannot be modified by other rules (in such cases, skip steps 2-5).","\x052.\x06 Apply multiplication modifiers.","\x053.\x06 Apply addition modifiers.","\x054.\x06 Apply division modifiers.","\x055.\x06 Apply subtraction modifiers.","\x056.\x06 Round any fractions up after applying all modifiers.","\x05WHEN MODIFYING CHARACTERISTICS\x06","When modifying characteristics, unless otherwise stated, the following points also apply:","• Characteristics of ‘-’, ‘*’ and ‘N/A’ can never be modified.","• Rules that modify a model’s \x05WS\x06 and/or \x05BS\x06 characteristic modify the \x05WS\x06 and/or \x05BS\x06 characteristic of every weapon equipped by that model.","• After all modifiers have been applied:",'◦ \x05M\x06 cannot be less than 1".',"◦ \x05T\x06 cannot be less than 1.","◦ \x05Sv\x06 cannot be 1+ or better.","◦ \x05InSv\x06 cannot be 1+ or better.","◦ \x05Ld\x06 cannot be 4+ (or better) or 9+ (or worse).","◦ \x05OC\x06 cannot be less than 0 or '-'.",'◦ \x05Range\x06 characteristics cannot be less than 1".',"◦ \x05A\x06 cannot be less than 1.","◦ \x05WS\x06 cannot be 1+ (or better) or 7+ (or worse).","◦ \x05BS\x06 cannot be 1+ (or better) or 7+ (or worse).","◦ \x05S\x06 cannot be less than 1.","◦ \x05AP\x06 cannot be worse than 0.","◦ \x05D\x06 cannot be less than 1.","When these terms are used in rules, the affected characteristics are being modified, and the following points apply:","• \x05Improving WS, BS, Sv and Ld:\x06 When improving a \x05WS\x06, \x05BS\x06, \x05Sv\x06 or \x05Ld\x06 characteristic, subtract the appropriate amount from the number before the plus sign, e.g. improving a \x05WS\x06 of 3+ by 1 would result in a \x05WS\x06 of 2+.","• \x05Worsening WS, BS, Sv and Ld:\x06 When worsening a \x05WS\x06, \x05BS\x06, \x05Sv\x06 or \x05Ld\x06 characteristic, add the appropriate amount to the number before the plus sign, e.g. worsening a \x05WS\x06 of 3+ by 1 would result in a \x05WS\x06 of 4+.","• \x05Improving AP:\x06 When improving an Armour Penetration characteristic, subtract the appropriate amount from the characteristic, e.g. improving an \x05AP\x06 of -1 by 1 would result in an \x05AP\x06 of -2; improving an \x05AP\x06 of 0 by 1 would result in an \x05AP\x06 of -1.","• \x05Reducing or Worsening AP:\x06 When reducing or worsening an Armour Penetration characteristic, add the appropriate amount to the characteristic, to a maximum of 0, e.g. reducing/worsening an \x05AP\x06 of -1 by 1 would result in an \x05AP\x06 of 0; reducing /worsening an \x05AP\x06 of 0 by 1 would result in an \x05AP\x06 of 0.","• \x05Improving or Worsening Other Characteristics:\x06 When instructed to improve/worsen a characteristic that does not include a ‘+’ or ‘-’ symbol, add/subtract the specified amount to/from that characteristic (e.g. to improve a \x05S\x06 by 1, add 1 to it).","\x05WHEN MODIFYING DICE ROLLS\x06","When modifying dice rolls, the following points also apply:","• Modifiers are applied after any re-rolls of that dice roll.","◦ Rules that refer to the value of an ‘unmodified’ dice roll are referring to the dice result after any re-rolls, but before modifiers.","• A dice result can be modified above its maximum possible value (for example, a D6 roll can be modified above 6).","• A result that would be less than 1 is changed to a result of 1.","• \x05Hit rolls\x06 and \x05wound rolls\x06 can never be modified by more than -1 or +1. After all the cumulative modifiers to such a roll have been calculated, if the total modifier would be:","◦ -2 or worse, it is changed to -1.","◦ +2 or better, it is changed to +1.","• \x05Charge rolls\x06 cannot be greater than 12. After all the cumulative modifiers to a \x05charge roll\x06 have been calculated, if the result would be 13 or more, it is changed to 12.","\x05OTHER MODIFIED RULES\x06","The following rules apply to various rules and effects found throughout the game.",'• \x05Detection range\x06 and \x05Lone Operative\x06 cannot be better than 9" or worse than 30".',"A \x05stratagem\x06 cannot have its \x05CP\x06 increased by more than 1 or reduced to below 0 after all modifiers have been applied."]},{ref:"02.02.02",title:"Ignore Modifiers",text:["Some rules enable a player, weapon, model or unit to ignore modifiers. When using such rules, the following points apply:","Unless otherwise stated, that rule allows you to ignore modifiers to the unit's rolls and the unit's profile and weapon characteristics.","When a rule states you can ignore modifiers to a stated roll or characteristic, you can choose to ignore all of those modifiers, or only some of them. For example, you can still choose to apply positive/beneficial modifiers while ignoring negative/detrimental modifiers.",'\x05Example:\x06 \x07Your unit can ignore characteristic modifiers and is under the effect of +2" \x05M\x06 and -2" \x05M\x06. You can choose to ignore the -2" \x05M\x06, meaning that unit\'s \x05M\x06 characteristic will only be modified by the +2" \x05M\x06.\b',"\x05Example:\x06 \x07Your unit's ranged attacks can ignore roll modifiers and are under the effect of +1 to \x05hit rolls\x06 and -1 to \x05hit rolls\x06. You can choose to ignore the -1 to \x05hit rolls\x06, meaning those attacks will only be affected by the +1 to \x05hit rolls\x06.\b"]},{ref:"02.02.03",title:"Random Characteristics",text:["\x05Random Movement:\x06 When a unit with a random \x05M\x06 characteristic is \x05selected to move\x06, determine the entire unit’s move distance by rolling the indicated number of dice.","\x05Random Attacks:\x06 If a weapon has a random \x05A\x06 characteristic, that characteristic is determined when generating attacks for that weapon at the Resolve Attacks step (04.03). If several weapons with random \x05A\x06 characteristics are making \x05identical attacks\x06, generate the attacks for each of those weapons individually, and group them all together.","\x05Random Damage:\x06 If a weapon has a random \x05D\x06 characteristic, then each time an attack made with it inflicts damage, the controlling player determines that weapon's characteristic when the opposing player has selected a model in the target unit to allocate that attack to.","When determining a random \x05D\x06 characteristic, the dice roll made is called a \x05damage roll\x06.","Where a \x05D\x06 characteristic includes an operator (e.g. a ‘+’, as in D6+1), the value after the operator is part of that \x05D\x06 characteristic – it is not a modifier.","\x05Other Random Characteristics:\x06 For all other characteristics, roll to determine the value on an individual, per-model or per-weapon basis each time that characteristic is required."]},{ref:"02.02.04",title:"Healing Or Regaining Lost Wounds",text:["When a unit \x05heals\x06 or regains a number of wounds, it regains up to that number of lost wounds. For each wound healed or regained, consult the following:","• If that unit has one or more models that does not have its full wounds remaining, select one of those models; that model regains one lost wound.","• If all models in that unit have their starting number of wounds, but one or more models from that unit are currently destroyed, revive one of those destroyed models (excluding \x03Character\x04 models), with one wound remaining.","This cannot cause a model to have more wounds remaining than it started the battle with.","If a rule states that a model \x05heals\x06 or regains a number of wounds, only that model can regain wounds up to its starting number of wounds. Any excess regained wounds are lost and do not cause a \x05destroyed\x06 model from that unit to \x05revive\x06."]},{ref:"02.02.05",title:"Full Wounds Remaining",text:["A model has its full wounds remaining if it has the same number of wounds remaining as its \x05W\x06 characteristic."]},{ref:"02.02.06",title:"Characteristic Modifiers & Modified Characteristics",text:["See Modifiers (02.02.01)."]}]},{ref:"02.03",title:"Abilities",text:["Many units have abilities that may apply during the game. These will be described here."],accordions:[{ref:"02.03.01",title:"Rules With Multiple Conditions And Effects",text:["Some rules have multiple conditions, with the second, more specific condition conferring an improved rule, either instead of the first condition’s rule or as well as it. Such rules require both the first condition and the second condition to be satisfied for the improved rule to apply.","For example, an ability reads: ‘This unit's ranged attacks that target the closest eligible target can:","• Re-roll \x05hit rolls\x06 of 1.","• \x01Or:\x02If that target is within range of an \x05objective\x06 your opponent controls, re-roll \x05hit rolls\x06.’","In order for those attacks to re-roll \x05hit rolls\x06, that target must be both the closest eligible target and within range of an \x05objective\x06 your opponent controls."]}]},{ref:"02.04",title:"Weapons",text:["Weapons have the following characteristics:","\x05Range (R)\x06: How far ranged weapons can shoot. Weapons with an \x05R\x06characteristic of ‘Melee’ are melee weapons.","\x05Attacks (A)\x06: How many \x05attack dice\x06 are used each time that weapon is used.","\x05Ballistic Skill (BS)\x06: Presented as a dice result (e.g. 4+), this shows how accurate the bearer is when shooting with the relevant ranged weapon.","\x05Weapon Skill (WS)\x06: Presented as a dice result (e.g. 4+), this reflects the bearer’s skill in wielding the relevant melee weapon.","\x05Strength (S)\x06: The higher a weapon’s \x05S\x06 characteristic, the more likely it is to wound a foe.","\x05Armour Penetration (AP)\x06: Presented as a modifier to a dice roll (e.g. -1). The larger the modifier, the better the weapon is at cutting through the target’s defences.","\x05Damage (D)\x06: The amount of damage inflicted by an attack."],accordions:[{ref:"02.04.01",title:"Weapons With No Strength",text:["If a weapon has no \x05S\x06 characteristic (because it is '-', or for any other reason) and a rule interacts with that weapon's \x05S\x06, that weapon has \x05S\x06 1 for that interaction."]}]},{ref:"02.05",title:"Keywords",text:["Datasheets have a list of keywords, separated into faction keywords and other keywords. The former are used when deciding which models to include in your army, but otherwise both are functionally the same. Keywords appear in full capitals, in \x03KEYWORD BOLD\x04."],accordions:[{ref:"02.05.01",title:"Using Keywords & Mixed Keywords in Units",text:["When using keywords, the following points apply:","• A unit has all the keywords of all models in that unit. A model only has its own keywords.","• If a rule specifies that it applies to a unit with a keyword, it applies to a unit which includes one or more models with that keyword.","• If a rule specifies that it applies to a model with a keyword, it only applies to a model with that keyword.","• If a rule specifies that it applies to ‘non-\x03Keyword\x04’ models/units, it only applies to models/units that do not have that keyword. For example, if a rule applies to non-\x03Vehicle\x04 units, it only applies to units that do not have the \x03Vehicle\x04 keyword.","• Some units can contain models that have different keywords. While this is the case, such a unit is considered to have all of the keywords of all of its models, and so is affected by any rule that applies to units with any of those keywords. Remember that attacks are made against units, not models.","• If a rule only applies to models with a specific keyword, then it instead only applies to models in such a unit that have the correct keyword.","• A rule with a comma-separated list of keywords, or a series of keywords separated by slashes ('/'), or two keywords separated by the word ‘or’ (e.g. ‘an \x03Immortals\x04, \x03Deathmarks\x04 or \x03Lychguard\x04 unit’) refers to a model/unit that has any one of those keywords.","• A rule with multiple adjacent keywords (e.g. ‘an \x03Aeldari Guardians\x04 unit’) only refers to a model/unit that has all of those keywords.","• Some older rules use keywords without specifying model or unit: for example, \x03MONSTER/VEHICLE\x04 or \x03TRANSPORT\x04. These rules refer to units with those keywords.","• Singular and plural instances of the same keyword function in the same way."]}]},{ref:"02.06",title:"Unit Composition And Other Rules",text:["This section details the number and types of models in the unit. Each of those models will have one set of default wargear, which will be listed here. It may also list other rules, such as which units a \x05leader\x06 unit can join or which units can embark within a \x03TRANSPORT\x04."],accordions:[{ref:"02.06.01",title:"Bearer",text:["The bearer of a weapon, enhancement or item of wargear is the model equipped with it."]},{ref:"02.06.02",title:"Unit's Equipment",text:["When a rule refers to a unit’s equipment, it refers to all of the wargear equipped by models in that unit."]}]},{ref:"02.07",title:"Wargear options",text:["Some datasheets have a list of wargear options. When you include such a unit in your army, you can use these options to alter the weapons and other wargear its models have."]}]},{number:"03",title:"Moving",subsections:[{ref:"03.01",title:"Moving Units",text:["There are several types of move a unit can make. Each one defines which units are eligible to make it, what its \x05maximum distance\x06 or \x05set-up distance\x06 is, and any conditions that must be met.","Each time you move a unit, you can move one or more of its models, one at a time, by moving it in a straight line and/or rotating it, as many times as you want to.","Each time you move a model, unless otherwise stated:","• It can be moved through friendly models.","• It can be moved through any space its base can fit through.","• Its base cannot be moved through enemy models.","• Its base cannot cross the edge of the battlefield.","• All stated ‘While Moving’ conditions must be met.","\x05MOVING A MODEL IN A STRAIGHT LINE\x06","Each time you move a model in a straight line, move it horizontally across the battlefield. Measure from the same point on its base at the start and end of that move, and add that distance to any other distance it has moved since its unit began that move. The distance moved cannot be greater than the \x05maximum distance\x06 of that \x05move type\x06.","\x05ROTATING A MODEL\x06","Each time you rotate a model, turn it any amount around the centre of its base, while keeping it upright. Note that rotating a model does not count towards the distance it has moved.","\x05ENDING A MOVE\x06","After you have finished setting up all of the models in a unit and/or moving all of the models in a unit that you want to move, check that all of the following apply:","• If that unit is on the battlefield, it is in \x05coherency\x06 (03.03).","• No models in that unit are on another model or partway through a surface of a \x05terrain feature\x06 (e.g. a wall or ceiling).","• All stated ‘After Moving’ conditions are met.","If one or more of the above conditions are not met, that unit cannot make that move and its models are returned to their positions at the start of that move. Otherwise, after resolving any additional rules stated in the ‘After Moving’ section of that \x05move type\x06, that move ends.","\x0eMoving in a straight line",'Both models shown here can move a \x05\x07maximum distance\b\x06 of 6". They both move 3" in a straight line, then 3" in another straight line, for a total movement of 6".',"\x0eRotating",'1. This model can move a \x05\x07maximum distance\b\x06 of 12". It moves in a series of straight lines and rotations, as follows:','\x05\x07A)\b\x06 Moves 6" in a straight line',"\x05\x07B)\b\x06 Rotates",'\x05\x07C)\b\x06 Moves 6" in a straight line',"\x05\x07D)\b\x06 Rotates",'This model has moved a total of 12".',"2. Models without a base are rotated around their central axis (see Frame, \x0717.02\b)."],accordions:[{ref:"03.01.01",title:"Different Move Characteristics",text:["When making a \x05move type\x06 whose \x05maximum distance\x06 uses the unit's \x05M\x06 characteristic, if different models in the moving unit have different \x05M\x06 characteristics, the \x05maximum distance\x06 for that move will be different for those models.",'\x05Example:\x06 \x07If a unit makes a \x05normal move\x06 and all models in that unit have an \x05M\x06 characteristic of 6" except for one model with an \x05M\x06 characteristic of 9", that model’s \x05maximum distance\x06 for that move is 9", while the other models’ \x05maximum distance\x06 is 6". While that unit is making that move, all other restrictions must be met.\b']},{ref:"03.01.02",title:"Moving Over Or Through Models",text:["Some models have a rule that enables them to ‘move over models’, 'move through models' or ‘move over models as if they were not there’ when making a move. When moving a model with such a rule, it can make its move through enemy models, but must follow all other restrictions of the move they are making."]},{ref:"03.01.03",title:"Random Movement",text:["See Random Characteristics (02.02.03)"]},{ref:"03.01.04",title:"When Moving Up To",text:['Some rules allow a unit to make a stated <move type> of up to X". That stated distance is the \x05maximum distance\x06 for that move.']}]},{ref:"03.02",title:"Set Up",text:["Before your units can move and make attacks, they will first need to be set up on the battlefield. This most commonly happens when deploying your army for battle, but can happen for other reasons as well.","Whenever a rule instructs you to set up a unit, place its models on the battlefield so that:","• That unit is in \x05coherency\x06 (03.03).","• That unit is \x05unengaged\x06 (03.04).","• All other requirements and restrictions are met.","If you cannot set up all of the models in a unit, remove that unit from the battlefield and return it to its original position (e.g. in \x05strategic reserves\x06 or embarked within a \x03TRANSPORT\x04)"],accordions:[{ref:"03.02.01",title:"If You Cannot Set Up a Unit",text:["While having to set up a unit as the result of a \x05move type\x06, if you have to return a unit’s models to their previous positions because it is not possible to set them all up, that unit has not been \x05selected to move\x06. This means it can be \x05selected to move\x06 later, so could either attempt another set up or \x05remain stationary\x06 (09.04)."]},{ref:"03.02.02",title:"Setting Up Large Models",text:["If a model cannot meet all of its set up restrictions because it is too large, consult the relevant section below:","\x05During Deployment:\x06 If a model is so large that its base cannot physically be set up wholly within your deployment zone, it must be set up so that it is touching your battlefield edge. During a turn in which such a large model is set up on the battlefield, that model’s unit cannot do any of the following:","• Make a \x05normal/advance/fall-back/charge move\x06.","• Make any attacks with ranged weapons.","Some large models, typically \x03Aircraft\x04, have wings and other parts that extend significantly beyond their base. Such models can overhang a deployment zone if it is not possible to set them up otherwise, but when setting them up, their base must still be wholly within that deployment zone.","\x05From Strategic Reserves:\x06 If a model is so large that its base cannot physically be set up wholly within the distance required of the battlefield edge, it must be set up so that it is touching a battlefield edge. During a turn in which such a large model is set up on the battlefield (excluding \x03AIRCRAFT\x04 models), that model’s unit cannot do any of the following:","normal/advance/fall-back/charge move.","Make any attacks with ranged weapons.",'Some large models, typically \x03Aircraft\x04, have wings and other parts that extend significantly beyond their base. Such models can overhang a battlefield edge if it is not possible to set them up otherwise, but when setting them up, they must still be more than 8" away from all enemy units.','\x05Disembarking from a Transport:\x06 When a unit disembarks from a \x03Transport\x04, it must be set up wholly within 3" of that model. If a disembarking model is so large that it is not possible to set it up wholly within 3" (typically because it is itself larger than 3" in all directions), set that model up with its base within 1" of that \x03Transport\x04’s base (or hull), and not \x05engaged\x06 with any enemy units.']},{ref:"03.02.03",title:"Redeployments",text:["When a player uses a rule that lets them redeploy their unit, they remove that unit from the battlefield, then deploy it again using all the normal rules (e.g. if all the models in the redeploying unit have the Infiltrators ability, that unit can be set up using that ability)."]}]},{ref:"03.03",title:"Coherency",text:["A unit that contains more than one model must be set up and end any kind of move in \x05coherency\x06. A unit is in \x05coherency\x06 while \x01both\x02 of the following apply to \x01every\x02 model in that unit:",'• Within \x012" horizontally\x02 and 5" vertically of \x01at least one other model\x02 in that unit.','• Within \x019" horizontally\x02 and 5" vertically of \x01every other model\x02in that unit.',"\x05REGAINING COHERENCY\x06","In the End of Turn step of each player’s turn, if one or more units on the battlefield are not in \x05coherency\x06, those units’ controlling players must remove models from them, one at a time, until they are in \x05coherency\x06 again. Models removed in this way are \x05destroyed\x06, but they do not trigger rules that apply when a model is \x05destroyed\x06."],accordions:[{ref:"03.03.01",title:"What Is Coherency",text:["\x05Coherency\x06 prevents models in the same unit from becoming too separated from each other while on the battlefield, ensuring they are set up and end every kind of move as a single group."]}]},{ref:"03.04",title:"Engagement",text:['A model’s \x05engagement range\x06 is the area of the battlefield within 2" horizontally and 5" vertically of it.',"• While a friendly model is within \x05engagement range\x06 of one or more enemy models, those models – and the units they belong to – are \x05engaged\x06 with each other.","• While a unit contains no \x05engaged models\x06, that unit is \x05unengaged\x06.","\x0eCoherency",'Every model in this unit is within 2" of at least one other model in its unit, and every model is within 9" of every other model in its unit. This unit is therefore in \x05\x07coherency\b\x06.',"\x0eEngagement",'These two units have at least one model within 2" of the opposing unit, and are therefore \x05\x07engaged\b\x06 with each other.'],accordions:[{ref:"03.04.01",title:"What Is Engagement",text:["While opposing models are within each other’s \x05engagement range\x06, they are able to fight in vicious melee, so unless they are seeking to make melee attacks, models should keep out of their foes’ reach."]}]}]},{number:"04",title:"Making Attacks",subsections:[{ref:"04.00",title:"Making Attacks",text:["During the battle, your units will shoot at and fight the enemy, making attacks with their weapons each time they do so. This section explains how to make attacks with your models.","Each time a unit shoots or fights, the active player follows these steps:","1. SELECT WEAPONS (04.01)","2. SELECT TARGETS (04.02)","3. RESOLVE ATTACKS (04.03)"]},{ref:"04.01",title:"Select Weapons",text:["For each model in the attacking unit, select which weapons that model will make attacks with. Models make ranged attacks with ranged weapons, and make melee attacks with melee weapons.","\x05WHILE SHOOTING\x06","You can select one or more ranged weapons that model has.","\x05WHILE FIGHTING\x06","You must select \x01one\x02 melee weapon that model has."],accordions:[{ref:"04.01.01",title:"Models Without Ranged/Melee Weapons",text:["A model that does not have any ranged weapons cannot make ranged attacks, and a model that does not have any melee weapons cannot make melee attacks."]},{ref:"04.01.02",title:"Sidearms",text:["Some models are equipped with \x03[CLOSE-QUARTERS]\x04 weapons in addition to other firearms. Such models can be an exception to the rules in this section, as you may not be able to select all of their weapons to make attacks with."]},{ref:"04.01.03",title:"Multiple Weapon Profiles",text:["In the \x05select weapons\x06 step(4.01), if a selected weapon has more than one profile, then the controlling player must also select one of those profiles. The selected profile is then used in the Resolve Attacks step (04.03).","Some of these profiles are known as \x05Hunter\x06 profiles. \x05Hunter\x06 profiles can only target units with the specified keywords.","Note that if a unit is equipped with more than one such weapon, a different profile can be selected for each model within that unit."]},{ref:"04.01.04",title:"Attack Characteristics and Abilities",text:["When making an attack, that attack is considered to have the same characteristics and abilities as the weapon making that attack.","If any modifiers or abilities apply to an attack, those changes apply to the weapon making that attack until that unit's attack sequence and all effects of those abilities (e.g. \x03[Hazardous]\x04) have been resolved.","Rules that apply to a weapon that modify rolls apply to the attacks made with that weapon."]},{ref:"04.01.05",title:"Selected to Attack",text:["Some rules use the term \x05selected to attack\x06. If a unit is \x05selected to fight\x06, \x05selected to shoot\x06 or chosen to make attacks, that unit is \x05selected to attack\x06."]}]},{ref:"04.02",title:"Select Targets",text:["For each weapon selected:","\x05WHILE SHOOTING\x06","Select \x01one\x02 enemy unit to be the target of that weapon. Unless otherwise stated, each target must be:","• \x05Visible\x06 to the model that has that weapon (06.01).","• Within range of that weapon.","• \x05Unengaged.\x06","\x05WHILE FIGHTING\x06","Select one or more enemy units to be the targets of that weapon:","• Each target must be \x05engaged\x06 with the model that has that weapon.","• You cannot select more targets than that weapon’s \x05A\x06 characteristic."],accordions:[{ref:"04.02.01",title:"Selecting Targets",text:["When shooting or fighting, you can select different targets for each weapon. If you cannot select a target for a weapon, or if you choose not to select a target for a ranged weapon, the model with that weapon will not make attacks with it."]},{ref:"04.02.02",title:"Against An Attack",text:["Rules that are triggered 'against' certain attacks are triggered after the attacking unit has completed the Select Targets step (04.02), provided all other qualifiers are met (e.g. concerning the characteristics of the attacking unit or its weapons).","Rules that are triggered when an attack is 'allocated' to a unit are triggered in step 1 of the Inflict Damage step (05.04)."]},{ref:"04.02.03",title:"Single Target",text:["When a model or unit attacks with one or more weapons, if all of the attacks made with those weapons target the same unit, that model or unit is said to be shooting at, fighting or targeting a single target."]}]},{ref:"04.03",title:"Resolve Attacks",text:["Resolve attacks using the following sequence:","\x051.  Select Enemy Unit:\x06 Select one of the enemy units targeted by one or more weapons.","\x052.  Gather Attack Dice:\x06 Select one weapon targeting that unit that has not yet been used to make attacks against it, and gather a number of D6 equal to that weapon’s \x05A\x06 characteristic. These are \x05attack dice\x06 – each one represents one attack being made by an attacking model with that weapon.","If one or more other weapons targeting that unit make \x05identical attacks\x06 (04.03.01) to the selected weapon and those weapons have not yet been used to make attacks against that target, they do so now and you gather those weapons’ \x05attack dice\x06 as well (e.g. for three weapons making \x05identical attacks\x06, each with an \x05A\x06 characteristic of 2, gather a total of six D6).","\x053.  Resolve Attack Dice:\x06 Resolve the attack sequence (05) for all of the attack dice you just gathered.","\x054.  Other Attacks:\x06 Follow the first of the instructions below that applies:","• If there are any weapons targeting the same unit that have not yet been used to make attacks, return to the Gather Attack Dice step.","• Otherwise, if there are any weapons with unresolved attacks targeting a different unit, return to the Select Enemy Unit step.","• Otherwise, if all weapons have been used to make all of their attacks, this sequence ends and the attacking unit’s attacks have been resolved."],accordions:[{ref:"04.03.01",title:"Identical Attacks",text:["Identical attacks are those that have the same \x05BS\x06/\x05WS\x06, \x05S\x06, \x05AP\x06 and \x05D\x06 characteristics, and which are affected by the same applicable abilities and rules."]},{ref:"04.03.02",title:"Splitting Melee Attacks",text:["While selecting targets, if you select more than one unit as the target of a melee weapon, you must split that weapon’s attacks between those target units. To do so, declare how many of that weapon’s attacks will be made against each unit (you must declare at least one attack per unit targeted).","In the Gather Attack Dice step, for each weapon that is splitting its attacks, only gather a number of \x05attack dice\x06 for that weapon equal to the number of attacks you declared would be made against that target with that weapon."]},{ref:"04.03.03",title:"Target No Longer Eligible Or Viable",text:["If a unit that was an eligible target for a rule or attack when it was selected stops being an eligible target (for example, because a rule enables it to make an out-of-phase move that takes it out of range), the controlling player can select new targets."]},{ref:"04.03.04",title:"Shot",text:["When all of the attacks made with a ranged weapon have been resolved, that weapon has shot.","When all of a model’s ranged weapons have shot, that model has shot.","When all models in a unit that are making ranged attacks have resolved all of those attacks, that unit has shot.","If a unit was selected to shoot and none of the models in it make any attacks, it has not shot."]},{ref:"04.03.05",title:"Fought",text:["When all of the attacks made with a melee weapon have been resolved, that weapon has fought.","When all of a model’s selected melee weapons have fought, that model has fought.","When all models in a unit that are making melee attacks have resolved all of those attacks, that unit has fought.","If a unit was selected to fight and none of the models in it make any attacks, it has not fought."]},{ref:"04.03.06",title:"Finished Making Its Attacks",text:["When all of an attacking unit’s attacks have been resolved, it has finished making its attacks, and that unit has attacked."]}]}]},{number:"05",title:"Attack Sequence",subsections:[{ref:"05.00",title:"Attack Sequence",text:["Whenever models make attacks, you will follow the sequence detailed in this section to find out if they inflict damage.","Each time the active player is instructed to resolve the attack sequence, they follow the steps below. In each step, if there is more than one dice to roll, make all of those rolls simultaneously.","1. HIT ROLLS","2. WOUND ROLLS","3. SAVE ROLLS","4. INFLICT DAMAGE","If an attack fails or inflicts damage, this sequence ends for that attack. When all attacks have either failed or inflicted damage, this sequence ends and those attacks have been resolved."]},{ref:"05.01",title:"Hit Rolls",text:["Make one \x05hit roll\x06 for each \x05attack dice\x06 by rolling one D6. For each result, check if it fails or is a hit by matching the first condition below that applies:"],tables:[{rows:[["Unmodified 1","FAILS"],["Unmodified 6","CRITICAL HIT"],["Equal to or greater than that attack’s \x05BS\x06/\x05WS\x06 characteristic","HIT"],["Any other result","FAILS"]]}],accordions:[{ref:"05.01.01",title:"Critical Hits and Critical Wounds",text:["\x05Critical hits\x06 are still hits, and \x05critical wounds\x06 are still wounds. In addition, other rules can be triggered by a \x05critical hit\x06 or a \x05critical wound\x06, such as \x03[LETHAL HITS]\x04 and \x03[DEVASTATING WOUNDS]\x04 (24)."]}]},{ref:"05.02",title:"Wound Rolls",text:["Make one \x05wound roll\x06 for each hit by rolling one D6. For each result, check if it fails or is a wound by matching the first condition below that applies:"],tables:[{rows:[["Unmodified 1","FAILS"],["Unmodified 6","CRITICAL WOUND"],["Equal to or greater than required result below","WOUND"],["ATTACK'S STRENGTH VS TARGET'S TOUGHNESS","REQUIRED RESULT"],["Strength is \x05TWICE (or more than twice)\x06 the Toughness","2+"],["Strength is \x05GREATER\x06 than the Toughness","3+"],["Strength is \x05EQUAL\x06 to the Toughness","4+"],["Strength is \x05LESS\x06 than the Toughness","5+"],["Strength is \x05HALF (or less than half)\x06 the Toughness","6+"],["Any other result","FAILS"]]}],accordions:[{ref:"05.02.01",title:"Multiple Toughness Characteristics",text:["When resolving attacks that target a unit in which the models have two or more different \x05T\x06 characteristics, follow the first instruction that applies from below:","• If the target unit is an \x05attached unit\x06, use the highest \x05T\x06 characteristic amongst \x05bodyguard\x06 models in that unit that are on the battlefield.","• Use the highest \x05T\x06 characteristic amongst models in that unit that are on the battlefield."]}]},{ref:"05.03",title:"Save Rolls",text:["The opposing player resolves the following sequence:","\x051. Create Groups:\x06 Divide all models in the target unit into the following groups, as many times as required:","• One group for each \x03CHARACTER\x04 model.","• One group for all other models with the same \x05W\x06, \x05Sv\x06 and \x05InSv\x06 characteristics.","\x052. Allocation Order:\x06 Declare the order in which those groups will have attacks allocated to them, applying \x01all\x02 of the following:","• If a non-\x03CHARACTER\x04 group contains a model that has lost one or more wounds, that group must be first in the allocation order.","• No \x03CHARACTER\x04 group can be earlier in the allocation order than a non-\x03CHARACTER\x04 group.","• \x03CHARACTER\x04 groups containing a model that has lost one or more wounds must be earlier in the allocation order than \x03CHARACTER\x04 groups containing no wounded models.","\x053. Make Save Rolls:\x06 The opposing player makes one \x05save roll\x06 for each attack that wounded the target by rolling one D6."],accordions:[{ref:"05.03.01",title:"Saving Throw",text:["The term 'saving throw' is the same as \x05save roll\x06."]},{ref:"05.03.02",title:"Attacks Modified during Hit and Wound rolls",text:["Some attacks may be modified as a result of the values of \x05hit/wound rolls\x06 made for those attacks. When this happens, split those attacks into attack pools based on their new identical attack profiles. The active player can decide which attack pool to resolve first for steps 5.3 and 5.4. Once those steps have been completed for that attack pool, the active player can decide the next pool to resolve and repeat until all new attack pools are resolved."]}]},{ref:"05.04",title:"Inflict Damage",text:["The opposing player resolves the following sequence for each \x05save roll\x06, working from lowest result(s) to highest result(s), until all attacks are resolved or all models in the target unit are \x05destroyed\x06 – in the latter case, any excess attacks are lost.","\x051. Select Model:\x06 Select one model in the current allocation group (5.4.1); this must be a model that has lost one or more wounds if possible.","\x052. Check Save Roll:\x06 For each result, check if that attack inflicts damage or fails by matching the first condition below that applies:","\x053. Resolve Damage:\x06 If that attack inflicts damage, the selected model loses a number of wounds equal to that attack’s \x05D\x06 characteristic. If this reduces that model’s remaining wounds to 0 or fewer, it is \x05destroyed\x06.","\x05Example:\x06\x07An \x05AP\x06 characteristic of -1 would modify a \x05save roll\x06 of 3 to a 2. For models with a \x05Sv\x06 characteristic of 2+ or better, that attack would fail.\b","\x0eMaking Attacks","1. Select Weapons","The RED unit is attacking. The following weapons are selected to make attacks with:","2 boltguns \x05\x07(A)\b\x06","2 bolt pistols \x05\x07(B)\b\x06","1 heavy bolter \x05\x07(C)\b\x06","2. Select Targets","The BLUE unit is selected as the target. The unit is \x05\x07visible\b\x06 to all models in the attacking unit. All of the selected weapons are in range, with the exception of one bolt pistol. As a result, that weapon will not make any attacks.","3. Resolve Attacks","There is only one enemy unit being targeted, so the controlling player now gathers \x05\x07attack dice\b\x06:","• Five \x05\x07attack dice\b\x06 are gathered for the boltguns and bolt pistol, which have \x05\x07A\b\x06 characteristics of 2 and 1 respectively and all make \x05\x07identical attacks\b\x06.","• Three \x05\x07attack dice\b\x06 are gathered for the heavy bolter, which has an \x05\x07A\b\x06 characteristic of 3 but does not make \x05\x07identical attacks\b\x06.","\x0eResolving attack dice","1. Hit rolls","The controlling player chooses to make the five \x05\x07hit rolls\b\x06 for the boltguns (A) and bolt pistol (B) first. The \x05\x07BS\b\x06 characteristic of the weapons is 3+. Four of the attacks hit the target.","2. Wound rolls","The controlling player makes four \x05\x07wound rolls\b\x06. The weapons have an \x05\x07S\b\x06 characteristic of 4 and the target unit has a \x05\x07T\b\x06 characteristic of 3, so rolls of 3+ are required to wound. Three of the attacks wound the target.","3. Save rolls","The target unit’s controlling player makes three \x05\x07save rolls\b\x06.","4. inflict damage","• The lowest result is less than both the \x05\x07InSv\b\x06 and \x05\x07Sv\b\x06 characteristics of the target, so that attack inflicts damage. This reduces the model to which that attack was allocated to 0 wounds, which \x05\x07destroys\b\x06 it.","• The next lowest result is less than the target’s \x05\x07InSv\b\x06 characteristic, but greater than its \x05\x07Sv\b\x06 characteristic of 3+; that attack fails.","• The other result is greater than the target’s \x05\x07InSv\b\x06 characteristic of 5+; that attack also fails.","\x0eResolving other Attacks","1. Hit rolls","The controlling player then makes three \x05\x07hit rolls\b\x06 for the heavy bolter (C). The \x05\x07BS\b\x06 characteristic of the weapon is 4+. Two of the attacks hit the target.","2. Wound rolls","The controlling player makes two \x05\x07wound rolls\b\x06. The weapon has an \x05\x07S\b\x06 characteristic of 5, so rolls of 3+ are required to wound. Both attacks wound the target.","3. Save rolls","The target unit’s controlling player makes two \x05\x07save rolls\b\x06.","4. inflict damage","• The lowest result, \x01*when modified by the attacking weapon’s*\x02\x01\x05\x07 AP\b\x06\x02 \x01*characteristic of -1*\x02, is less than the target’s \x05\x07Sv\b\x06 characteristic of 3+, so that attack inflicts damage. This reduces the model to which that attack was allocated to 0 wounds, which \x05\x07destroys\b\x06 it.","• The other result is equal to the target’s \x05\x07InSv\b\x06 characteristic of 5+; that attack fails.","\x0eAttacking attached Units","1. Select Weapons","The RED unit is attacking. The following weapons are selected to make attacks with:","7 boltguns \x05\x07(A)\b\x06","1 plasma pistol \x05\x07(B)\b\x06","2 heavy bolters \x05\x07(C)\b\x06","2. Select Targets","The BLUE unit is selected as the target. It is an \x05\x07attached unit\b\x06 (\x0719\b) formed from a Seraphim unit and Saint Celestine (with her two Geminae Superia). The unit is \x05\x07visible\b\x06 to all models in the attacking unit, and all of the selected weapons are in range.","3. resolve attacks","There is only one enemy unit being targeted, so the controlling player now gathers \x05\x07attack dice\b\x06. They decide to resolve the heavy bolter attacks first, which each have an \x05\x07A\b\x06 characteristic of 3, so six \x05\x07attack dice\b\x06 are gathered.","The \x05\x07attack dice\b\x06 for the remaining weapons will be gathered once the heavy bolter attacks are resolved (see opposite), as follows:","• 14 \x05\x07attack dice\b\x06 for the boltguns, which each have an \x05\x07A\b\x06 characteristic of 2.","• One \x05\x07attack dice\b\x06 for the plasma pistol, which has an \x05\x07A\b\x06 characteristic of 1.","\x0eAllocation groups","1. Create groups and Declare Order","The target unit’s controlling player divides it into groups: one containing Saint Celestine, one containing the Geminae Superia, and one containing the Seraphim. They then declare the allocation order, choosing the Geminae Superia first \x05\x07(E)\b\x06, hoping their better \x05\x07Sv\b\x06 and \x05\x07InSv\b\x06 characteristics will weather the attacks. The Seraphim must be chosen second \x05\x07(D)\b\x06, as Saint Celestine is a \x03Character\x04 model so must be last in the order \x05\x07(F)\b\x06.","2. resolve attack dice","The heavy bolters’ attacks wound the target five times, so the target unit’s controlling player makes five \x05\x07save rolls\b\x06.","The attacks are resolved one at a time, from lowest \x05\x07save rolls\b\x06 to highest:","• The two results of 1 are allocated first, to the current allocation group (the Geminae Superia). They both inflict damage, and both Geminae Superia are \x05\x07destroyed\b\x06.","• The result of 3 is now allocated to the Seraphim, who have become the current allocation group. \x01*When modified by the attacking weapon’s*\x02\x01\x05\x07 AP\b\x06\x02 \x01*characteristic of -1*\x02, this also inflicts damage, \x05\x07destroying\b\x06 one Seraphim model.","• The remaining attacks fail, so no further damage is inflicted.","3. Select next group of attack dice and repeat"],tables:[{rows:[["Unmodified 1","INFLICTS DAMAGE"],["\x05Invulnerable Save:\x06 The models in the current allocation group have an \x05InSv\x06 characteristics, and the result is equal to or greater than that characteristic.","FAILS"],["\x05Save and AP:\x06 After modifying the result by the attacking weapon's \x05AP\x06 characteristic, it is equal to or greater than the \x05Sv\x06 characteristic of model in the current allocation group.","FAILS"],["Any other result","INFLICTS DAMAGE"]]}],accordions:[{ref:"05.04.01",title:"Current Allocation Group",text:["The first group in the allocation order begins as the current group. Once all models in an allocation group are \x05destroyed\x06, the next group in the allocation order becomes the current one."]},{ref:"05.04.02",title:"Modifying Damage",text:["See Modifiers (02.02.01)."]},{ref:"05.04.03",title:"Suffers Damage",text:["If an attack reaches the Resolve Damage step of the attack sequence (05.04), the model that attack was allocated to has suffered damage, even if that model subsequently uses a rule to ignore the wounds inflicted or it uses a rule that means those wounds are not lost."]},{ref:"05.04.04",title:"Destroyed",text:["Throughout a battle, models will suffer damage, lose wounds and be \x05destroyed\x06. When every model in a unit has been \x05destroyed\x06, that unit is \x05destroyed\x06.","When a model is \x05destroyed\x06, first resolve any rules that are triggered when it is \x05destroyed\x06, then it is removed from the battlefield. If any such rules apply, and if the model was \x05destroyed\x06 as the result of an attack, unless otherwise stated, those rules are only resolved and that model is only removed after the attacking unit’s attacks have been resolved. Unless otherwise stated, \x05destroyed\x06 models and units cannot use abilities or be selected or targeted by rules.","Some rules only trigger if an enemy model or unit was \x05destroyed\x06 by you, or by a model or unit from your army. This means that the enemy model or unit was \x05destroyed\x06 by an attack made by a model from your army, or by a player rule you have. Enemy models or units that are \x05destroyed\x06 by any other means are not \x05destroyed\x06 by you, or by a model or unit from your army."]},{ref:"05.04.05",title:"Fight On Death",text:["Some rules enable models to attack after they have been \x05destroyed\x06. When a model under such an effect is \x05destroyed\x06, do not remove it from play.","Those models will stay on the battlefield until their unit is \x05selected to attack\x06 and has attacked, or until the end of the phase (whichever comes first). Any rules triggered by those models being \x05destroyed\x06 are resolved, and then those \x05destroyed\x06 models are removed.","If a rule instructs a \x05destroyed\x06 model to fight immediately after the attacking unit, instead that model is not removed from the battlefield until that model's unit has fought, or until the end of the phase (whichever comes first). This allows the models in the unit to fight all at once, and \x05stratagems\x06 that target that unit will also affect that \x05destroyed\x06 model."]},{ref:"05.04.06",title:"Measuring To A Destroyed Model Or Unit",text:["When a player has to measure the distance to a \x05destroyed\x06 model, that player can measure to any point occupied by that model’s base (or any part of that model if it does not have a base or is a \x03Vehicle\x04, excluding \x03Walker\x04 models that have a base) before it was \x05destroyed\x06.","When a player has to measure the distance to a \x05destroyed\x06 unit, they measure to the last model \x05destroyed\x06 in that unit."]}]}]},{number:"06",title:"Other Concepts",subsections:[{ref:"06.01",title:"Visibility",text:["\x05Line of sight\x06 is used to determine visibility between models. For an observing model to have \x05line of sight\x06, it must be possible to draw an imaginary straight line, 1 mm wide, from any part of that model to any part of the model being observed. This line is the \x05line of sight\x06. While doing so, other models in the observing model’s unit and in the observed model’s unit are ignored. Other models and units can be either \x05visible\x06 or \x05fully visible\x06 to the observing model, as shown in the example. Note that terrain applies additional rules to visibility (13.07).","\x0eModel Visible","If any part of another model is \x05\x07visible\b\x06 to the observing model, that model is \x05\x07visible\b\x06.","\x0eModel Fully Visible","If every part of another model that is facing the observing model is \x05\x07visible\b\x06 to the observing model (so the only thing blocking visibility to any part of that other model is that model itself), that model is \x05\x07fully visible\b\x06.","\x0eUnit Visible","If one or more models in a unit are \x05\x07visible\b\x06 to the observing model, that unit is \x05\x07visible\b\x06.","\x0eUnit Fully Visible","If every model in a unit is \x05\x07fully visible\b\x06 to the observing model, that unit is \x05\x07fully visible\b\x06. When determining this, the observing model can see through other models in that unit."],accordions:[{ref:"06.01.01",title:"Describing Visible Units",text:["When a rule references a \x05visible\x06 unit but does not state which units that unit must be \x05visible\x06 to, it must be \x05visible\x06 to the unit that is using that rule.","\x05Example:\x06 \x07You target a friendly unit with a \x05stratagem\x06 that says 'select one \x05visible\x06 enemy unit'. That enemy unit must be \x05visible\x06 to the friendly unit you targeted with the \x05stratagem\x06.\b"]}]},{ref:"06.02",title:"Mortal Wounds",text:["Some attacks or rules inflict \x05mortal wounds\x06 on units. Each time a unit suffers one or more \x05mortal wounds\x06, its controlling player must resolve the following sequence for each of those \x05mortal wounds\x06, until either all of them have been inflicted or that unit is \x05destroyed\x06:","\x051. Select Model\x06: Select one model in that unit by following the first instruction below that applies:","• If a non‑\x03CHARACTER\x04 model in that unit has lost one or more wounds, you must select that model.","• Otherwise, if that unit contains one or more non‑\x03CHARACTER\x04 models, you must select one of those models.","• Otherwise, if one or more \x03CHARACTER\x04 models in that unit have lost one or more wounds, you must select one of those models.","• Otherwise, you must select one \x03CHARACTER\x04 model in that unit.","\x052. Resolve Damage\x06: The selected model loses 1 wound. If this reduces that model’s remaining wounds to 0, it is destroyed.","\x05MORTAL WOUNDS AND NORMAL DAMAGE\x06","When resolving \x05attack dice\x06, if those attacks inflict a mixture of both \x05mortal wounds\x06 and normal damage, resolve all of the normal damage first, then resolve all of the \x05mortal wounds\x06."],accordions:[{ref:"06.02.01",title:"Normal Damage",text:["Normal Damage is damage that was inflicted on a model as a result of a weapon’s \x05D\x06 characteristic, rather than by other means such as \x05mortal wounds\x06. \x05Mortal wounds\x06 dealt in addition to normal damage from an attack are part of that same attack."]}]},{ref:"06.03",title:"Hazard Rolls",text:["To make a \x05hazard roll\x06 for a unit, roll one D6: on a 1-2, that roll fails and that unit suffers:","• 1 \x05mortal wound\x06 (06.02)","• Or 3 \x05mortal wounds\x06 instead if each model in that unit is a \x03MONSTER/VEHICLE model\x04.","If more than one \x05hazard roll\x06 is required for a unit, make all of those rolls simultaneously."],accordions:[{ref:"06.03.01",title:"Hazardous Test",text:["The term 'Hazardous test' is the same as \x05hazard roll\x06."]}]}]},{number:"07",title:"The Battle Round",subsections:[{ref:"07.00",title:"The Battle Round",text:["Games of Warhammer 40,000 are played in a series of battle rounds. This section describes the structure of the battle round, defining the order in which players take turns to move their units and make attacks with them.","Each battle round is resolved by following these steps:","1. START OF BATTLE ROUND","2. PLAYER TURNS","3. END OF BATTLE ROUND"]},{ref:"07.01",title:"Start Of Battle Round",text:["At the start of the battle round, players resolve rules that are triggered at the start of the battle round, before progressing to player turns."]},{ref:"07.02",title:"Player Turns",text:["Both players now take one turn each. The same player always takes the first turn in each battle round – the mission you are playing will tell you which player this is. Once that player’s turn has ended, their opponent takes their turn.","Each turn consists of seven parts: first the Start of Turn step, then a series of five phases resolved in the order shown below, then the End of Turn step.","\x051. Start of Turn Step:\x06 Rules that are triggered at the start of a turn are resolved now.","\x052. Command Phase:\x06 You marshal strategic resources and check your units’ morale.","\x053. Movement Phase:\x06 Your units move across the battlefield and strategic reserves arrive.","\x054. Shooting Phase:\x06 Your units make attacks with their ranged weapons.","\x055. Charge Phase:\x06 Your units make charge moves to engage the enemy.","\x056. Fight Phase:\x06 Both player's units make attacks with their melee weapons.","\x057. End of Turn Step:\x06 Rules that are triggered at the end of a turn are resolved now, in the following order:","\x051.\x06 First resolve rules triggered at this point other than mission rules.","\x052.\x06 Both players then consult their mission; if one or both players have achieved any aspects of their mission that are triggered at this point, resolve them now."],accordions:[{ref:"07.02.01",title:"Out Of Phase Rules",text:["Some rules allow a model or unit to make a move, shoot, declare a charge or fight outside of the normal turn sequence.","When using these out-of-phase rules, you cannot use any other ‘phase-locked’ rules; that is, any other rule that explicitly states the phase in which that rule applies.","\x05Example\x06: \x07In your opponent’s Movement phase, you target a friendly unit with the Fire Overwatch \x05stratagem\x06. That unit has an ability which is used ‘In your Shooting phase, after this unit has shot’. Because Fire Overwatch is phase-locked to your opponent's Shooting phase, that ability is not triggered.\b"]},{ref:"07.02.02",title:"Battle Round/Turn/Phase Definitions",text:["• \x05Start of Battle Round/Turn/Phase:\x06 If a rule is triggered at the start of the battle round/turn/phase, it is triggered at the start of every battle round/turn/phase.","• \x05The Turn/the Phase:\x06 If a rule is triggered during \x01the\x02 turn/phase instead of during \x01your\x02 turn/phase or \x01your opponent’s\x02 turn/phase, it is triggered in both players’ turn/phase.","\x05Example\x06: \x07If a rule states ‘At the end of the Movement phase, this model \x05heals\x06 1 wound’, that rule triggers at the end of your Movement phase and at the end of your opponent’s Movement phase.\b"]}]},{ref:"07.03",title:"End Of Battle Round",text:["Rules that are triggered at the end of the battle round are resolved now, in the following order:","1. First resolve rules triggered at this point other than mission rules.","2. Both players then consult their mission; if one or both players have achieved any aspects of their mission that are triggered at this point, resolve them now.","The battle round then ends and, unless the battle ends, the next battle round starts. The mission you are playing will tell you how many battle rounds to resolve before the battle ends."]}]},{number:"08",title:"Command Phase",subsections:[{ref:"08.00",title:"Command Phase",text:["In the Command phase, both players gain Core CP, then you check the combat readiness of your forces and use any strategic-level abilities you may have.","The Command phase is resolved by following these steps:","1. START OF COMMAND PHASE","2. GAIN CORE CP","3. BATTLE-SHOCK","4. COMMAND ABILITIES","5. END OF COMMAND PHASE"]},{ref:"08.01",title:"Start of Command Phase",text:["Rules that are triggered at the start of the Command phase are resolved now."]},{ref:"08.02",title:"Gain Core CP",text:["Both players gain 1 Command Point (CP)."],accordions:[{ref:"08.02.01",title:"Command Points",text:["Command Points are a valuable resource you can spend to use \x05stratagems\x06 (15). The Gain Core CP step ensures that both players gain 1CP each turn. While these are termed Core CP here, they are Command Points like any other. Other rules sometimes mention ‘Core CP’ when referring to these Command Points"]}]},{ref:"08.03",title:"Battle-Shock Step",text:["The active player must now make one \x05battle-shock roll\x06 (01.07) for each unit in their army that fulfils one or both of the following conditions:","• That unit is currently \x05battle-shocked\x06.","• That unit is at, or below, \x05half‑strength\x06.","If a unit was \x05battle-shocked\x06 at the start of this step and its \x05battle-shock roll\x06 during this step succeeds, it is no longer \x05battle-shocked\x06.","\x0eBattle-shock Examples","This unit has a \x05\x07starting strength\b\x06 of 3 so is not at or \x05\x07below\b\x06 \x05\x07half-strength\b\x06, but it is currently \x05\x07battle-shocked\b\x06, so a \x05\x07battle-shock roll\b\x06 must be made for it. If that roll succeeds, the unit will no longer be \x05\x07battle-shocked\b\x06.","This unit has a \x05\x07starting strength\b\x06 of 10. It has five models remaining, so it is \x05\x07at half-strength\b\x06 and a \x05\x07battle-shock roll\b\x06 must be made for it.","This unit has a \x05\x07starting strength\b\x06 of 5. It has two models remaining, so it is \x05\x07below half-strength\b\x06 and a \x05\x07battle-shock roll\b\x06 must be made for it.","This \x03Vehicle\x04 has a \x05\x07starting strength\b\x06 of 1 and a \x05\x07W\b\x06 characteristic of 11. It has 3 wounds remaining, so it is \x05\x07below half-strength\b\x06 and a \x05\x07battle-shock roll\b\x06 must be made for it."],accordions:[{ref:"08.03.01",title:"Multiple Battle-shock Rolls",text:["In the Battle-shock step (08.03), unless otherwise stated, no more than one \x05battle-shock roll\x06 can be made by each unit. If for any reason a unit must make a \x05battle-shock roll\x06 in this step before one it is required to make for being battle-shocked or at or below \x05half-strength\x06, that unit does not also have to make the \x05battle-shock roll\x06 for being battle-shocked or at or below \x05half-strength\x06."]}]},{ref:"08.04",title:"Command Abilities",text:["Rules that are triggered in the Command phase (excluding those that are triggered at the start or end of this phase, when gaining Core CP, or by \x05battle-shock rolls\x06) are resolved now."]},{ref:"08.05",title:"End of Command Phase",text:["Rules that are triggered at the end of the Command phase are resolved now, in the following order:","\x051\x06. First resolve rules triggered at this point other than mission rules.","\x052\x06. Both players then consult their mission; if one or both players have achieved any aspects of their mission that are triggered at this point, resolve them now."]}]},{number:"09",title:"Movement Phase",subsections:[{ref:"09.00",title:"Movement Phase",text:["In the Movement phase, you will be able to move each of your units across the battlefield. Reinforcements can also arrive in this phase to bolster your forces.","The Movement phase is resolved by following these steps:","1. START OF MOVEMENT PHASE","2. MOVE UNITS","3. END OF MOVEMENT PHASE"]},{ref:"09.01",title:"Start Of Movement Phase",text:["Rules that are triggered at the start of the Movement phase are resolved now."]},{ref:"09.02",title:"Move Units Step",text:["The active player moves their units one at a time, using the sequence below, until all of their units have been \x05selected to move\x06 and those moves have ended.","\x051. Select Unit:\x06 Select one friendly unit that has not been \x05selected to move\x06 this phase. You can select a unit on the battlefield, in \x05strategic reserves\x06, or embarked within a \x03TRANSPORT\x04. That unit is \x05selected to move\x06.","\x052. Select Move Type:\x06 Select one \x05move type\x06 that unit is eligible to make, and resolve it with that unit. This can be one listed below, or one presented elsewhere:","▫ \x05Remain stationary\x06 (09.04)","▫ \x05Normal move\x06 (09.05)","▫ \x05Advance move\x06 (09.06)","▫ \x05Fall-back move\x06 (09.07)","▫ \x05Disembark move\x06 (18.04)","▫ \x05Ingress move\x06 (20.04)"],accordions:[{ref:"09.02.01",title:"Selecting Units To Move",text:["When the Move Units step ends, the active player must have selected all of their units to make a move with, including those in \x05strategic reserves\x06. This means that before the phase ends, every unit in their army will have been selected to make a move, even if it is to \x05remain stationary\x06 (09.04). Any units the active player does not select a \x05move type\x06 for during this step will \x05remain stationary\x06."]},{ref:"09.02.02",title:"Selecting Modes",text:["Some rules instruct you to select a mode, such as \x05fall-back moves\x06 (09.07). Modes are mutually exclusive, and you must assess each one in the order presented. When making a move, if your unit does not meet the conditions of any of the modes, it cannot make that move.","Sometimes a mode will be mandatory if applicable (e.g. \x05consolidation modes\x06, 12.08), but in the case of \x05fall-back moves\x06, \x05ordered retreat\x06 is not mandatory, so you could select \x05desperate escape\x06 instead.","Many \x05move types\x06 state conditions you must meet while/after moving. Those that are labelled with a mode name only apply if you selected that mode; those not labelled with a mode name always apply."]},{ref:"09.02.03",title:"Reinforcements Step",text:["Rules that say they happen during the Reinforcements step happen during the Move Units step."]}]},{ref:"09.03",title:"End Of Movement Phase",text:["Rules that are triggered at the end of the Movement phase are resolved now."]},{ref:"09.04",title:"Remain Stationary",text:["\x0eEligible If","Any unit.","\x0eEffect","No models are moved (either in straight lines or rotated). Units that \x05remain stationary\x06 do \x01not\x02 trigger any rules that are triggered when a unit starts or ends a move.","\x0eMaximum Distance","'-'"]},{ref:"09.05",title:"Normal Move",text:["\x0eEligible If","Your unit is on the battlefield and \x05unengaged\x06.","\x0eEffect","Your unit moves as described in Moving (03).","\x0eAfter Moving","Your unit must be \x05unengaged\x06.","\x0eMaximum Distance","Your unit’s \x05M\x06 characteristic."],accordions:[{ref:"09.05.01",title:"More Than One Normal Move in a Phase.",text:["A unit cannot make more than one \x05Normal Move\x06 in a phase."]}]},{ref:"09.06",title:"Advance Move",text:["\x0eEligible If","Your unit is on the battlefield and \x05unengaged\x06.","\x0eBefore Moving","Make an \x05advance roll\x06 by rolling one D6.","\x0eEffect","Your unit moves as described in Moving (03).","\x0eAfter Moving","• Your unit must be \x05unengaged\x06.","• Until the end of the turn, unless otherwise stated, your unit is \x01not\x02 \x05eligible to declare a charge\x06 or \x05start an action\x06.","\x0eMaximum Distance","Advance roll + your unit’s \x05M\x06 characteristic."]},{ref:"09.07",title:"Fall-Back Move",text:["\x0eEligible If","Your unit is \x05engaged\x06.","\x0eBefore Moving","Select \x05fall-back mode:\x06","• \x05Ordered Retreat:\x06 If your unit is not \x05battle-shocked\x06, you can select this mode.","• \x05Desperate Escape:\x06 Otherwise, you must select this mode. Make a \x05hazard roll\x06 for each model in your unit (06.03).","\x0eWhile Moving","• \x05Desperate Escape:\x06 Each model that is moved can be moved through enemy models.","\x0eEffect","Your unit moves as described in Moving (03).","\x0eAfter Moving","• Your unit must be \x05unengaged\x06.","• Until the end of the turn, unless otherwise stated, your unit is \x01not\x02 \x05eligible to shoot\x06, \x05declare a charge\x06 or \x05start an action\x06.","• \x05Desperate Escape:\x06 If your unit is not \x05battle-shocked\x06, you must make a \x05battle-shock roll\x06 for your unit (01.07).","\x0eMaximum Distance","Your unit’s \x05M\x06 characteristic."],accordions:[{ref:"09.07.01",title:"Desperate Escape Test",text:["Some rules may reference the term 'Desperate Escape test'. In all instances this means the \x05hazard rolls\x06 made for the \x05desperate escape\x06 mode of a \x05fall-back move\x06.","Abilities that subtract from a unit's Desperate Escape test instead subtract from those \x05hazard rolls\x06.","\x05Example:\x06 \x07A \x05battle-shocked\x06 unit makes a \x05fall-back move\x06 away from a unit of Bloodletters that have the Bane of Cowards ability. As a result of Bane of Cowards, because the unit making the \x05fall-back move\x06 is \x05battle-shocked\x06, the \x05hazard rolls\x06 they make as part of their \x05desperate escape\x06 will be at -1\b."]},{ref:"09.07.01",title:"Desperate Escape",text:["If a \x05stratagem\x06 or ability forces a unit to make a Desperate Escape test, that unit:","- Must make one \x05hazard roll\x06 for each model in that unit.","- Must make a \x05battle-shock roll\x06."]}]}]},{number:"10",title:"Shooting Phase",subsections:[{ref:"10.00",title:"Shooting Phase",text:["In the Shooting phase, your units will take aim and use their ranged weapons to fire at their chosen targets.","The Shooting phase is resolved by following these steps:","1. START OF SHOOTING PHASE","2. SHOOT","3. END OF SHOOTING PHASE"]},{ref:"10.01",title:"Start Of Shooting Phase",text:["Rules that are triggered at the start of the Shooting phase are resolved now."]},{ref:"10.02",title:"Shoot Step",text:["The active player shoots with their eligible units one at a time, using the sequence below, until all the units they choose to shoot with have been \x05selected to shoot\x06 and their attacks have been resolved.","A unit is \x05eligible to shoot\x06 if it is on the battlefield and has not already been \x05selected to shoot\x06 this phase.","\x051. Select Unit:\x06 Select one friendly unit that is \x05eligible to shoot\x06; that unit is \x05selected to shoot\x06.","\x052. Select Shooting Type:\x06 Select one \x05shooting type\x06 that unit is eligible to make, and resolve it with that unit. This can be one listed below, or one presented elsewhere:","▫ \x05Normal shooting\x06 (10.04)","▫ \x05Assault shooting\x06(10.05)","▫ \x05Close‑quarters shooting\x06 (10.06)","▫ \x05Indirect shooting\x06 (10.07)"]},{ref:"10.03",title:"End of Shooting Phase",text:["Rules that are triggered at the end of the Shooting phase are resolved now."]},{ref:"10.04",title:"Normal Shooting",text:["\x0eEligible If","Your unit is \x05unengaged\x06 and did not make an \x05advance move\x06 this turn.","\x0eEffect","Your unit shoots as described in Making Attacks (04).","\x0eAfter Shooting","Until the end of the phase, your unit is \x01not\x02 \x05eligible to start an action\x06."]},{ref:"10.05",title:"Assault Shooting",text:["\x0eEligible If","\x01All\x02 of the following apply to your unit:","• \x05Unengaged\x06 and made an \x05advance move\x06 this turn.","• Has one or more \x05[ASSAULT]\x06 weapons.","\x0eWhile Shooting","You can only select \x05[ASSAULT]\x06 weapons to make attacks with.","\x0eEffect","Your unit shoots as described in Making Attacks (04).","\x0eAfter Shooting","Until the end of the phase, your unit is \x01not\x02 \x05eligible to start an action\x06."]},{ref:"10.06",title:"Close-Quarters Shooting",text:["\x0eEligible If","\x01All\x02 of the following apply to your unit:","• \x05Engaged\x06 and did not make an \x05advance move\x06 this turn.","• Has one or more \x05[CLOSE‑QUARTERS]\x06 weapons or is a \x03MONSTER/VEHICLE\x04 unit.","\x0eWhile Shooting","Models in your unit can target enemy units your unit is \x05engaged\x06 with.","• \x03MONSTER/VEHICLE\x04 \x05Models\x06: Each time a \x03MONSTER/VEHICLE\x04 model in your unit makes an attack:","◦ Unless that attack is made with a \x03[CLOSE‑QUARTERS]\x04 weapon and targets a unit your unit is \x05engaged\x06 with, subtract 1 from the \x05hit roll\x06.","◦ If that attack is made with a \x05[BLAST]\x06 weapon, it still cannot target a unit your unit is \x05engaged\x06 with.","• Non‑\x03MONSTER\x04/Non‑\x03VEHICLE\x04\x05Models:\x06 You can only select \x05[CLOSE‑QUARTERS]\x06 weapons to make attacks with and you can only select enemy units that are \x05engaged\x06 with your unit as targets","\x0eEffect","Your unit shoots as described in Making Attacks (04).","\x0eAfter Shooting","Until the end of the phase, your unit is \x01not\x02 \x05eligible to start an action\x06."]},{ref:"10.07",title:"Indirect Shooting",text:["\x0eEligible If","\x01All\x02 of the following apply to your unit:","• \x05Unengaged\x06 and did not make an \x05advance move\x06 this turn.","• Has one or more \x03[INDIRECT FIRE]\x04 weapons.","\x0eWhile Shooting","• \x03[INDIRECT FIRE]\x04 weapons in your unit can target units that are not \x05visible\x06 to the attacking model.","• Each time an \x03[INDIRECT FIRE]\x04 weapon makes an attack:","◦ The target has the \x05benefit of cover\x06 against that attack (13.08).","◦ You cannot re‑roll \x05hit rolls\x06.","◦ An unmodified \x05hit roll\x06 of 1‑5 fails, unless your unit \x05remained stationary\x06 this turn and the target is \x05visible\x06 to one or more friendly units, in which case an unmodified \x05hit roll\x06 of 1‑3 fails instead.","\x0eEffect","Your unit shoots as described in Making Attacks (04).","\x0eAfter Shooting","Until the end of the phase, your unit is \x01not\x02 \x05eligible to start an action\x06."]}]},{number:"11",title:"Charge Phase",subsections:[{ref:"11.00",title:"Charge Phase",text:["In the Charge phase, you will be able to make charge moves with your units. This represents your forces closing the distance with their foes in order to engage them in bloody close combat.","The Charge phase is resolved by following these steps:","1. START OF CHARGE PHASE","2. CHARGE","3. END OF CHARGE PHASE"]},{ref:"11.01",title:"Start Of Charge Phase",text:["Rules that are triggered at the start of the Charge phase are resolved now."]},{ref:"11.02",title:"Charge Step",text:["The active player resolves \x05charges\x06 with their eligible units one at a time, using the sequence below, until all of their units they choose to \x05charge\x06 with have \x05declared a charge\x06 and those \x05charges\x06 have been resolved.","\x051. Declare Charge\x06: Select one friendly unit that has not \x05declared a charge\x06 this phase and is \x05eligible to declare a charge\x06 (see below). That unit \x05declares a charge\x06.","A unit is \x05eligible to declare a charge\x06 if it is on the battlefield, unless otherwise stated. Here are some rules that \x01prevent\x02 a unit from being \x05eligible to declare a charge\x06:",'• It is not within 12" of one or more enemy units.',"• It is \x05engaged\x06.","• It made an \x05advance\x06 or \x05fall-back move\x06 this turn.","\x052. Make Charge Roll\x06: Make a \x05charge roll\x06 by rolling 2D6: the result is the \x05maximum distance\x06 for the \x05charge move\x06.","\x053. Attempt Charge\x06: If it is possible to make a \x05charge move\x06, and if you still want to, make a \x05charge move\x06 with that unit (11.04). Otherwise, your unit does not make a \x05charge move\x06. In either case, the \x05charge\x06 is then resolved.","\x0eMaking a charge move",'The BLUE unit \x05\x07(A) declares a charge\b\x06 and the \x05\x07charge roll\b\x06 generates a \x05\x07maximum distance\b\x06 of 7". Unit \x05\x07B\b\x06 is within this distance, so can be selected as a \x05\x07charge target\b\x06, but the BLUE unit would not be able to end its \x05\x07charge move\b\x06 \x05\x07engaged\b\x06 with this unit after moving around the intervening terrain features.','Unit \x05\x07C\b\x06 is more than 7" from the charging unit, so it cannot be selected as a \x05\x07charge target\b\x06, even though the charging unit could end its \x05\x07charge move\b\x06 within 2" of this unit.','Units \x05\x07D\b\x06 and \x05\x07E\b\x06 are both within 7", so can be selected as \x05\x07charge targets\b\x06. The charging unit can end its \x05\x07charge move\b\x06 \x05\x07engaged\b\x06 with all of its \x05\x07charge targets\b\x06, so this move can be made.'],accordions:[{ref:"11.02.01",title:"Failed Charges",text:['Note that in the absence of modifiers to the \x05charge roll\x06, a result of 2 (a double 1) is never sufficient for a unit to complete a \x05charge move\x06, as a unit cannot be within \x05engagement range\x06 (2") when it attempts a \x05charge\x06. Such a roll would therefore result in a failed \x05charge\x06, and the unit would not move.']}]},{ref:"11.03",title:"End Of Charge Phase",text:["Rules that are triggered at the end of the Charge phase are resolved now."]},{ref:"11.04",title:"Charge Move",text:["\x0eEligible If","Your unit \x05declared a charge\x06 this phase.","\x0eBefore Moving",'Select one or more enemy units that are within 12" of your unit and within the \x05maximum distance\x06 of your unit; until the end of this move, each of those enemy units is a \x05charge target\x06.',"\x0eWhile Moving","• Each model must end its move closer to one or more \x05charge targets\x06.",'• Each model that can end its move within 1" of one or more \x05charge targets\x06 must do so.',"• Each model that can end its move \x05engaged\x06 with one or more \x05charge targets\x06 must do so.","\x0eEffect","Your unit moves as described in Moving (03).","\x0eAfter Moving","• Your unit must be \x05engaged\x06 with \x01all\x02 of the \x05charge targets\x06.","• Your unit cannot be \x05engaged\x06 with one or more enemy units that are not \x05charge targets\x06.","• Until the end of the turn, each model in your unit has the \x05Fights First\x06 ability (24.13).","\x0eMaximum Distance","Charge roll."]}]},{number:"12",title:"Fight Phase",subsections:[{ref:"12.00",title:"Fight Phase",text:["In the Fight phase, both players get to act. First, units will pile in to maximise the number of models that are engaged, then all the combatants will make melee attacks, before units consolidate their position.","The Fight phase is resolved by following these steps:","1. START OF FIGHT PHASE","2. PILE IN","3. FIGHT","4. CONSOLIDATE","5. END OF FIGHT PHASE"]},{ref:"12.01",title:"Start Of Fight Phase",text:["Rules that are triggered at the start of the Fight phase are resolved now.","\x0eStart of Fight Phase","Because both RED\x05\x06 units made \x05\x07charge moves\b\x06 this turn, they are both \x05\x07Fights First\b\x06 units this phase and are both eligible to make \x05\x07pile-in moves\b\x06, even though the \x03Monster\x04 is \x05\x07unengaged\b\x06 as it \x05\x07destroyed\b\x06 its \x05\x07charge target\b\x06 in the Charge phase using the Crushing Impact stratagem (\x0715.06\b)."]},{ref:"12.02",title:"Pile In Step",text:["Both players make \x05pile-in moves\x06 (12.03) with all of their eligible units they choose to move. The ‘Eligible If’ section describes which units are eligible to make such moves. The player whose turn it is resolves all of their moves first, followed by their opponent. Each unit cannot make more than one \x05pile-in move\x06 during this step.","\x0ePile-in moves","\x051.\x06 The RED\x05\x06 player makes \x05\x07pile-in moves\b\x06 first. Each model moves up to 3”.","\x052.\x06 The BLUE player makes \x05\x07pile-in moves\b\x06 next, but as their model is in base-contact with enemy models, it is not moved."]},{ref:"12.03",title:"Pile-In Move",text:["\x0eEligible If","It is the Fight phase and one or more of the following apply to your unit:","• It is \x05engaged\x06.","• It made a \x05charge move\x06 this turn.","• It was selected to make an \x05overrun fight\x06 this phase (12.06).","\x0eBefore Moving","Select \x05pile-in targets\x06:","• If your unit is \x05engaged\x06, select \x01every\x02 enemy unit it is \x05engaged\x06 with.",'• Otherwise, select one or more enemy units within 5" of your unit.',"\x0eWhile Moving","• Models in base‑contact with one or more enemy models cannot be moved.","• Each model that is moved must end its move closer to the closest \x05pile-in target\x06, and \x05engaged\x06 with it if possible.","\x0eEffect","Your unit moves as described in Moving (03).","\x0eAfter Moving","• Your unit must be \x05engaged\x06.","• Each model that started this move \x05engaged\x06 with an enemy unit must still be \x05engaged\x06 with that enemy unit.","\x0eMaximum Distance",'3"']},{ref:"12.04",title:"Fight Step",text:["A unit is \x05eligible to fight\x06 if it has not already been \x05selected to fight\x06 this phase and one or more of the following apply to it:","• It is \x05engaged\x06, or it was \x05engaged\x06 at the start of this step.","• It made a \x05charge move\x06 this turn.","Players resolve the following sequence until all eligible units have been \x05selected to fight\x06 and their attacks have been resolved:","\x051. Resolve Fights First Combats\x06: Starting with the player whose turn it is, players alternate selecting one friendly \x05Fights First\x06 unit that is \x05eligible to fight\x06; that unit is \x05selected to fight\x06 (see below). If this is not possible:","• If there are no \x05Fights First\x06 units that are \x05eligible to fight\x06, move to the Resolve Remaining Combats step where this player will select their next unit.","• Otherwise, the other player selects their next unit.","\x052. Resolve Remaining Combats\x06: Starting with the player who just moved this sequence onto this step, players alternate selecting one friendly unit that is \x05eligible to fight\x06; that unit is \x05selected to fight\x06. If this is not possible:","• If there are no units that are \x05eligible to fight\x06, the Fight step ends.","• Otherwise, the other player selects their next unit.","After resolving a fight in the Resolve Remaining Combats step, if there are one or more \x05Fights First\x06 units that are now \x05eligible to fight\x06, return to the Resolve Fights First Combats step.","\x05WHEN A UNIT IS SELECTED TO FIGHT\x06","Each time a unit is \x05selected to fight\x06, select one \x05fight type\x06 that unit is eligible to make, and resolve it with that unit. This can be one listed below, or one presented elsewhere:","\x0eNormal Fight","Players alternate selecting units to fight. \x05\x07Fights First\b\x06 units (\x05\x07A\b\x06 and \x05\x07B\b\x06) must be selected before any other eligible units.","\x051.\x06 The RED\x05\x06 player selects their \x03Monster\x04 to fight. It makes a \x05\x07normal fight\b\x06, \x05\x07destroying\b\x06 the \x03Transport\x04.","\x052.\x06 The embarked unit makes an \x05\x07emergency\b\x06 \x05\x07disembark move\b\x06. After doing so, it is \x05\x07unengaged\b\x06.","\x0eOverrun Fight","\x053.\x06 The BLUE player has no \x05\x07Fights First\b\x06 units, so the RED player selects another \x05\x07Fights First\b\x06 unit. This unit is \x05\x07unengaged\b\x06, but was \x05\x07engaged\b\x06 with the \x03Transport\x04 at the start of the Fight step, so can make an \x05\x07overrun fight\b\x06. It first makes a \x05\x07pile-in move\b\x06 to \x05\x07engage\b\x06 the unit that disembarked, then fights, \x05\x07destroying\b\x06 two enemy models.","\x054.\x06 The BLUE player’s unit fights back, but inflicts no damage."],accordions:[{ref:"12.04.01",title:"Eligible to fight, but unable to fight",text:['During the Fight sequence, when the sequence returns to a player to select a unit to fight, if all of that player’s units that are \x05eligible to fight\x06 are more than 5" from all enemy units, that player can instead choose to pass and return the sequence to their opponent to select a unit. If both players pass in succession, or if one player passes when their opponent has no remaining units that are \x05eligible to fight\x06, the Fight step ends.',"\x05Designer's Note:\x06 \x07Occasionally, all of a unit’s targets will be \x05destroyed\x06 before they have had a chance to fight, with no other targets close enough to \x05engage\x06 with a \x05pile-in move\x06. In such cases, a player can choose to pass and wait to see if another enemy unit ends a \x05pile-in move\x06 close enough to be attacked later in the phase.\b"]}]},{ref:"12.05",title:"Normal Fight",text:["\x0eEligible If","Your unit is \x05engaged\x06.","\x0eEffect","Your unit fights as described in Making Attacks (04)."]},{ref:"12.06",title:"Overrun Fight",text:["\x0eEligible If","Your unit is \x05unengaged\x06, or was \x05unengaged\x06 at the start of the Fight step but became \x05engaged\x06 during the Fight phase.","\x0eEffect","Your unit can make one additional \x05pile-in move\x06, then fights as described in Making Attacks (04)."]},{ref:"12.07",title:"Consolidate Step",text:["Both players make \x05consolidation moves\x06 (12.08) with all of their eligible units they choose to move. The ‘Eligible If’ section describes which units are eligible to make such moves. The player whose turn it is resolves all of their moves first, followed by their opponent. Each unit cannot make more than one \x05consolidation move\x06 during this step.","\x0eOngoing Consolidation","The RED player makes \x05\x07consolidation moves\b\x06 first. All \x05\x07engaged\b\x06 units and all units that were \x05\x07eligible to fight\b\x06 this phase can make a \x05\x07consolidation move\b\x06.",'Each model moves up to 3". Models in base-contact with enemy models cannot be moved.',"\x0eObjective Consolidation",'No enemy units are within 3" of this \x03Monster\x04 unit, but an \x05\x07objective (C)\b\x06 is within 3", so it moves within range of that \x05\x07objective\b\x06.']},{ref:"12.08",title:"Consolidation Move",text:["\x0eEligible If","It is the Fight phase and your unit was \x05eligible to fight\x06 this phase.","\x0eBefore Moving","Select \x05consolidation mode\x06:","• \x05Ongoing Consolidation:\x06 If your unit is \x05engaged\x06, you must select this mode and select \x01every\x02 enemy unit it is \x05engaged\x06 with.",'• \x05Engaging Consolidation:\x06 Otherwise, if your unit is within 3" of one or more enemy units, you must select this mode and select one or more of those enemy units.','• \x05Objective Consolidation:\x06 Otherwise, if your unit is within 3" of one or more \x05objectives\x06, you must select this mode and select one of those \x05objectives\x06.',"\x0eWhile Moving","• \x05Ongoing Consolidation:\x06 Models in base‑contact with one or more enemy models cannot be moved. Each model that is moved must end its move closer to the closest selected enemy unit, and \x05engaged\x06 with it if possible.","• \x05Engaging Consolidation:\x06 Each model that is moved must end its move closer to the closest selected enemy unit, and \x05engaged\x06 with it if possible.","• \x05Objective Consolidation:\x06 Each model that is moved must end its move within range of the selected \x05objective\x06 if possible, or closer to it if not.","\x0eEffect","Your unit moves as described in Moving (03).","\x0eAfter Moving","• \x05Ongoing Consolidation:\x06 Each model that started this move \x05engaged\x06 with an enemy unit must still be \x05engaged\x06 with that enemy unit.","• \x05Engaging Consolidation:\x06 Your unit must be \x05engaged\x06 with \x01all\x02 of the selected enemy units. If one or more enemy units \x05engaged\x06 with your unit have not been \x05selected to fight\x06 this phase, your opponent must select each of those units, one at a time; when each is selected, it becomes \x05eligible to fight\x06 and is \x05selected to fight\x06 (12.04).","• \x05Objective Consolidation:\x06 Your unit must be \x05unengaged\x06 and within range of the selected \x05objective\x06.","\x0eMaximum Distance",'3"']},{ref:"12.09",title:"End Of Fight Phase",text:["Rules that are triggered at the end of the Fight phase are resolved now."]}]},{number:"13",title:"Terrain",subsections:[{ref:"13.01",title:"Placing Terrain",text:["Before the battle, place a selection of \x05terrain features\x06 on the battlefield using one or more of the following methods:","• Place a well‑defined boundary (such as a base or mat) in each location you want to furnish with terrain, then place one or more \x05terrain features\x06 wholly within that boundary.","• Place one \x05terrain feature\x06 directly on the battlefield.","• Place two or more \x05terrain features\x06 directly on the battlefield in such a way that together they define the boundary of an area.","In each case, the area of the battlefield occupied by that boundary or \x05terrain feature\x06 is known as a \x05terrain area\x06. A mission’s deployment map may define the location and dimensions of each \x05terrain area\x06. Otherwise, players must agree on this before the battle."]},{ref:"13.02",title:"Terrain Categories",text:["Each \x05terrain feature\x06 belongs to a \x05terrain category\x06, which can affect the movement and visibility of models. Below are some examples of which types of \x05terrain features\x06 fall under each category.","A mission’s deployment map may define which \x05terrain categories\x06 should be present within each terrain area. Meeting these requirements will create the best gaming experience. Note that \x05terrain features\x06 sharing the same \x05terrain area\x06 can belong to different \x05terrain categories\x06.","\x0eTerrain Placed on a Mat","Two \x05\x07terrain features\b\x06 have been placed on a mat. The edges of this mat define the boundary of this \x05\x07terrain area (A)\b\x06. Both \x05\x07terrain features (B)\b\x06 are ruins, so use the rules for \x05\x07dense terrain features\b\x06.","\x0eTerrain Placed on a Battlefield","Three \x05\x07terrain features\b\x06 have been placed directly on the battlefield. The players have agreed on the boundary of the \x05\x07terrain area (A)\b\x06 defined by these features (the shaded rectangle). The \x05BLUE\x06 features \x05\x07(B)\b\x06 are \x05\x07dense terrain features\b\x06 and the \x05RED\x06 feature \x05\x07(C)\b\x06 is a \x05\x07light\b\x06 \x05\x07terrain feature\b\x06."],accordions:[{ref:"13.02.01",title:"Creating Your Own Battlefield",text:["Don’t worry if your battlefield doesn’t match a mission’s \x05terrain category\x06 requirements; just do the best with the \x05terrain features\x06 you have. If a mission does not provide you with guidance, it will be up to the players to decide how to create their battlefield. When doing so, keep in mind that \x05dense terrain features\x06 have the greatest impact on visibility and movement. Battlefields with too few \x05dense terrain features\x06 can advantage armies that rely on shooting, or disadvantage armies that rely on melee. Also remember to leave sufficient room around \x05dense terrain features\x06 for larger models such as \x03MONSTERS/VEHICLES\x04 to manoeuvre, especially near the edges of the battlefield."]}]},{ref:"13.03",title:"Exposed Terrain",text:["Exposed terrain offers only scant protection to the most desperate troops, and can be traversed without hindrance.","\x05Examples\x06: Craters, razorwire, scattered debris."]},{ref:"13.04",title:"Light Terrain",text:["Light terrain can provide cover from incoming attacks, but will not slow an enemy’s advance or offer lasting defence.","\x05Examples\x06: Barricades, low walls, statuary."]},{ref:"13.05",title:"Dense Terrain",text:["Dense terrain is an obstacle to even the largest war machines, and can shelter entire squads from enemy sight.","\x05Examples\x06: Buildings, ruins, armoured containers, woods."]},{ref:"13.06",title:"Terrain And Movement",text:["Models can move through different categories of \x05terrain feature\x06 as follows:","• \x05Exposed/Light\x06: All models can move horizontally and vertically through \x05exposed\x06 and \x05light terrain features\x06.","• \x05Dense\x06:","◦ \x03INFANTRY/BEASTS/SWARM/MOBILE\x04 models can move horizontally through \x05dense terrain features\x06.","◦ \x03INFANTRY/BEASTS/SWARM\x04 models can move vertically through \x05dense terrain features\x06.",'◦ Other models can move horizontally through \x05dense terrain features\x06 provided that all sections of that \x05terrain feature\x06 that the moving model’s base would move through are 2" or less in height. Otherwise, the moving model must move vertically to ascend or descend such sections. They cannot move through ceilings and floors while doing so, and they cannot end that move on any surface of that \x05terrain feature\x06 that is not on ground level (see below).',"\x05MOVING VERTICALLY\x06","Models can move vertically to ascend or descend \x05terrain features\x06. While doing so:",'• That model must remain within \xbd" horizontally of that \x05terrain feature\x06.',"• Add the distance moved vertically up, and the distance moved vertically down, to any other distance that model has moved since its unit began that move.","\x05SETTING UP OR ENDING A MOVE\x06","Models can be set up or end a move on the ground level of \x05terrain features\x06. Models can also be set up or end a move on any surface of a \x05terrain feature\x06that is not on ground level, if all of the following apply:","• That model has one or more of the following keywords: \x03INFANTRY/BEASTS/SWARM/FLY/MONSTER\x04.","• After ending that move, that model is stable and no part of its base overhangs the outer edge of that surface.","\x0eTerrain and Movement",'All sections of the \x05\x07dense\b\x06 \x05\x07terrain feature (A)\b\x06 are more than 2" in height, so the \x03Monster\x04 model \x05\x07(B)\b\x06 cannot move through it and must move around it instead.',"The \x03Infantry\x04 models \x05\x07(C)\b\x06 can move through \x05\x07dense terrain features\b\x06, such as the walls of this ruin.","1. This \x03Infantry\x04 model can move vertically and end its move on the top surface of the \x05\x07terrain feature (D)\b\x06, as it is stable and no part of its base overhangs the outer edge of that surface.",'2. This \x03Vehicle\x04 model cannot move through the \x05\x07dense\b\x06 \x05\x07terrain feature (E)\b\x06, but It can move vertically to ascend and descend sections that are more than 2" in height (provided it does not end that move on top of such sections).',"3. This \x03INFANTRY\x04 model is not being moved over or through any \x05\x07terrain features\b\x06. Its move through the \x05\x07terrain area\b\x06 shown is therefore unimpeded."],accordions:[{ref:"13.06.01",title:"Solid Terrain and Movement",text:['If a \x05terrain feature\x06 has the \x05Solid\x06 rule (13.11), as \x05dense terrain features\x06 do, a model cannot end a move such that any part of it is through any enclosed part of that \x05terrain feature\x06 that is 3" or less from ground level – not even through small openings such as doors and windows. This ensures that protruding elements of models cannot be used to circumvent the visibility restrictions of the Solid rule.']}]},{ref:"13.07",title:"Terrain And Visibility",text:["Terrain can affect visibility, depending on whether the \x05Benefit of Cover\x06, \x05Hidden\x06, \x05Obscuring\x06 or \x05Solid\x06 rules apply."]},{ref:"13.08",title:"Benefit Of Cover",text:["Each time a ranged attack targets a unit, if \x01every\x02 model in that unit meets one or more of the following conditions, that unit has the \x05benefit of cover\x06 against that attack:","• That model has the \x03INFANTRY/BEASTS/SWARM\x04 keyword and is within a \x05terrain area\x06.","• That model is not \x05fully visible\x06 to the attacking model due to one or more intervening \x05terrain features\x06 and/or one or more intervening \x05obscuring terrain areas\x06 (13.10).","Each time a ranged attack targets a unit that has the \x05benefit of cover\x06against it, worsen the \x05BS\x06 characteristic of that attack by 1.","\x0eBenefit of Cover","When Unit \x05\x07E\b\x06 makes ranged attacks:","• Unit \x05\x07A\b\x06 is \x05\x07fully visible\b\x06 to every model in Unit \x05\x07E\b\x06, so does not have the \x05\x07benefit of cover\b\x06.","• Not all of the models in unit \x05\x07B\b\x06 are within a \x05\x07terrain area\b\x06, so unit \x05\x07B\b\x06 does not have the \x05\x07benefit of cover\b\x06.","• All of the models in unit \x05\x07C\b\x06 are within a \x05\x07terrain area\b\x06, so unit \x05\x07C\b\x06 has the \x05\x07benefit of cover\b\x06 (-1 BS).","• Unit \x05\x07D\b\x06 is not \x05\x07fully visible\b\x06 to unit \x05\x07E\b\x06 due to an intervening \x05\x07obscuring\b\x06 \x05\x07terrain area\b\x06, so unit \x05\x07D\b\x06 has the \x05\x07benefit of cover\b\x06 (-1 BS)."]},{ref:"13.09",title:"Hidden",text:["A model is \x05hidden\x06 while \x01all\x02 of the following apply to it:","• That model has the \x03INFANTRY/BEASTS/SWARM\x04 keyword and is within a \x05terrain area\x06 that contains one or more \x05light/dense terrain features\x06.","• That model’s unit did not make one or more ranged attacks during this turn or during the previous turn.",'While a model is \x05hidden\x06, it can only be \x05visible\x06 to enemy models that are within its \x05detection range\x06. Unless otherwise stated, a model’s \x05detection range\x06 is 15".'],accordions:[{ref:"13.09.01",title:"Hidden and the First Turn",text:["During the first turn, conditions that require something not to have happened during the previous turn are true. For the \x05Hidden\x06 rule, this means that during the first turn a unit has not made ranged attacks during the previous turn."]}]},{ref:"13.10",title:"Obscuring",text:["\x05Terrain areas\x06 containing one or more \x05light\x06 or \x05dense terrain features\x06 are \x05obscuring terrain areas\x06. If every \x05line of sight\x06 drawn between two models crosses one or more \x05obscuring terrain areas\x06 (excluding \x05obscuring terrain areas\x06 that one or both of those models are within), those two models are not \x05visible\x06 to each other.","\x0eHidden and Obscuring","• There is an \x05\x07obscuring\b\x06 \x05\x07terrain area\b\x06 between all models in units \x05\x07A\b\x06 and \x05\x07D\b\x06, so none of them are \x05\x07visible\b\x06 to each other.",'• All models in units \x05\x07B\b\x06 and \x05\x07C\b\x06 are within the \x05\x07terrain area\b\x06 and are \x03Infantry\x04, so are \x05\x07hidden\b\x06. However, unit \x05\x07D\b\x06’s models are within the 15" \x05\x07detection range\b\x06 of unit \x05\x07B\b\x06’s models (but not unit \x05\x07C\b\x06’s), so unit \x05\x07B\b\x06’s models are \x05\x07visible\b\x06 to unit \x05\x07D\b\x06’s. Unit \x05\x07D\b\x06’s models are also \x05\x07visible\b\x06 to the models in units \x05\x07B\b\x06 and \x05\x07C\b\x06, since they are not within a \x05\x07terrain area\b\x06.']},{ref:"13.11",title:"Solid",text:['\x05Dense terrain features\x06 have the \x05Solid\x06 rule. \x05Line of sight\x06 cannot be drawn across any enclosed gap in the surface of such a \x05terrain feature\x06 that is 3" or less from ground level.','\x05Designer’s Note\x06: \x07This rule ensures that models are not \x05visible\x06 while sheltering in ground-level terrain, irrespective of small openings such as doors, windows or bullet holes, or because of small gaps between adjacent \x05terrain features\x06. 3" is the height of the first floor of many \x05terrain features\x06, but some missions may adjust the height at which this rule takes effect.\b',"\x0eSolid",'Units \x05\x07A\b\x06 and \x05\x07B\b\x06 are not \x05\x07visible\b\x06 to each other, because even though there is a window in this \x05\x07dense\b\x06 \x05\x07terrain feature\b\x06, it has the \x05\x07Solid\b\x06 rule, so \x05\x07line of sight\b\x06 cannot be drawn through such enclosed gaps that are 3" or less from ground level.','Units \x05\x07A\b\x06 and \x05\x07C\b\x06 are \x05\x07visible\b\x06 to each other, because even though this \x05\x07dense\b\x06 \x05\x07terrain feature\b\x06 has the \x05\x07Solid\b\x06 rule, \x05\x07line of sight\b\x06 can be drawn normally through enclosed gaps that are more than 3" from ground level.'],accordions:[{ref:"13.11.01",title:"Gone to Ground",text:["\x05Hidden\x06 models that are concealed by \x05dense terrain features\x06 gain an extra benefit while they have \x05gone to ground\x06.","A model has \x05gone to ground\x06 while all of the following apply:","• That model is \x05hidden\x06.","• That model is not \x05fully visible\x06 to the attacking model due to one or more intervening \x05dense terrain features\x06.","• That model’s unit did not make one or more ranged attacks during this turn or during the previous turn.",'While a model has \x05gone to ground\x06, subtract 3" from that model’s \x05detection range\x06.',"\x05Designer’s Note:\x06 \x07Units that made ranged attacks in the current or previous turn cannot \x05go to ground\x06, regardless of any abilities that allow them to shoot and remain \x05hidden\x06."]}]}]},{number:"14",title:"Objectives",subsections:[{ref:"14.01",title:"Terrain Objectives",text:["If a mission uses \x05objectives\x06, it will state where they are located on the battlefield. Typically, your mission will have a deployment map showing several points where \x05objectives\x06 should be placed. The location of each point should coincide with a \x05terrain area\x06 (13.01); that \x05terrain area\x06 is the \x05objective\x06, and is called a \x05terrain objective\x06.","When measuring distances to and from an \x05objective\x06, measure to and from the closest part of it."],accordions:[{ref:"14.01.01",title:"Objectives Not Within A Terrain Area",text:["If the location point of an \x05objective\x06 does not coincide with a \x05terrain area\x06, you must denote the location of that \x05objective\x06 with a flat, circular marker, 40 mm in diameter, centred on that point – this is called an\x05objective marker\x06. Models can move through \x05objective markers\x06 and they can end a move on top of \x05objective markers\x06.",'A model is within range of an \x05objective marker\x06 while it is within 3" horizontally and 5" vertically of that \x05objective marker\x06. When measuring distances to and from an \x05objective marker\x06, measure to and from the closest part of it.']}]},{ref:"14.02",title:"Level Of Control",text:["At the start of the battle, no \x05objective\x06 on the battlefield is controlled by either player. To gain control of an \x05objective\x06, a player will need one or more models with an \x05OC\x06 characteristic of 1 or more within range of it. A model is within range of a \x05terrain objective\x06 while it is within that \x05terrain area\x06.","At the end of each phase and turn, to determine a player’s \x05level of control\x06 over an \x05objective\x06, add together the \x05OC\x06 characteristics of all the models in that player’s army that are within range of that \x05objective\x06:","• The player who has the highest \x05level of control\x06 over that \x05objective\x06 controls that \x05objective\x06.","• If both players have the same \x05level of control\x06 over that \x05objective\x06, unless that \x05objective\x06 is \x05secured\x06 (14.03), that \x05objective\x06 is not controlled by either player.","While one or more units from a player’s army are within range of an \x05objective\x06 that player controls, for each of those units that contains one or more models with an \x05OC\x06 characteristic of 1 or more, that unit is said to be controlling that \x05objective\x06."],accordions:[{ref:"14.02.01",title:"Controlling an Objective at the End of a Phase",text:["At the end of each phase and turn, the first thing players do (before any other 'at the end of the phase/end of the turn' rules or abilities) is determine which \x05objectives\x06 are controlled by which player."]}]},{ref:"14.03",title:"Secured Objectives",text:["Some rules allow an \x05objective\x06 to be \x05secured\x06 by a player’s army. When an \x05objective\x06 is \x05secured\x06 by a player’s army, that \x05objective\x06 remains under their control – even once they no longer have any units within range of it – until their opponent’s \x05level of control\x06 over that \x05objective\x06 is greater than theirs at the end of a phase.","\x0eControlling a Terrain Objective","\x03Vehicle\x04 \x05\x07A\b\x06 has an \x05\x07OC\b\x06 characteristic of 3, and it is within the \x05\x07terrain area\b\x06.","\x03Vehicle\x04 \x05\x07B\b\x06 has an \x05\x07OC\b\x06 characteristic of 2, and it is wholly within the \x05\x07terrain area\b\x06.","The models in unit \x05\x07C\b\x06 each have an \x05\x07OC\b\x06 characteristic of 1. Six of its models are within the \x05\x07terrain area\b\x06.","Unit \x05\x07D\b\x06 is currently \x05\x07battle-shocked\b\x06, so the \x05\x07OC\b\x06 characteristic of all of its models is ‘-’.","Both players add together the \x05\x07OC\b\x06 characteristics of all their models that are within the \x05\x07terrain area\b\x06. The BLUE player’s \x05\x07level of control\b\x06 is 5, and the RED player’s \x05\x07level of control\b\x06 is 6. The RED player therefore controls the \x05\x07objective\b\x06."]}]},{number:"15",title:"Stratagems",subsections:[{ref:"15.01",title:"Using Stratagems",text:["During the battle, both players can use \x05stratagems\x06. Each \x05stratagem\x06 states:","• How many CP it costs to use.","• \x05WHEN\x06: When it can be used.","• \x05TARGET\x06: Which units it can target.","• \x05EFFECT\x06: What the effects of using that \x05stratagem\x06 are.","• \x05RESTRICTIONS\x06: Any additional restrictions that apply.","Each player can use the same \x05stratagem\x06 multiple times during the battle, but the following restrictions apply:","• Each player cannot use the same \x05stratagem\x06 more than once in the same phase.","• Unless otherwise stated, each player cannot target the same unit with more than one \x05stratagem\x06 in the same phase.","Each time you use a \x05stratagem\x06, resolve the following sequence:","\x051.\x06 Select targets as described in that \x05stratagem\x06.","\x052.\x06 Reduce your CP total by the CP cost listed in that \x05stratagem\x06. If that \x05stratagem\x06 contains a section that carries an additional CP cost (e.g. +1CP), you can only use that additional section if you increase the CP cost of that \x05stratagem\x06 by the amount shown. If you do not have enough CP remaining, you cannot use that \x05stratagem\x06.","\x053.\x06 Resolve the effects of that \x05stratagem\x06.","\x05CORE STRATAGEMS\x06","All players can use \x05core stratagems\x06 (see overleaf). Additional \x05stratagems\x06 can be found in Codexes and other publications."],accordions:[{ref:"15.01.01",title:"Modifying CP Cost",text:["Some rules modify the cost of using certain \x05stratagems\x06. In such cases, the following points apply:","• The CP cost of a \x05stratagem\x06 use can never be modified below 0CP.","• If a rule modifies the CP cost of a \x05stratagem\x06 when you use it, but does not specify a duration for that modifier, that modifier only applies to that usage of that \x05stratagem\x06."]},{ref:"15.01.02",title:"Affected By A Stratagem",text:["If a unit is selected as the target of a \x05stratagem\x06, it is said to be affected by that \x05stratagem\x06."]},{ref:"15.01.03",title:"Stratagem Definitions",text:["• \x05Your Opponent’s Stratagems:\x06 \x05stratagems\x06 that your opponent uses are sometimes referred to as your opponent’s \x05stratagems\x06.","• \x05Your Stratagems:\x06 \x05stratagems\x06 that you use are sometimes referred to as your \x05stratagems\x06.","• \x05Your Unit (in Stratagems):\x06 The term ‘your unit(s)’ in the Effect section of \x05stratagems\x06 always relates to the unit(s) selected in the Target section of that \x05stratagem\x06, and never refers to any other units from your army."]}]},{ref:"15.02",title:"Command Re-Roll",text:[]},{ref:"15.03",title:"Epic Challenge",text:[]},{ref:"15.04",title:"Insane Bravery",text:[]},{ref:"15.05",title:"Crushing Impact",text:[]},{ref:"15.06",title:"Explosives",text:[]},{ref:"15.07",title:"Rapid Ingress",text:[]},{ref:"15.08",title:"Fire Overwatch",text:[]},{ref:"15.09",title:"Snap Shooting",text:["\x0eEligible If","As stated in the rule allowing this \x05shooting type\x06.","\x0eWhile Shooting",'• You can only target \x01one\x02 \x05visible\x06 enemy unit within 24" of your unit (and only if it is an eligible target).',"• Each attack only hits on an unmodified \x05hit roll\x06 of 6 (irrespective of the attacking weapon’s \x05BS\x06 characteristic or any modifiers). Those hits are \x01not\x02 \x05critical hits\x06.","• You cannot re‑roll \x05hit rolls\x06.","\x0eEffect","Your unit shoots as described in Making Attacks (04).","\x0eAfter Shooting","Until the end of the phase, your unit is \x01not\x02 \x05eligible to start an action\x06."]},{ref:"15.10",title:"Smokescreen",text:[]},{ref:"15.11",title:"Heroic Intervention",text:[]},{ref:"15.12",title:"Counteroffensive",text:[]}]},{number:"16",title:"Actions",subsections:[{ref:"16.01",title:"Performing Actions",text:["Some rules allow units to perform \x05actions\x06. Each \x05action\x06 states:","■ \x05STARTS\x06: When it is started.","■ \x05UNITS\x06: Which friendly units can perform it.","■ \x05USE LIMIT\x06: How many times friendly units can start it.","■ \x05COMPLETES\x06: When it completes.","■ \x05EFFECT\x06: What the effects of completing it are.","■ Any additional restrictions that may apply.","\x05STARTING AN ACTION\x06","A unit is \x05eligible to start an action\x06 unless one or more of the following apply to that unit:","■ It is not on the battlefield.","■ It is an \x03AIRCRAFT/FORTIFICATION\x04 unit.","■ It is \x05battle-shocked\x06.","■ It has an \x05OC\x06 characteristic of 0 or ‘-’.","■ It is \x05engaged\x06 (unless it is a \x03TITANIC\x04 unit).","■ It made an \x05advance\x06 or\x06fall-back\x06 move this turn.","■ It started another \x05action\x06 this turn.","If a unit starts an \x05action\x06, until the end of the turn:","■ It is not \x05eligible to shoot\x06 (excluding \x03TITANIC\x04 units).","■ It is not \x05eligible to declare a charge.\x06","\x05COMPLETING AN ACTION\x06","If a unit performing an \x05action\x06 makes a move (excluding \x05pile-in\x06 and \x05consolidation moves\x06) or leaves the battlefield, that unit does not complete that \x05action\x06. Otherwise, when an \x05action\x06 is completed, its ‘Effect’ section is triggered."]}]},{number:"17",title:"Monsters And Vehicles",subsections:[{ref:"17.01",title:"Moving Monsters And Vehicles",text:["Each time you make a \x05normal\x06 or \x05advance move\x06 with a unit, \x03MONSTER/VEHICLE\x04 models in that unit can be moved through friendly and enemy models (excluding other \x03MONSTER/VEHICLE\x04 models)."]},{ref:"17.02",title:"Frame",text:["Some models do not have a base; many of these are \x03MONSTER/VEHICLE\x04 models. Such models have the \x03FRAME\x04 keyword, as do some other large models. Whenever a rule refers to a model’s position in relation to anything else on the battlefield (e.g. when measuring distances), if that model has the \x03FRAME\x04 keyword, unless otherwise stated, measure to and from the closest point on that model (so not necessarily from its base, if it has one).","When rotating a \x03FRAME\x04 model as part of a move, if that model does not have a base, turn it any amount around its central axis, while keeping it upright."]},{ref:"17.03",title:"Shooting At Engaged Monsters And Vehicles",text:["In your Shooting phase, enemy \x03MONSTER/VEHICLE\x04 units that are \x05engaged\x06 can be selected as targets of ranged attacks (excluding attacks made with \x03[BLAST]\x04 weapons).","Each time a model makes a ranged attack that targets such a unit, subtract 1 from the \x05hit roll\x06 (excluding attacks made with \x03[CLOSE‑QUARTERS]\x04 weapons by models in a unit \x05engaged\x06 with the target).","\x0eEngaged Monsters/Vehicles – Shooting","The \x03Vehicle\x04 can shoot at \x03Infantry\x04 unit \x05\x07A\b\x06 using \x05\x07close-quarters shooting\b\x06. While resolving those attacks, subtract 1 from \x05\x07hit rolls\b\x06 (excluding attacks made with \x03[Close‑quarters]\x04 weapons).","\x03Infantry\x04 unit \x05\x07A\b\x06 can shoot at the \x03Vehicle\x04 using \x05\x07normal shooting\b\x06. While resolving those attacks, subtract 1 from \x05\x07hit rolls\b\x06. As the \x03Vehicle\x04 is \x05\x07engaged\b\x06, \x03[Blast]\x04 weapons cannot target it, but can target other \x05\x07unengaged\b\x06 units.","The \x03Vehicle\x04 can shoot at \x03Infantry\x04 unit \x05\x07B\b\x06 using \x05\x07close-quarters shooting\b\x06. While resolving those attacks, subtract 1 from \x05\x07hit rolls\b\x06. As the \x03INFANTRY\x04 unit is \x05\x07engaged\b\x06, \x03[Blast]\x04 weapons cannot target it, but can target other \x05\x07unengaged\b\x06 units.","\x03Infantry\x04 unit \x05\x07B\b\x06 is \x05\x07engaged\b\x06, but can shoot at the \x03VEHICLE\x04 using \x05\x07close-quarters shooting\b\x06. While doing so, it can only make attacks with its \x03[CLOSE-QUARTERS]\x04 weapons and can only target the \x03VEHICLE\x04 it is \x05\x07engaged\b\x06 with."],accordions:[{ref:"17.03.01",title:"Shooting While Engaged With Monsters/Vehicles",text:["A unit that is \x05engaged\x06 with an enemy \x03MONSTER/VEHICLE\x04 unit is still \x01not\x02 \x05eligible to shoot\x06, and so cannot make ranged attacks against that \x03MONSTER/VEHICLE\x04 unit, unless that unit is \x05eligible to shoot\x06 while \x05engaged\x06 (e.g. because it is using \x05close‑quarters shooting\x06)."]}]}]},{number:"18",title:"Transports",subsections:[{ref:"18.01",title:"Transport Capacity",text:["\x03TRANSPORT\x04 models have a \x05transport capacity\x06 listed on their datasheet. This determines the type and maximum number of friendly models that are \x05eligible to embark\x06 within them. More than one unit can be embarked within the same \x03TRANSPORT\x04 model at the same time, provided it has sufficient \x05transport capacity\x06.","Before the battle, in the Declare Battle Formations step, your units can start embarked within any friendly \x03TRANSPORT\x04 model that has sufficient \x05transport capacity\x06 remaining for the whole unit.","A friendly unit must be embarked within each friendly \x03DEDICATED TRANSPORT\x04 model. At the end of this step, each friendly \x03DEDICATED TRANSPORT\x04 model without an embarked unit is \x05destroyed\x06, but they do not trigger rules that are triggered when a model is \x05destroyed\x06."]},{ref:"18.02",title:"Embarking",text:["Once the first battle round has started, a friendly unit can embark within a friendly \x03TRANSPORT\x04 model after making a \x05normal\x06, \x05advance\x06 or \x05fall-back move\x06, if \x01all\x02 of the following conditions apply:",'• Each model in that unit is within 3" of that \x03TRANSPORT\x04.',"• That unit was not set up on the battlefield this turn.","• That unit is \x05eligible to embark\x06 within that \x03TRANSPORT\x04, as described on that \x03TRANSPORT\x04’s datasheet.","• That \x03TRANSPORT\x04 has sufficient remaining \x05transport capacity\x06 for each model in that unit.","When a unit embarks, the active player removes that unit from the battlefield and places it to one side – it is now embarked within that \x03TRANSPORT\x04 and is not on the battlefield."],accordions:[{ref:"18.02.01",title:"Able To Embark",text:["A unit is able to embark if it meets all of the conditions in Embarking (18.02). Note that one or more of these conditions may be modified by other rules, in which case a unit must satisfy those modified conditions in addition to any unmodified conditions to be able to embark."]}]},{ref:"18.03",title:"Disembarking",text:["In the active player’s Movement phase, each friendly unit embarked within a \x03TRANSPORT\x04 model can disembark from it by making a \x05disembark move\x06 (18.04).","If a \x03TRANSPORT\x04 model is destroyed, before removing it from the battlefield, the active player must make an \x05emergency disembark move\x06 (18.05) with each unit embarked within it."]},{ref:"18.04",title:"Disembark Move",text:["\x0eEligible If","\x01All\x02 of the following apply to your unit:","• Embarked within a \x03TRANSPORT\x04 model that is on the battlefield.","• Did not embark within that \x03TRANSPORT\x04 this phase.","• That \x03TRANSPORT\x04 has not made an \x05advance\x06 or \x05fall-back\x06 move this phase.","\x0eSet-up Distance",'- Rapid/Tactical Disembark: 3"','- Combat Disembark: 6"',"\x0eBefore Moving","Select \x05disembark mode\x06:","• \x05Rapid Disembark:\x06 If that \x03TRANSPORT\x04 made a \x05normal\x06 or \x05ingress move\x06 this phase, you must select this mode.","• \x05Tactical Disembark:\x06 Otherwise, If that \x03TRANSPORT\x04 \x05remained stationary\x06 or has not yet been \x05selected to move\x06 this phase, and if you can set up your unit as described below, you must select this mode.","• \x05Combat Disembark:\x06Otherwise, you must select this mode. Make a \x05hazard roll\x06 for each model in your unit.","\x0eWhile Moving","Set up each model in your unit wholly within the \x05set-up distance\x06 of that \x03TRANSPORT\x04.","• \x05Rapid Disembark:\x06 If that \x03TRANSPORT\x04 made an \x05ingress move\x06 this turn, each model must follow the same rules that \x03TRANSPORT\x04 had to follow while resolving that move.","• \x05Combat Disembark:\x06 Each model can be set up \x05engaged\x06 with one or more enemy units that \x03TRANSPORT\x04 is \x05engaged\x06 with.","\x0eEffect","Your unit is set up as described in Set Up (03.02)","\x0eAfter Moving","• \x05Rapid Disembark:\x06 Until the end of the turn, your unit is \x01not\x02 \x05eligible to declare a charge\x06.","• \x05Tactical Disembark:\x06 Select your unit to make a \x05normal\x06 or \x05advance move\x06.","• \x05Combat Disembark:\x06 Your unit is \x05battle-shocked\x06 and, until the end of the turn, it is \x01not\x02 \x05eligible to declare a charge\x06."],accordions:[{ref:"18.04.01",title:"Rapid Disembark And Limitations",text:['When a unit uses the \x05rapid disembark\x06 mode after its \x03TRANSPORT\x04 makes an \x05ingress move\x06, the models must follow the same rules and restrictions as that \x03TRANSPORT\x04 did. For example, if that \x03TRANSPORT\x04 had to be set up more than 8" from all enemy units and not within your opponent’s deployment zone, the same applies to the disembarking unit.']}]},{ref:"18.05",title:"Emergency Disembark Move",text:["\x0eEligible If","Your unit is embarked within a \x03TRANSPORT\x04 model that was just \x05destroyed\x06.","\x0eBefore Moving","Make a \x05hazard roll\x06 for each model in your unit (06.03)","\x0eWhile Moving","Set up each model in your unit:","• Wholly within the \x05set-up distance\x06 of that \x03TRANSPORT\x04, and as close as possible to that \x03TRANSPORT\x04.","• \x01Or:\x02 If the above is not possible while remaining \x05unengaged\x06, set up that model wholly within the \x05set-up distance\x06 of that \x03TRANSPORT\x04, as close as possible to that \x03TRANSPORT\x04, and \x05engaged\x06.","Each model that still cannot be set up is \x05destroyed\x06.","\x0eEffect","Your unit is set up as described in Set Up (03.02)","\x0eAfter Moving","Your unit is \x05battle-shocked\x06 and, until the end of the turn, it is \x01not\x02 \x05eligible to declare a charge\x06.","\x0eMaximum Distance",'SET-UP DISTANCE: 6"']},{ref:"18.06",title:"Assault Disembark Move",text:["\x0eEligible If","As stated in the rule allowing this \x05move type\x06, if all of the following apply to your unit:","• Embarked within a \x03TRANSPORT\x04 model that is on the battlefield.","• Did not embark within that \x03TRANSPORT\x04 this phase.","• That \x03TRANSPORT\x04 has not made an \x05advance/fall‑back\x06 move this phase.","\x0eSet-up Distance",'3"',"\x0eWhile Moving","Set up each model in your unit wholly within the \x05set‑up distance\x06 of that \x03TRANSPORT\x04.","\x0eEffect","Your unit is set up as described in Set Up (Core Rules, 03.02)."]},{ref:"18.07",title:"Shock Disembark Move",text:["\x0eEligible If","As stated in the rule allowing this \x05move type\x06, if all of the following apply to your unit:","• Embarked within a \x03TRANSPORT\x04 model that is on the battlefield.","• Did not embark within that \x03TRANSPORT\x04 this phase.","\x0eSet-up Distance",'3"',"\x0eWhile Moving","Set up each model in your unit wholly within the \x05set‑up distance\x06 of that \x03TRANSPORT\x04.","\x0eEffect","Your unit is set up as described in Set Up (Core Rules, 03.02).","\x0eAfter Moving","Your unit is \x01not\x02 \x05eligible to declare a charge\x06 until the end of the turn."]}]},{number:"19",title:"Attached Units",subsections:[{ref:"19.01",title:"Forming Attached Units",text:["Some units have the \x05Leader\x06 or \x05Support\x06 ability listed on their datasheet (24.22 & 24.34). Such units are known as \x05leader\x06 units and \x05support\x06 units respectively. Both of these abilities allow such units to lead other friendly units (known as \x05bodyguard\x06 units) to form \x05attached\x06 units. An attached unit is a single unit for all rules purposes. \x05Leader\x06 and \x05support\x06 units can only lead specific \x05bodyguard\x06 units, as listed in the Warhammer 40,000 app"],accordions:[{ref:"19.01.01",title:"Attached Units After Their Bodyguard Unit is Destroyed",text:["Some units have rules stating that when the \x05bodyguard\x06 unit in an \x05attached\x06 unit is \x05destroyed\x06, \x05leader/support\x06 units that were attached to them become separate units with their original \x05starting strengths\x06.","When the \x05bodyguard\x06 unit in an \x05attached\x06 unit affected by such a rule is \x05destroyed\x06, all of those \x05leader/support\x06 units remain a single unit for all rules purposes."]}]},{ref:"19.02",title:"Attacking Attached Units",text:["Each time an attack targets an \x05attached\x06 unit, if that unit contains one or more \x05bodyguard\x06 models, use the highest \x05T\x06 characteristic of the \x05bodyguard\x06 models in that unit while resolving that attack, even if a \x05leader\x06/\x05support\x06 unit in that \x05attached\x06 unit has a different \x05T\x06 characteristic. If that unit only contains \x05leader\x06/\x05support\x06 models, use the highest \x05T\x06 characteristic of those models while resolving that attack instead.","Rules that are triggered when a unit is \x05destroyed\x06 are only triggered when the last model that started the battle in an \x05attached\x06 unit is \x05destroyed\x06."]},{ref:"19.03",title:"Keywords In Attached Units",text:["An \x05attached\x06 unit has all of the keywords of all of its component units. As such, an \x05attached\x06 unit is affected by any rule that applies to units with any of those keywords. Note that models in an \x05attached\x06 unit do not gain the keywords of other models in that unit that they do not already have. Remember that attacks target units, not models.","\x05Example\x06: \x07An \x05attached\x06 unit contains a \x05leader\x06 model with the \x03PSYKER\x04 keyword. While that model is part of that unit, that unit has the \x03PSYKER\x04 keyword, even if the \x05bodyguard\x06 models do not have that keyword. If that unit is attacked by a weapon with the \x03[ANTI‑PSYKER 4+]\x04 ability, any unmodified \x05wound roll\x06 of 4+ made against that unit is a \x05critical wound\x06, even if the attack itself is not allocated to that \x05leader\x06 model.\b"]},{ref:"19.04",title:"Abilities In Attached Units",text:["Abilities/rules that affect a single specified model (e.g. from an \x05enhancement\x06 or an item of wargear) only ever apply to that model, even while part of an \x05attached\x06 unit.","Otherwise, abilities/rules that affect a unit (or models in it) apply to every model in an \x05attached\x06 unit, until the source of that ability/rule is \x05destroyed\x06, as shown below.","*\x07This means \x05leader/support\x06 units continue to benefit from their own 'while this model is \x05leading\x06 a unit' abilities even after their \x05bodyguard\x06 unit is \x05destroyed\x06, provided they started the battle in an \x05attached\x06 unit.\b","In all of the above cases, if that last model was \x05destroyed\x06 as the result of an attack, the ability it was conferring upon the \x05attached\x06 unit applies until the attacking unit has resolved all of its attacks."],tables:[{rows:[["SOURCE OF ABILITY/RULE","APPLIES TO THE ATTACHED UNIT UNTIL"],["\x05Leader/support unit\x06","The last model in that \x05leader/support\x06 unit is \x05destroyed\x06.*"],["\x05Bodyguard unit\x06(e.g. from a datasheet ability)","The last model in that \x05bodyguard\x06 unit is \x05destroyed\x06"],["\x05A specific model\x06(e.g. the bearer of an \x05enhancement\x06 or an item of wargear)","That model is \x05destroyed\x06"]]}],accordions:[{ref:"19.04.01",title:"Only In Death Does Duty End",text:["\x05Leader\x06 and \x05support\x06 units often have abilities that make the models they are leading more powerful. In the same way, some \x05bodyguard\x06 units’ abilities can enhance the power of those leading them. Abilities in Attached Units (19.04) means that once the models conferring such effects are \x05destroyed\x06, that \x05attached\x06 unit does not continue to benefit from them. Should those models later be \x05revived\x06, however, those abilities will once more apply to their \x05attached\x06 unit."]}]}]},{number:"20",title:"Strategic Reserves",subsections:[{ref:"20.01",title:"Placing Units In Strategic Reserves",text:["Before the battle, in the Declare Battle Formations step, you can select one or more friendly units (excluding \x03FORTIFICATIONS\x04) to place in \x05strategic reserves\x06. Instead of setting up these units on the battlefield during deployment, place them to one side; they are \x05strategic reserves\x06 units, and will arrive later in the battle.","Unless otherwise stated, the combined points value of all of your \x05strategic reserves\x06 units (including those embarked within \x03TRANSPORTS\x04 that are themselves placed in \x05strategic reserves\x06) cannot exceed 50% of your points limit for your battle size."],accordions:[{ref:"20.01.01",title:"Reserves",text:["The term 'Reserves' is the same as \x05strategic reserves\x06."]},{ref:"20.01.02",title:"Strategic Reserves at the End of the Battle",text:["At the end of the final turn, units in \x05strategic reserves\x06 are \x05destroyed\x06, but they do not trigger rules that apply when a model is \x05destroyed\x06."]}]},{ref:"20.02",title:"Repositioned Units",text:["Some rules allow units to be removed from the battlefield and placed in \x05strategic reserves\x06 during the battle. Units that use such rules are known as \x05repositioned\x06 units. In addition to any other rules that apply to such units (such as where they can or cannot arrive), \x01all\x02 of the following rules apply to them:","• If used in the Movement phase, such rules can be used on units that have already moved that phase.","• A \x05repositioned\x06 unit that is set up in the same turn in which it made an \x05advance\x06, \x05fall-back\x06 or \x05disembark move\x06 has still made an \x05advance\x06, \x05fall-back\x06 or \x05disembark move\x06 that turn.","• When they are removed from the battlefield, any rules that are affecting such units for a specified duration or under specified circumstances continue to affect them while that duration and/or those circumstances apply.","\x05Example:\x06 \x07A unit that was within range of an \x05aura ability\x06 when removed from the battlefield would no longer be affected by that \x05aura ability\x06 if it is no longer within range of it when it makes an \x05ingress move\x06, but a unit that was \x05battle-shocked\x06 when removed from the battlefield would still be \x05battle-shocked\x06 if it makes an \x05ingress move\x06 in the same turn.\b"]},{ref:"20.03",title:"Arriving From Strategic Reserves",text:["To arrive on the battlefield, each \x05strategic reserves\x06 unit must make an \x05ingress move\x06 (20.04). Unless otherwise stated, they can only do so from the second battle round onwards.","At the end of the third battle round, unless otherwise stated, all \x05strategic reserves\x06 units that have not made one or more \x05ingress moves\x06 are \x05destroyed\x06, with the following exceptions:","• Units embarked within \x03TRANSPORTS\x04 that have made an \x05ingress move\x06 during the battle.","• Repositioned units (20.02)."],accordions:[{ref:"20.03.01",title:"Set Up As Reinforcements",text:["If a rule mentions a unit being set up on the battlefield as Reinforcements, it means a unit that made an \x05ingress move\x06."]}]},{ref:"20.04",title:"Ingress Move",text:["\x0eEligible If","Your unit is in \x05strategic reserves\x06 (excluding units that are embarked within \x03TRANSPORTS\x04 that are themselves in \x05strategic reserves\x06)","\x0eSet-up Distance",'6"',"\x0eWhile Moving",'Set up your unit wholly within the \x05set-up distance\x06 of one or more battlefield edges and more than 8" horizontally from all enemy units.',"• \x05Before the Third Battle Round:\x06 While doing so, no models can be set up within your opponent’s deployment zone.","\x0eEffect","Your unit is set up as described in Set Up (03.02)","\x0eAfter Moving","Unless otherwise stated, until the start of the next Charge phase, your unit is \x01not\x02 eligible to make any other type of move."]}]},{number:"21",title:"Flying and Surging",subsections:[{ref:"21.01",title:"Surge Moves",text:["Some rules allow a unit to make a \x05surge move\x06 (21.02).","\x0eMaking a Surge Move","• Unit \x05\x07A\b\x06 shoots, and \x05\x07destroys\b\x06 two models from unit \x05\x07B\b\x06.",'• Unit \x05\x07B\b\x06 has an ability that allows it to make a \x05\x07surge move\b\x06 of D6" after an enemy unit has shot, if one or more of its models were \x05\x07destroyed\b\x06 by those attacks. The active player rolls one D6, resulting in a 4.','• Unit \x05\x07B\b\x06 makes a \x05\x07surge move\b\x06, each of its surviving models moving up to 4" towards the closest enemy unit (unit \x05\x07C\b\x06). It ends this move \x05\x07engaged\b\x06 with that unit.']},{ref:"21.02",title:"Surge Move",text:["\x0eEligible If","\x01All\x02 of the following apply:","• The rule allowing this \x05move type\x06 has been triggered.","• Your unit is not \x05battle-shocked\x06.","• Your unit is \x05unengaged\x06.","• Your unit has not moved this phase.","\x0eBefore Moving","Select the closest enemy unit to be the \x05surge target\x06.","\x0eWhile Moving","• Each model must end its move \x05engaged\x06 with the \x05surge target\x06 if possible.","• Each model that cannot end its move \x05engaged\x06 with the \x05surge target\x06 must end its move as close as possible to the \x05surge target\x06.","\x0eEffect","Your unit moves as described in Moving (03).","\x0eAfter Moving","• Your unit cannot be \x05engaged\x06 with one or more enemy units that were not the \x05surge target\x06.","• Your unit cannot move again this phase.","\x0eMaximum Distance","As stated in the rule allowing this \x05move type\x06."]},{ref:"21.03",title:"Flying Models",text:["Models with the \x03FLY\x04 keyword, and units such models are part of, are said to be able to \x03FLY\x04. Some rules also refer to such models/units as \x03FLYING\x04 models/\x03FLYING\x04 units.","Each time a \x03FLYING\x04 unit is selected to make a \x05normal\x06, \x05advance\x06, \x05fall-back\x06 or \x05charge move\x06, before moving any models in that unit, the active player can declare that it will \x03take to the skies\x04. If it does, while resolving that move:",'• Subtract 2" from the \x05maximum distance\x06.',"• Each time a \x03FLYING\x04 model moves:","◦ Ignore all vertical distance for the purposes of how far it has moved.","◦ It can move through all types of model (including enemy models and \x03MONSTER/VEHICLE\x04 models).","◦ It can move horizontally and vertically through all categories of \x05terrain feature\x06.","\x0eTaking to the Skies",'• This Riptide Battlesuit can \x03Fly\x04. It makes an \x05\x07advance move\b\x06 with a \x05\x07maximum distance\b\x06 of 16".','• Before moving the unit, the active player declares that it will \x05\x07take to the skies\b\x06. That move’s \x05\x07maximum distance\b\x06 is reduced to 14", but while making that move, the Riptide Battlesuit can move through all enemy units (including \x03Vehicles\x04) and all \x05\x07terrain features\b\x06, ignoring any vertical distance that would normally be counted to ascend and descend \x05\x07terrain features\b\x06.']}]},{number:"22",title:"Other Rules And Abilities",subsections:[{ref:"22.01",title:"Aura Abilities",text:["Abilities that affect models or units within a stated range are \x05aura abilities\x06, and are tagged with the word ‘Aura’.","While a model with an \x05aura ability\x06 is on the battlefield, it is always within range of its own \x05aura ability\x06.","A unit can be affected by more than one \x05aura ability\x06 at a time, but if a unit is within range of the same \x05aura ability\x06 more than once, that \x05aura ability\x06 only applies to that unit once."]},{ref:"22.02",title:"Faction Abilities",text:["Some abilities are common to each unit that belongs to a particular faction – these are \x05faction abilities\x06 (also known as \x05army rules\x06), and are listed in the Faction Abilities section of a datasheet.","Unless otherwise stated, a unit’s \x05faction abilities\x06 only apply if the \x05army faction\x06 you selected while mustering your army matches a faction keyword listed on that unit’s datasheet."]},{ref:"22.03",title:"Psychic Abilities",text:["Abilities tagged with the word ‘Psychic’ are \x05psychic abilities\x06. If a \x05psychic ability\x06 causes a model to lose one or more wounds, each of those wounds is said to be inflicted by a \x05psychic attack\x06 (this can be important for the triggering of other rules)."],accordions:[{ref:"22.03.01",title:"Psychic Abilities with a Psychic Level",text:["When using \x05psychic abilities\x06 with a \x05psychic level\x06, a \x03PSYKER\x04 unit cannot use the same \x05psychic ability\x06 more than once per phase."]}]},{ref:"22.04",title:"Wargear Abilities",text:["Abilities that are gained when a unit (or one of its models) has a particular item of wargear are \x05wargear abilities\x06, and are listed in the Wargear Abilities section of a datasheet.","If a unit has an item of wargear that has a \x05wargear ability\x06, that ability applies to that unit. If a model within a unit has an item of wargear that has a \x05wargear ability\x06, that model is the ‘bearer’ of that item of wargear and that ability applies until that model is \x05destroyed\x06."]},{ref:"22.05",title:"Plunging Fire",text:["Each time a model makes a ranged attack that targets a \x05visible unit\x06 containing one or more models on ground level, if one or more of the following conditions apply, improve the \x05BS\x06 characteristic of that attack by 1:",'• The attacking model is on a section of a \x05terrain feature\x06 that is 3" or more in height.','• The attacking model has the \x03TOWERING\x04 keyword and the target unit is within 12".',"\x0ePlunging Fire",'All the attacking models in unit \x05\x07A\b\x06 are on a section of \x05\x07terrain feature\b\x06 that is 3" or more in height, and the target unit contains models on ground level, so \x05\x07Plunging Fire\b\x06 improves the \x05\x07BS\b\x06 characteristic of those attacks by 1.','Attacking model \x05\x07B\b\x06 is on ground level, but has the \x03Towering\x04 keyword. The target unit is within 12" and contains models on ground level, so \x05\x07Plunging Fire\b\x06 improves the \x05\x07BS\b\x06 characteristic of those attacks by 1.']}]},{number:"23",title:"Aircraft",subsections:[{ref:"23.01",title:"Aircraft Deployment",text:["• In the Declare Battle Formations step, all \x03AIRCRAFT\x04 units must be placed in \x05strategic reserves\x06 (20.01)."]},{ref:"23.02",title:"Aircraft Movement",text:["• \x03AIRCRAFT\x04 units are only eligible to make an \x05ingress move\x06 (20.04); they are \x01not\x02 eligible to make any other type of move.","• At the end of your opponent’s turn, all \x03AIRCRAFT\x04 units in your army that are on the battlefield must be placed in \x05strategic reserves\x06.","• Each time a unit makes any type of move, its models can be moved through \x03AIRCRAFT\x04 models.","• Each time a unit makes a \x05pile-in\x06, \x05consolidation\x06 or \x05surge move\x06, unless that unit can \x03FLY\x04, while making that move, ignore \x03AIRCRAFT\x04 units for the purposes of selecting enemy units and determining the closest enemy unit.","• Being \x05engaged\x06 solely with one or more \x03AIRCRAFT\x04 units does not prevent a unit from being eligible to make a \x05normal\x06 or \x05advance move\x06."]},{ref:"23.03",title:"Shooting With Or At Aircraft",text:["• The \x05Plunging Fire\x06 rule (22.05) has no effect on attacks made by, or targeting, \x03AIRCRAFT\x04 units."]},{ref:"23.04",title:"Aircraft Charging And Fighting",text:["• \x03AIRCRAFT\x04 units are \x01not\x02 \x05eligible to declare a charge\x06, and can only make melee attacks that target \x03FLYING\x04 units.","• Only \x03FLYING\x04 units can select \x03AIRCRAFT\x04 units as a \x05charge target\x06, and only \x03FLYING\x04 models can make melee attacks that target \x03AIRCRAFT\x04 units."]}]},{number:"24",title:"Core Abilities",subsections:[{ref:"24.01",title:"Abilities",text:["Many units have \x05core abilities\x06 listed on their datasheets, and \x05weapon abilities\x06 listed in their weapon profiles.","\x05Weapon abilities\x06 are presented in square brackets with bold formatting, e.g. \x03[BLAST]\x04. Weapons are often described using a particular ability they have, e.g. \x03[BLAST] weapons\x04 are those with the \x03[BLAST]\x04 ability.","If a \x05weapon ability\x06 is followed by one or more keywords, when making attacks with that weapon, that ability only applies if the target unit has one or more of those keywords.","\x05Example:\x06 \x07The \x03[LETHAL HITS: VEHICLE]\x04 ability only applies to attacks that target a \x03VEHICLE\x04 unit. The \x03[SUSTAINED HITS 1: INFANTRY/BEASTS]\x04 ability only applies to attacks that target an \x03INFANTRY/BEASTS\x04 unit.\b"],accordions:[{ref:"24.01.01",title:"With The 'X' Ability",text:["Some rules affect or require you to select a model or unit with a particular ability. When resolving such rules, any numbers following the ability are irrelevant when determining if such rules apply.","\x05Example\x06: \x07If a rule instructs you to select a model from your army with the \x05Deadly Demise\x06 ability, you could select a model with the \x05Deadly Demise 1\x06, \x05Deadly Demise D3\x06 or \x05Deadly Demise D6\x06 ability.\b"]}]},{ref:"24.02",title:"Duplicated Abilities",text:["Multiple instances of the same \x05core ability\x06 or \x05weapon ability\x06 are not cumulative, regardless of any numbers or keywords included in them. In such cases, the controlling player must select which instance will apply at any one time. In the case of duplicated \x05weapon abilities\x06, this selection must be made each time that unit makes attacks, in the Select Weapons step.",'• Multiple instances of \x05core abilities\x06 that include a number are duplicated even if that number varies. However, in the case of \x05Scouts\x06, you must select the lowest number not shared by every model in that unit (e.g. if every model in a unit has both \x05Scouts 6"\x06 and \x05Scouts 8"\x06, you could select \x05Scouts 8"\x06 as it is shared by every model, but if a unit contains one model with \x05Scouts 6"\x06 and five with \x05Scouts 8"\x06, you must select \x05Scouts 6"\x06).',"• Multiple instances of \x05weapon abilities\x06 that include a number (e.g. \x03[SUSTAINED HITS 1]\x04) are duplicated even if that number varies (e.g. the controlling player would have to select between \x03[SUSTAINED HITS 1]\x04 and \x03[SUSTAINED HITS 2]\x04).","• Multiple instances of \x05weapon abilities\x06 that include a keyword are duplicated even if that keyword varies (e.g. the controlling player would have to select between \x03[ANTI‑VEHICLE 4+]\x04 and \x03[ANTI‑INFANTRY 2+]\x04)."]},{ref:"24.03",title:"[ANTI]",text:["This ability always takes the form \x03[ANTI‑X Y+]\x04. Each time an attack is made with an \x05[ANTI]\x06 weapon, if the target unit has the keyword denoted by \x05X\x06, an unmodified \x05wound roll\x06 of \x05Y+\x06 is a \x05critical wound.\x06","\x05Example:\x06 \x07An attack made with an \x03[ANTI‑VEHICLE 4+]\x04 weapon against a \x03VEHICLE\x04 unit will result in a \x05critical wound\x06  on an unmodified wound roll of 4+, while an attack made with an \x03[ANTI‑PSYKER 2+]\x04 weapon against a \x03PSYKER\x04 unit will result in a \x05critical wound\x06  on an unmodified wound roll of 2+.\b"]},{ref:"24.04",title:"[ASSAULT]",text:["Units containing one or more models with an \x03[ASSAULT]\x04 weapon can shoot using \x05assault shooting\x06 (10.05)."]},{ref:"24.05",title:"[BLAST]",text:["Each time you gather \x05attack dice\x06 for a \x03[BLAST]\x04 weapon, add one additional \x05attack dice\x06 for every five models that were in the target unit in the Select Targets step (rounding down).","If this ability takes the form \x03[BLAST X]\x04, each time you gather \x05attack dice\x06 for such a weapon, add \x05X\x06 additional \x05attack dice\x06 for every five models that were in the target unit in the Select Targets step (rounding down) instead.","\x05Example:\x06 \x07If a \x03[BLAST 2]\x04 weapon with an \x05A\x06 characteristic of 3 targets a unit containing 12 models, you would gather four additional \x05attack dice\x06 for that weapon (for a total of seven for that weapon).\b"]},{ref:"24.06",title:"[CLEAVE]",text:["This ability always takes the form \x03[CLEAVE X]\x04. Each time you gather \x05attack dice\x06 for a \x03[CLEAVE]\x04 weapon, if you only selected one target for all of that weapon’s attacks, add \x05X\x06 additional \x05attack dice\x06 for every five models that were in the target unit in the Select Targets step (rounding down).","\x05Example:\x06 \x07If a \x03[CLEAVE 1]\x04 weapon with an \x05A\x06 characteristic of 3 targets one unit containing 16 models, you would gather three additional \x05attack dice\x06 for that weapon (for a total of six for that weapon).\b"]},{ref:"24.07",title:"[CLOSE-QUARTERS]",text:["Units containing one or more models with a \x03[CLOSE‑QUARTERS]\x04 weapon can shoot using \x05close‑quarters shooting\x06 (10.06).","When using another \x05shooting type\x06, for each model in that unit (excluding \x05MONSTER/VEHICLE\x06 models), you can only select \x01one\x02 of the following to make attacks with:","• One or more of its \x03[CLOSE‑QUARTERS]\x04 weapons.","• One or more of its other ranged weapons."]},{ref:"24.08",title:"Deadly Demise",text:['This ability always takes the form \x05Deadly Demise X\x06. Each time a model with this ability is \x05destroyed\x06, after the units embarked within it (if any) have made their \x05emergency disembark moves\x06, roll one D6. On a 6, that model suffers a \x05deadly demise\x06; each unit within 6" of that model suffers a number of \x05mortal wounds\x06 denoted by \x05X\x06 (if this is a random number, roll separately for each unit within 6").']},{ref:"24.09",title:"Deep Strike",text:['Each time this unit makes an \x05ingress move\x06 (20.04), if every model in this unit has this ability, it can be set up anywhere on the battlefield that is more than 8" horizontally from all enemy units, even if that is within your opponent’s deployment zone.']},{ref:"24.10",title:"[DEVASTATING WOUNDS]",text:["Each time an attack made with a \x03[DEVASTATING WOUNDS]\x04 weapon results in a \x05critical wound\x06, the attack sequence for that attack ends and the target unit suffers a number of \x05mortal wounds\x06 equal to the \x05D\x06 characteristic of that weapon. These are inflicted after resolving any normal damage inflicted by those attacks.","\x05Mortal wounds\x06 inflicted by \x03[DEVASTATING WOUNDS]\x04 weapons can damage a maximum of one model for each \x05critical wound\x06; any remaining \x05mortal wounds\x06 inflicted by that attack are lost.","\x05Example\x06: \x07An attack made with a \x03[DEVASTATING WOUNDS]\x04 weapon with a \x05D\x06 characteristic of 3 results in a \x05critical wound\x06 against an Intercessor Squad, so inflicts 3 \x05mortal wounds\x06. The first 2 \x05mortal wounds\x06 are sufficient to destroy 1 Intercessor model, so the remaining \x05mortal wound\x06 is lost.\b"]},{ref:"24.11",title:"[EXTRA ATTACKS]",text:["Each time a unit containing one or more models with an \x03[EXTRA ATTACKS]\x04 weapon fights, those models will make attacks with those weapons in addition to any others. In the Select Weapons step (04.01), for each of those models, you must select:","• All of that model’s \x03[EXTRA ATTACKS]\x04 weapons.","• One of that model’s other melee weapons, if possible."],accordions:[{ref:"24.11.01",title:"Only [EXTRA ATTACKS] weapons",text:["If a unit has \x03[Extra Attacks]\x04 weapons, it does not need to select weapons without the \x03[Extra Attacks]\x04 ability in order to make attacks with those \x03[Extra Attacks]\x04 weapons."]}]},{ref:"24.12",title:"Feel No Pain",text:["This ability always takes the form \x05Feel No Pain X+\x06. Each time a model with this ability would lose a wound, roll one D6: on an \x05X+\x06, that wound is not lost."]},{ref:"24.13",title:"Fights First",text:["While every model in a unit has this ability, that unit is a \x05Fights First\x06 unit.","See the Resolve Fights First Combats step in the Fight phase (12.04)."]},{ref:"24.14",title:"Firing Deck",text:["This ability always takes the form \x05Firing Deck X\x06. In your Shooting phase, each time this \x03TRANSPORT\x04 is \x05selected to shoot\x06, if one or more units are embarked within it, resolve the following sequence:","1. Select up to \x05X\x06 models embarked within this \x03TRANSPORT\x04 (excluding models whose units have already been \x05selected to shoot\x06 this phase).","2. For each selected model, select one of its ranged weapons (excluding \x03[ONE SHOT]\x04 weapons).","3. Until this \x03TRANSPORT\x04 has resolved all of its attacks, it has all of those selected weapons in addition to its other weapons.","4. Until the end of the turn, units embarked within this \x03TRANSPORT\x04 are \x01not\x02 \x05eligible to shoot\x06."]},{ref:"24.15",title:"[HAZARDOUS]",text:["Each time a unit is \x05selected to shoot\x06 or \x05selected to fight\x06, after that unit has resolved all of its attacks, make a number of \x05hazard rolls\x06 (06.03) for that unit equal to the number of \x03[HAZARDOUS]\x04 weapons you selected in the Select Weapons step."]},{ref:"24.16",title:"[HEAVY]",text:["In your Shooting phase, each time an attack is made with a \x03[HEAVY]\x04 weapon, add 1 to the \x05hit roll\x06 if \x01all\x02 of the following apply to the attacking unit:","• That unit is \x05unengaged\x06.","• That unit was not set up on the battlefield this turn.",'• No model in that unit has moved moret han 3" this turn.']},{ref:"24.17",title:"Hover",text:['Each time this unit \x05takes to the skies\x06 (21.03), do not subtract 2" from the \x05maximum distance\x06.']},{ref:"24.18",title:"[IGNORES COVER]",text:["Each time an attack is made with an \x03[IGNORES COVER]\x04 weapon, the target cannot have the \x05benefit of cover\x06 against that attack (13.08), including from rules that give a model or unit the \x05benefit of cover\x06 (e.g. \x05Stealth\x06)."]},{ref:"24.19",title:"[INDIRECT FIRE]",text:["Units containing one or more models with an \x03[INDIRECT FIRE]\x04 weapon can shoot using \x05indirect shooting\x06 (10.07)."]},{ref:"24.20",title:"Infiltrators",text:['During deployment, if every model in a unit has this ability, it can be set up anywhere on the battlefield that is more than 8" horizontally from your opponent’s deployment zone and all enemy units.']},{ref:"24.21",title:"[LANCE]",text:["Each time an attack is made with a \x03[LANCE]\x04 weapon, if the attacking model’s unit made a \x05charge\x06 move this turn, add 1 to the \x05wound roll\x06."]},{ref:"24.22",title:"Leader",text:["Before the battle, in the Muster Armies step, for each \x05leader\x06 and \x05support\x06 unit in your army, you can select one friendly \x05bodyguard\x06 unit that unit can \x05lead\x06. That unit will then \x05lead\x06 that \x05bodyguard\x06 unit for the battle and form an \x05attached\x06 unit with it.","Unless otherwise stated, each \x05bodyguard\x06 unit can only have one \x05leader\x06 unit and one \x05support\x06 unit attached to it.","See Attached Units (19)"]},{ref:"24.23",title:"[LETHAL HITS]",text:["Each time an attack made with a \x03[LETHAL HITS]\x04 weapon results in a \x05critical hit\x06, you can choose for that attack to automatically wound the target.","\x05Designer’s Note:\x06 \x07Choosing to automatically wound the target means that no \x05wound roll\x06 is made for that attack. You may decide against this, as it means that attack cannot result in a \x05critical wound\x06 and so cannot trigger other abilities such as \x03[DEVASTATING WOUNDS]\x04.\b"]},{ref:"24.24",title:"Lone Operative",text:['Unless part of an \x05attached\x06 unit, this unit is \x01not\x02 \x05visible\x06 to enemy models unless they are within 12" of this unit, and it cannot be targeted by \x03[INDIRECT FIRE]\x04 weapons unless the attacking model is within 12" of this unit.','If this ability takes the form \x05Lone Operative X"\x06, unless part of an \x05attached\x06 unit, this unit is \x01not\x02 \x05visible\x06 to enemy models unless they are within \x05X"\x06 of this unit, and it cannot be targeted by \x03[INDIRECT FIRE]\x04 weapons unless the attacking model is within \x05X"\x06 of this unit.'],accordions:[{ref:"24.24.01",title:"Attached units and Lone Operative",text:["If all models in an \x05attached\x06 unit have \x05Lone Operative\x06, that unit will benefit from \x05Lone Operative\x06.","If a unit has \x05Lone Operative\x06, but models in that unit have different range values for \x05Lone Operative\x06, the highest value amongst that unit's models on the battlefield is applied to the whole unit.","If an \x05attached\x06 unit \x05below starting strength\x06 only contains models with \x05Lone Operative\x06, \x05Lone Operative\x06 becomes active again.",'\x05Example:\x06 \x07A \x03Character\x04 with \x05Lone Operative\x06 is attached to a \x05bodyguard\x06 unit that has \x05Lone Operative 15"\x06. \x05Lone Operative 15"\x06 is therefore used for the whole unit.\b',"\x05Example:\x06 \x07A \x03Character\x04 with \x05Lone Operative\x06 is attached to a \x05bodyguard\x06 unit that does not have \x05Lone Operative\x06. Once all of the \x05bodyguard\x06 models have been \x05destroyed\x06 and only the \x03Character\x04 remains, the \x03Character\x04's \x05Lone Operative\x06 becomes active again.\b"]}]},{ref:"24.25",title:"[MELTA]",text:["This ability always takes the form \x03[MELTA X]\x04. Each time a model makes an attack with a \x03[MELTA]\x04 weapon, if the target unit was within half range of that weapon in the Select Targets step, until the attacking unit’s attacks have been resolved, add \x05X\x06 to that weapon’s \x05D\x06 characteristic.","\x05Example:\x06 \x07A model targets a unit that is within half range of a \x03[MELTA 2]\x04 weapon with a \x05D\x06 characteristic of D6. While resolving those attacks, that weapon has a \x05D\x06 characteristic of D6+2\b"]},{ref:"24.26",title:"[ONE SHOT]",text:["Each weapon with this ability can only be selected to make attacks with once per battle.","If a \x05destroyed\x06 model is returned to a unit, all of its \x03[ONE SHOT]\x04 weapons that have already been selected to make attacks with during the battle cannot be selected to make attacks with again.","If a new unit is added to an army, all \x03[ONE SHOT]\x04 weapons in that unit can be selected to make attacks with once per battle."],accordions:[{ref:"24.26.01",title:"Multiple [ONE SHOT] Weapons",text:["If a model is equipped with more than one of the same weapon with the [ONE SHOT] ability (e.g. 2 hunter-killer missiles), that model can shoot with each of those weapons once per battle."]}]},{ref:"24.27",title:"[PISTOL]",text:["\x03[PISTOL]\x04 and \x03[CLOSE‑QUARTERS]\x04 are identical for all rules purposes. See \x03[CLOSE‑QUARTERS]\x04.","\x05Designer’s Note:\x06 \x03[PISTOL]\x04 \x07is a pre-existing ability that will be superseded by \x03[CLOSE-QUARTERS]\x04 as this edition of Warhammer 40,000 progresses. Both are functionally the same, but the latter is a more suitable term for weapons that function in this way.\b"]},{ref:"24.28",title:"[PRECISION]",text:["While resolving attacks made with one or more \x03[PRECISION]\x04 weapons, at the start of the Allocation Order step (05.03), if the target unit contains one or more \x05CHARACTER\x06 models \x05visible\x06 to one or more of the attacking models, the active player can select one allocation group that contains one of those \x05visible\x06 \x03CHARACTER\x04 models. If they do, until those attacks are resolved, or until that \x03CHARACTER\x04 group is destroyed (whichever happens first), that \x03CHARACTER\x04 group is the current allocation group."],accordions:[{ref:"24.28.01",title:"Precision and Devastating Wounds",text:["\x05Mortal Wounds\x06 inflicted by a \x03[PRECISION]\x04 attack with the \x03[DEVASTATING WOUNDS]\x04 ability are first applied to the \x03CHARACTER\x04 group that was selected for those \x03[PRECISION]\x04 attacks (if that group is not already \x05destroyed\x06)."]}]},{ref:"24.29",title:"[PSYCHIC]",text:["Each time an attack is made with a \x03[PSYCHIC]\x04 weapon, you can ignore any or all modifiers to that attack’s \x05BS\x06 or \x05WS\x06 characteristic and any or all modifiers to the \x05hit roll\x06. Attacks made with \x03[PSYCHIC]\x04 weapons are known as \x05psychic attacks\x06 (this can be important for the triggering of other rules)."]},{ref:"24.30",title:"[RAPID FIRE]",text:["This ability always takes the form \x03[RAPID FIRE X]\x04. Each time you gather \x05attack dice\x06 for a \x03[RAPID FIRE]\x04 weapon, add \x05X\x06 additional \x05attack dice\x06 if the target unit was within half range of that weapon in the Select Targets step.","\x05Example:\x06 If a \x03[RAPID FIRE 1]\x04 weapon with an \x05A\x06 characteristic of 1 targets a unit that is within half range, you would gather one additional \x05attack dice\x06 for that weapon (for a total of two for that weapon)."]},{ref:"24.31",title:"Scouts",text:['This ability always takes the form \x05Scouts X"\x06. In the Resolve Pre‑battle Abilities step, if every model in a unit has this ability, you can do \x01one\x02 of the following:',"• If that unit is in \x05strategic reserves\x06, you can set up that unit anywhere that is wholly within your deployment zone.","• If that unit is wholly within your deployment zone, it can make a \x05scout move\x06 (24.32).","• If that unit is embarked within a \x03DEDICATED TRANSPORT\x04 that is wholly within your deployment zone, and if every model embarked within that \x03DEDICATED TRANSPORT\x04 has the \x05Scouts\x06 ability, that \x03DEDICATED TRANSPORT\x04 can make a \x05scout move\x06."]},{ref:"24.32",title:"Scout Move",text:["\x0eEligible If","It is the Resolve Pre-battle Abilities step, and your unit is wholly within your deployment zone.","\x0eEffect","Your unit moves as described in Moving (03).","\x0eAfter Moving",'Your unit must be more than 8" horizontally from all enemy units.',"\x0eMaximum Distance",'The \x05X"\x06 in \x05Scouts X"\x06']},{ref:"24.33",title:"Stealth",text:["If every model in a unit has this ability, each time a ranged attack targets that unit, that unit has the \x05benefit of cover\x06 against that attack (13.08)."]},{ref:"24.34",title:"Support",text:["Before the battle, in the Muster Armies step, for each \x05leader\x06 and \x05support\x06 unit in your army, you can select one friendly \x05bodyguard\x06 unit that unit can \x05lead\x06. That unit will then \x05lead\x06 that \x05bodyguard\x06 unit for the battle and form an \x05attached\x06 unit with it.","Unless otherwise stated, each \x05bodyguard\x06 unit can only have one \x05leader\x06 unit and one \x05support\x06 unit attached to it.","See Attached Units (19)."]},{ref:"24.35",title:"Super-Heavy Walker",text:["Each time a unit with this ability makes a \x05normal\x06, \x05advance\x06 or \x05fall-back move\x06:",'• Models in that unit can move through models (including \x03MONSTER/VEHICLE\x04 models, but excluding \x03TITANIC\x04 models) and can move horizontally through sections of \x05terrain features\x06 that are 4" or less in height.',"• Before moving that unit, you can select for all models in that unit to have the \x03MOBILE\x04 keyword until that move ends. If you do, when that move ends, roll one D6: on a 1, that unit is \x05battle-shocked\x06.","\x05Designer’s Note:\x06 \x07Gaining the \x03MOBILE\x04 keyword for the duration of a move will enable models in that unit to move horizontally through \x05dense terrain features\x06\b (13.06)."]},{ref:"24.36",title:"[SUSTAINED HITS]",text:["This ability always takes the form \x03[SUSTAINED HITS X]\x04. Each time an attack made with a \x03[SUSTAINED HITS]\x04 weapon results in a \x05critical hit\x06, that attack results in a number of additional hits on the target as denoted by \x05X\x06.","\x05Example:\x06 \x07An attack made with a \x03[SUSTAINED HITS 2]\x04 weapon results in a \x05critical hit\x06. That attack therefore hits the target three times (once from the \x05critical hit\x06, and twice more from the \x03[SUSTAINED HITS 2]\x04 ability).\b"]},{ref:"24.37",title:"[TORRENT]",text:["Each time an attack is made with a \x03[TORRENT]\x04 weapon, that attack automatically hits the target."],accordions:[{ref:"24.37.01",title:"",text:["\x03[TORRENT]\x04 weapons cannot have \x03[INDIRECT FIRE]\x04 or \x03[PRECISION]\x04."]}]},{ref:"24.38",title:"[TWIN-LINKED]",text:["Each time an attack is made with a \x03[TWIN‑LINKED]\x04 weapon, you can re‑roll the \x05wound roll\x06."]},{ref:"24.39",title:"Damaged",text:["This ability always takes the form \x05Damaged X\x06. While a model’s remaining wounds are equal to or less than \x05X\x06, that model is \x05damaged\x06:","• While a model is \x05damaged\x06, that model's attacks have -1 to \x05hit rolls\x06."]}]},{number:"25",title:"Muster Armies",subsections:[{ref:"25.01",title:"Start Your Army Roster",text:["The details of your army must be recorded on an army roster. You can either write this down or use the Warhammer 40,000 app. Players should show their finished army roster to their opponent before battle commences."]},{ref:"25.02",title:"Select Army Faction",text:["Note on your army roster one faction keyword to be your \x05army faction\x06."]},{ref:"25.03",title:"Select Battle Size",text:["With your opponent, select one of the battle sizes below. This will determine the total number of points (also known as the points total) each player can spend to build their army. The points values for units can be found in the Warhammer 40,000 app. You will need to refer to these when building your army.","The battle size will also determine the total number of Detachment Points (DP) players will have to unlock \x05detachments\x06 with, the number of units with the same datasheet name that they can include in their army, and the number of \x05enhancements\x06 that they can include in their army.","These are summarised below.","* The unit limit for \x03BATTLELINE\x04 and \x03DEDICATED TRANSPORT\x04 units is double the relevant amount shown above, and every \x03EPIC HERO\x04 has a unit limit of 1, regardless of the battle size."],tables:[{rows:[["BATTLE SIZE","Points Total","Detachment Points (DP)","Enhancement Limit","Unit Limit*"],["INCURSION","1000","2","2","2"],["STRIKE FORCE","2000","3","4","3"]]}]},{ref:"25.04",title:"Fill Your Army Roster",text:["You will now select your \x05detachments\x06, units, \x03warlord\x04 and \x05enhancements\x06 that will be in your army. You will also attach your \x05leader\x06 and \x05support\x06 units to other units.","When doing so:","• You cannot exceed any of the values presented in the Select Battle Size table (25.03). For example, in an Incursion battle, you cannot select \x05detachments\x06 with a combined value of more than 2 DP.","• No unit (including \x05attached\x06 units) can have more than one \x05enhancement\x06.","• Your army roster must follow all restrictions placed on it by the rules and units being included in it.","\x05SELECT DETACHMENTS\x06","You can now use your DP to select \x05detachments\x06 for your army. You can only select from those available to your \x05army faction\x06. Each one will give you access to different \x05force dispositions\x06, \x05detachment rules\x06, \x05enhancements\x06 and/or \x05stratagems\x06 to use in the coming battle. You cannot select the same \x05detachment\x06 more than once. Record your selected \x05detachments\x06 on your army roster.","Note that some \x05detachment rules\x06 list units and other \x05detachments\x06 that your army either must include or cannot include; you must follow all such rules when building your army for the \x05detachments\x06 you have selected.","\x05SELECT UNITS\x06","Select all the units you want to include in your army. You can only select units with your faction keyword and units available to your \x05army faction\x06. Each time you include a unit in your army, it can take any wargear or options it has access to. Note on your army roster the number of models in the unit, any wargear and upgrades it has, and its points value.","Select one \x03CHARACTER\x04 unit to be your Warlord’s unit. This must be a unit that has the faction keyword you chose as your \x05army faction\x06. Then select one \x03CHARACTER\x04 model in that unit to be your Warlord – the supreme leader of your army – and make a note of this on your army roster. That model gains the \x03WARLORD\x04 keyword. Some units have a rule on their datasheet stating that they must be your \x03WARLORD\x04. If you want to include one or more of these units in your army, you must select one of them to be your \x03WARLORD\x04. Rules that state that a model cannot be your \x03WARLORD\x04 take precedence over ones that require it to be your \x03WARLORD\x04.","\x05ATTACH LEADERS AND SUPPORT UNITS\x06","For each \x05leader\x06 and \x05support\x06 unit in your roster, you can attach them to a \x05bodyguard\x06 unit that they can join, following the rules for Forming Attached Units (19.01). Each \x05support\x06 unit in your roster must be attached to a \x05bodyguard\x06 unit.","\x05SELECT ENHANCEMENTS\x06","Select all of the \x05enhancements\x06 you want to include from the \x05detachments\x06 you selected and give each one to a different unit in your army. When you do, increase those units’ points values accordingly. The points values for \x05enhancements\x06 can be found in the Warhammer 40,000 app.","Unless otherwise stated:","• Only \x03CHARACTER\x04 units can be given \x05enhancements\x06. If such a unit contains more than one model, select one \x03CHARACTER\x04 model in that unit to have that \x05enhancement\x06.","• \x03EPIC HEROES\x04 models cannot be given \x05enhancements\x06.","• Your army cannot include more than one of the same \x05enhancement\x06.","\x05Upgrades:\x06 Some \x05enhancements\x06 are tagged with ‘Upgrade'. Unlike other \x05enhancements\x06:","• These can be given to non-\x03Character\x04 units.","• You can include up to three of the same Upgrade in your army (the second and third instances of the same Upgrade do not count towards the total number of \x05enhancements\x06 in your army, but you must still spend the stated points cost each time).","** If you are playing an Incursion battle, you can select a 3DP \x05detachment\x06 as your only \x05detachment\x06."]}]},{number:"00",title:"Universal Rules Updates",subsections:[{ref:"",title:"Move Types for Disembarking Units",text:["■ If a rule allows a unit to be \x05eligible to declare a charge\x06 after disembarking from a \x05\x03TRANSPORT\x04\x06 model that made a \x05normal move\x06 that turn, that unit makes an \x05assault disembark move\x06 (18.06) for that disembarkation (instead of a \x05disembark move\x06).","■ If a rule allows a unit to disembark from a \x05\x03TRANSPORT\x04\x06 model that made an \x05advance move\x06 that turn, that unit makes a \x05shock disembark move\x06 (18.07) for that disembarkation (instead of a \x05disembark move\x06)."]}]}],d={de:()=>a.e(6606).then(a.bind(a,6606)).then(e=>e.data),es:()=>a.e(9509).then(a.bind(a,1890)).then(e=>e.data),fr:()=>a.e(3949).then(a.bind(a,3949)).then(e=>e.data),it:()=>a.e(692).then(a.bind(a,692)).then(e=>e.data),ja:()=>a.e(6696).then(a.bind(a,6696)).then(e=>e.data),ko:()=>a.e(3371).then(a.bind(a,3371)).then(e=>e.data),zh:()=>a.e(491).then(a.bind(a,491)).then(e=>e.data)},c={"15.02":["Cost: 1CP","WHEN: Any phase, just after you make one of the following rolls for a friendly unit or model:","• Advance roll","• Charge roll","• Damage roll","• Hazard roll","• Hit roll","• Save roll","• Wound roll","• A roll to determine the number of attacks generated with a weapon.","TARGET: That unit or model.","EFFECT: You re‐roll that roll. If you are rolling more than one dice together, select one of those dice to re‐roll (excluding charge rolls, which you must re-roll in full)."],"15.03":["Cost: 1CP","WHEN: Fight phase, just after a friendly CHARACTER unit is selected to fight.","TARGET: That CHARACTER unit.","EFFECT: Select one CHARACTER model in your unit.","Until the end of the phase, that model’s melee weapons have the [PRECISION] ability."],"15.04":["Cost: 1CP","WHEN: Battle‐shock step of your Command phase, just before you make a battle-shock roll for a friendly unit.","TARGET: That unit.","EFFECT: That battle-shock roll is automatically successful.","RESTRICTIONS: You cannot use this stratagem more than once per battle."],"15.05":["Cost: 1CP","WHEN: Your Charge phase, just after a friendly MONSTER/VEHICLE unit ends a charge move.","TARGET: That MONSTER/VEHICLE unit.","EFFECT: Resolve the following sequence:","1. Select one enemy unit engaged with your unit.","2. Select one model in your unit engaged with that enemy unit.","3. Roll a number of D6 equal to the T characteristic of that model: for each 1, your unit suffers 1 mortal wound; for each 5+, that enemy unit suffers 1 mortal wound (to a maximum of 6 mortal wounds per unit)."],"15.06":["Cost: 1CP","WHEN: Your Shooting phase.","TARGET: One friendly unengaged EXPLOSIVES/GRENADES unit that is eligible to shoot and did not make an advance move this turn.","EFFECT: Resolve the following sequence:","1. Select one EXPLOSIVES/GRENADES model in your unit.",'2. Select one unengaged enemy unit within 8" of and visible to that model.',"3. Roll six D6: for each 4+, that enemy unit suffers 1 mortal wound (06.02)."],"15.07":["Cost: 1CP","WHEN: End of your opponent’s Movement phase.","TARGET: One friendly unit that is in strategic reserves (excluding AIRCRAFT).","EFFECT: Your unit makes an ingress move (20.04).","RESTRICTIONS: You cannot use this stratagem during the first battle round."],"15.08":["Cost: 1CP","WHEN: End of your opponent’s Movement phase.","TARGET: One friendly unengaged unit (excluding TITANIC units).","EFFECT: Your unit shoots using snap shooting (see below)."],"15.10":["Cost: 1CP","WHEN: Start of your opponent’s Shooting phase.","TARGET: One friendly SMOKE unit.","EFFECT: Until the end of the phase, each time an attack targets either your SMOKE unit, or a unit that is not fully visible to the attacking model because of one or more models in your SMOKE unit, the target has the benefit of cover against that attack (13.08)."],"15.11":["Cost: 1CP","WHEN: End of your opponent’s Charge phase.",'TARGET: One friendly unengaged unit within 12" of one or more enemy units. You can only select a VEHICLE unit if it is a CHARACTER/WALKER unit.',"EFFECT: Resolve a charge with your unit (11.02).","While doing so, before making the charge roll, you must select one of the following modes:","• When selecting charge targets, you can only select enemy units that made a charge move this phase and are within the maximum distance.","• is greater than 6 (after modifiers), change it to 6.",'can select any enemy units that are within 6" of your unit and within the maximum distance.'],"15.12":["Cost: 2CP","WHEN: Fight step of your opponent’s Fight phase, just after an enemy unit has resolved its attacks.","TARGET: One friendly unit that is eligible to fight.","EFFECT: Until the end of the phase, your unit has the Fights First ability and it must be the next unit you select to fight (12.04)."]},u={"05.02":{headRow:3,endRow:9,fingerprintEn:{head:["ATTACK'S STRENGTH VS TARGET'S TOUGHNESS","REQUIRED RESULT"],end:["Any other result","FAILS"]}}},m=[{id:"c2df3e97-f21e-4fc9-943e-37072c08c10e",question:"Aerialists ability allows you to get into a transport even though they disembarked a transport this turn?",answer:"Yes, as the unit embarking is not making a normal, advance or fall-back move as part of this embarkation."},{id:"9bfa47ed-be8d-4e11-80de-f3832d507ca1",question:"Can I select a unit to shoot or fight if it doesn't have melee or ranged weapons?",answer:"Yes, it just makes no attacks and then the fight type or shoot type is resolved."},{id:"7f767dd0-3996-417e-bba2-b7a5828b2430",question:"Can a model be within range of a weapon if it is not visible",answer:"Yes"},{id:"904b8b36-09f0-4449-a9c3-45892664ef60",question:"Do models destroyed when a unit is out of coherency count for mission objectives?",answer:"Yes."},{id:"e5941469-5653-49b2-919e-9c9246e811d4",question:"Does my model or unit become engaged while moving through a enemy units engagement range during a move?",answer:"No"},{id:"5928ab6e-7113-42c8-9085-4291faddae09",question:"How many mortals do you take from Hazardous tests for a combined vehicle/monster and Infantry unit",answer:"The roll would be all at once and it would be 1 MW per fail"},{id:"6b074ac1-8a03-43ac-8669-3bac17d372ab",question:"I failed hazard rolls from [Hazardous] weapons, do those mortal wounds have to be allocated to the models with the [Hazardous] weapons?",answer:"No, you allocate the mortal wounds to the unit as per Mortal Wounds(06.02). (This represents Bob the guardsmen picking up his fallen squad mates plasma gun or that the twisting power of James the Chaos Sorcerer pulling his followers into the warp.)"},{id:"e58d31bc-b6eb-4db1-b319-dc27dd60154f",question:"I have a rule that triggers when a mortal wound is allocated to a model, when does this happen?",answer:"When you select a model in the Select Model step of Mortal Wounds (06.02)."},{id:"814f382c-d6b7-4a30-a78b-1247b57ac133",question:"I have a unit being attacked with weapons that will modify some of their save rolls to be worse then 6 should I make those save rolls?",answer:"Yes, because other models in your unit may have Sv's that are better those models you've mentioned, this means that enough save rolls could be allocated to the those models that the rest of the results are not greater then the Sv's of the other models in your unit."},{id:"acdcfb0c-5b84-4b41-b271-751c4204bf56",question:'If I have a rule that says my unit can move up to 6" when it makes a pile-in move or consolidation move, does this also mean it changes the maximum distance of those moves to 6"?',answer:"Yes"},{id:"9657bb5d-72da-4d42-9927-731c9fc0e315",question:"If a rule allows my unit to pile-in or consolidate an extra distance in the Fight phase, when can I use that rule?",answer:"For pile-in moves, during the Pile-in step(12.02), and for consolidation moves, during the Consolidate step(12.07) of the Fight phase."},{id:"55ea7d23-2f9e-45bf-bf6c-d98bf682549f",question:"If a rule modifies how far a unit or model can move during a pile-in move or consolidation move does it also change the distance of the target units?",answer:"No"},{id:"4978f15f-2b4a-4805-aacd-db9b5cad71bd",question:"If a rule says a unit auto passes Desperate Escape tests does that mean it would auto pass the hazard rolls from a desperate escape move?",answer:"Yes"},{id:"fae8a959-9cbe-46e3-a721-029b23b24e24",question:"If a rule says a unit can embark into a Transport in a turn that unit disembarked, does this ignore the core rules restriction on embarking in a turn that unit made a set up move (see 18.02)?",answer:"Yes"},{id:"81bf7082-3ef5-47b9-bfc4-f2021fff1d4f",question:"If a rule says my unit must make a hazard roll does every model in the unit make a hazard roll?",answer:"No, the unit would make 1 single hazard roll."},{id:"bbe268a2-b1fd-43ab-8b24-fd4363730c3f",question:"If a unit becomes battle-shocked after starting an action does it stop performing that action?",answer:"Yes"},{id:"4c654d00-318d-4665-9e46-26cfab179a29",question:"If a unit has a rule that allows it to start an action when it is battle-shocked can it also continue doing that action if it becomes battle-shocked after starting an action?",answer:"Yes"},{id:"b49d0004-1dd8-4746-a971-0b6656719dd3",question:"If a unit makes any disembark move in a turn (i.e. Disembark move, Emergency Disembark move etc.) has it disembarked that turn?",answer:"Yes."},{id:"a89dddb3-7930-4704-9f7a-0a7664da4d84",question:"If my unit has taken control of an objective at the end of my movement phase and that unit has as an ability that secures an objective they control, can they secure that objective?",answer:"Yes"},{id:"ab92e97b-be2b-4125-9ded-fcfa6abe092e",question:"If my unit has the Deadly Demise ability and has an ability that allows it to Fight on Death, how do I resolve this?",answer:"Fight on Death rules are resolved before Deadly Demise abilities, meaning that your unit's Deadly Demise will resolve after your unit has fought/at the end of the phase and the relevant models have been removed from the battlefield."},{id:"ee9a398d-3acb-4440-b63a-68bed3e6e217",question:"If my unit has weapons that are identical in characteristics, but some of those weapons have [PRECISION] and those weapons targeted a unit without the character keyword, do I roll all of those weapons together?",answer:"Yes, the [PRECISION] ability is not an applicable ability for those attacks as there is no CHARACTER in the target unit for the ability to trigger its rule."},{id:"bb42e060-31e1-46bc-ba52-85cd5ea8c6cf",question:"If the [ANTI] ability on my unit is ANTI-non-Monster/Vehicle does it mean the [ANTI] rule triggers when targeting units that do not have the Monster or Vehicle keyword?",answer:"Yes, ANTI-non-(any keyword) will trigger on any unit that does not have the specified keyword."},{id:"66be2ad9-24af-4edf-890a-c0e55004bf76",question:'My rule says that "this units ranged attacks have +1 A", do each of my attacks get an extra attack dice?',answer:"No, it increases the A characteristics of the unit's ranged weapons by 1."},{id:"c7a83b0a-e8c3-44b5-a3ca-bb3dfba98c2d",question:"The Munitorium Field Manual shows my unit can attach to different units then are on it's datasheet, which do I use?",answer:"Use the Munitorium Field Manual."},{id:"3103e536-8fb8-4fa3-800c-c0d159115bba",question:'What does the X" in Lone Operative X" mean?',answer:'The X is a placeholder for a number of inches that the ability might appear in a rule with, like Lone Operative 15" where the X has been replaced with 15"'},{id:"ba488672-92ec-443d-9087-85a999342589",question:"When a move says that a model or unit must move in a way if it is able, can that requirement force the unit to end their move not in coherency?",answer:"No, when a model or unit is making a move it must follow requirements while ending that move in coherency"},{id:"fdefb262-1eb9-43fd-a2c8-70cf3bd2a621",question:"When a rule instructs you to perform a charge outside of the charge phase, do I resolve step 2 and 3 of the Charge step(11.02)?",answer:"Yes"},{id:"a7ba0395-6635-45cd-aeec-1cc3c0607a0b",question:"When checking coherency for my unit can my unit be in multiple groups?",answer:"No, it must be in a single contiguous group as per Units and Models (01.02) and What is Coherency in the core rules."},{id:"06c896b8-bf06-40bd-a892-b56cb3cde9d3",question:"When declaring the allocation order of groups in my unit I have more than one non-CHARACTER groups that contain a model with a missing wound, how must I select the order?",answer:"Those groups can be selected in an order of your choosing but must be in an order that makes them come before any non-CHARACTER groups that do not contain a model with a missing wound."},{id:"5553f538-6182-4e72-905a-67855489bb1d",question:"When selecting a target unit can the enemy model that is visible to my model and the enemy model that is in range of my model's weapon be different enemy models in the same unit?",answer:"Yes"},{id:"019feac1-cd25-4644-b855-2ce3fa048fee",question:"Can an attached unit be given an Upgrade?",answer:"Yes."},{id:"38785a5c-16ba-41c5-b936-723a385f57aa",question:"Can a unit have both an Upgrade and an enhancement?",answer:"No, units are prevented from having two enhancements, and Upgrades are enhancements."},{id:"3de45ba4-435e-4f58-a50c-fbda3f71bdc5",question:"Are Upgrades enhancements?",answer:"Yes, Upgrades are a type of enhancement (but not all enhancements are Upgrades)."},{id:"603e9b2f-cc24-498c-ac2e-08ad3068f257",question:"Are models that are within the boundary of a terrain area, but not on the ground floor of a terrain area (e.g. overhanging parts of FRAME VEHICLES or models on terrain features that are within that terrain area) within that terrain area?",answer:"Yes"},{id:"6575ee89-b92a-456d-8e59-4ee513df8f4e",question:"Do rules that affect a keyword include multi-word keywords that contain that keyword? For example, would rules that affect Commissar units affect a unit that has the Commissar Graves keyword?",answer:"No."},{id:"7a982686-03ff-4565-8d5a-2549e5650268",question:"After using an ability that increases the CP cost of a stratagem, must my opponent continue to use the selected stratagem at the increased cost if they have the necessary CP available?",answer:"Yes."},{id:"88fc6c54-a3a6-4757-947b-b2dab8b7f3bf",question:"In what step during the attack sequence do I roll for Feel No Pain?",answer:"In the Resolve Damage step of the Inflict Damage step (05.04)."},{id:"9aea2cef-c9db-4a30-bbfb-6b07c1f148a2",question:"Can an Epic Hero unit form an attached unit with a unit that has an enhancement?",answer:"Yes."},{id:"9b1c81f5-2ea0-40eb-9015-6a005367cd75",question:"While making a move type other than a normal/advance move, can my MONSTER/VEHICLE unit move through friendly units?",answer:"Yes."},{id:"9e243f82-42e9-4f0d-9e4b-3f5b74cd68bc",question:"If I place units in strategic reserves during the battle, can this exceed the 50% of my points limit for the battle restriction as mentioned in Placing Units in Strategic Reserves (20.01)?",answer:"Yes. That restriction is applicable before the battle, in the Declare Battle Formations step."},{id:"adf7c2cd-b765-4e84-abb7-f0ed45d52841",question:"Does the limit to the combined points value of my units in strategic reserves only apply until the start of the first battle round?",answer:"Yes."},{id:"beaeca32-9701-45f7-9461-879d8ae3d78f",question:"After using an ability that increases the CP cost of a stratagem, if my opponent does not have the necessary CP available for the selected stratagem, what happens?",answer:"No CP are spent and that stratagem's effects are not resolved (but that stratagem still counts as having been used this phase)."},{id:"c8d8181c-0fd4-40d0-a9b9-6dcfadfc287e",question:"Is being within range of a terrain objective the same as being within range of an objective marker?",answer:"Yes."},{id:"e01c8a02-7a36-4d3b-b168-976b11bd47e8",question:"When my unit shoots at another unit, how does it work if some models in the target unit are fully visible to some models in my unit, while others are within a terrain area/not fully visible?",answer:"For each attacking model in your unit, determine whether the target unit has the benefit of cover, as described in Terrain and Visibility. In this scenario, the target unit will likely have the benefit of cover against some of the attacking models, but not all. This means that, in an example unit where all attacking models are using the same weapon, when you get to the Resolve Attacks step of the Attack Sequence, you will collect dice for attacks made by models against which the target unit has the benefit of cover separately from the dice for attacks made by models against which the target unit does not have the benefit of cover."},{id:"e43402db-7c49-4cd6-acf7-fa6cac83acb0",question:"If a stratagem contains a section that carries an additional CP cost (such as the Into the Fray option of Heroic Intervention), is that additional cost considered to be a modifier?",answer:"No, a stratagem that costs 1CP and is making use of an optional +1CP section has an original cost of 2CP."},{id:"e846db5e-3138-4ac6-b7ee-ca2ff7fe303e",question:"Does vertical movement in a unit that has taken to the skies count towards the distance a model has used for the purposes of [Heavy]?",answer:"No."},{id:"fc49644c-cc46-47a0-892b-284a4c4ec018",question:"Can I group or allocate a wound to a destroyed model?",answer:"No."},{id:"04f15433-3ee1-4c6d-8546-29e4247dee5b",question:"My unit has access to a rule that changes the Damage characteristic of an incoming attack to 0. When such an attack is allocated to a model in that unit, is the Damage changed before or after save rolls?",answer:"After."},{id:"2d91a89e-59f3-410f-84cb-16644d7ea4a4",question:"Fight On Death (05.04.05) requires models awaiting such an ability to stay on the battlefield until their unit has attacked (or until the end of the phase). How do these models function while this is the case?",answer:"Models awaiting a Fight On Death ability are still present on the battlefield for all rules purposes. This includes (but is not limited to) the following regarding such models: They can be measured to by friendly/enemy abilities. They can be considered visible to friendly/enemy models where relevant. They can use their datasheet abilities. They can be targeted by stratagems. Enemy units can still be engaged with them (which may restrict the opposing player's consolidation/pile-In moves made as part of an overrun fight)."},{id:"421a6f30-63e2-4e1f-b352-99b643637c53",question:"Can I use the Insane Bravery stratagem on a battle-shocked unit?",answer:"No, as a unit's controlling player cannot target that unit with stratagems (01.07)."},{id:"60232b79-7a10-44a0-ac68-e27312c7ba60",question:"Units have all the keywords of all their models, and attached units have all the keywords of all of their component units. How are destroyed models taken into account for these purposes?",answer:"These statements are only true so long as the models possessing those keywords remain part of the unit; destroyed models do not contribute their keywords to their prior unit. Example: The Aspiring Sorcerer model in a unit of Rubric Marines is destroyed; as none of the remaining models in the unit possess the PSYKER keyword, that unit is no longer a PSYKER unit."},{id:"7ac6c358-0263-49ff-aee7-28b8fd4b5b8b",question:"Do a unit's abilities continue to function while they are embarked within a TRANSPORT?",answer:"Yes, within the restrictions specified by the ability itself. Embarked units are Not On The Battlefield (01.02.04), so any ability requiring visibility or measurement to another unit will fail. Example: Azrael is attached to an Intercessor Squad unit and embarked within a TRANSPORT, and that TRANSPORT is making a shooting attack using the Firing Deck ability. While Azrael's Supreme Grand Master ability is still technically active, it will have no effect, as the requirements of the ability are not met (the ability affects 'weapons equipped by models' in Azrael's unit, and for the purposes of Firing Deck, the TRANSPORT itself is equipped with those weapons instead)."},{id:"7f238e23-cd3f-40ad-aa91-c75274cc655e",question:"When checking line of sight from one model to another, is this drawn between the bases of those models, or between any part of them?",answer:"Line of sight is drawn from any part of the observing model to any part of the model being observed."},{id:"80182be3-1a44-464b-9ef6-cd9212429603",question:"If both players have units with the Scouts ability, do they alternate resolving scout moves?",answer:"Yes, players alternate resolving any pre-battle rules units from their army may have, starting with the player who will take the first turn."},{id:"aab10e23-6433-42ca-86e7-ddc829f16c47",question:"My attack has a rule that means it results in a critical hit on a hit roll of 4+. Does this work when snap shooting?",answer:"Unless otherwise stated, no: when snap shooting, each attack only hits on a roll of 6."},{id:"b7d3d760-a167-44b2-9c91-32ce86684225",question:"My attack has a rule that means it results in a critical hit on a hit roll of 4+, and I would otherwise need a 5+ to hit. Does a 4+ hit?",answer:"Yes, except when snap shooting: when snap shooting, each attack only hits on a roll of 6."},{id:"ce5fd555-a0f1-4bc9-85d3-00443143e94a",question:"When do the effects of a FLYING unit taking to the skies apply?",answer:"When that unit is selected to make a normal/advance/fall-back/charge move. Note that for an advance/charge move, this means you must declare that a unit will take to the skies before rolling for that advance/charge move."},{id:"dc9911da-e156-4b48-bf9b-18f9d96d037e",question:"If a rule refers to an 'objective marker', does this mean an 'objective'?",answer:"Yes (excluding rules in the Core Rules)'."},{id:"fb3b2776-c954-471b-b448-b70caa91929d",question:"How do modifiers to the charge roll (or to the maximum distance of the charge move, such as Take to the Skies) affect the selection of charge targets?",answer:'A charging unit may only select charge targets that are within the maximum distance of their charge roll, including any modifiers. If such a modifier occurs after selecting a charge target and causes that charge target to no longer be within the maximum distance, the charging unit would then select new targets (Target No Longer Eligible Or Viable, 04.03.03). Example: A unit\'s charge roll is 7", and that unit has a datasheet ability which adds 1 to charge rolls: that charge\'s maximum distance is 8", so you can select charge targets within 8". Example: A FLYING unit chooses to take to the skies and rolls a charge roll of 9"; that charge\'s maximum distance is 7" (9" minus the 2" from taking to the skies), so you can select charge targets within 7".'},{id:"db020803-7564-45c9-a6d4-e4cdf463da32",question:"Can a unit be controlling more than one objective at once?",answer:"Yes."},{id:"8c51d370-70b2-46c7-abaa-228b55c830c3",question:"When determining control over an objective, can the same model's OC count towards more than one objective that model is within range of?",answer:"Yes."},{id:"f1507145-5606-474c-ba71-f5c92f2d6faf",question:"If a rule's effect lasts until the end of a specific part of the battle (e.g. until the end of the phase, until the end of the turn), is that rule still in effect at the end of that part of the battle?",answer:"Yes. For example, if an ability gave a unit +1 OC until the end of the turn, at the end of the turn, that unit would still have +1 OC. That unit would not have +1 OC at the start of the next turn."},{id:"9638115f-b94b-4d05-ba62-df9fba2805ac",question:"When a model overhangs the edge of the battlefield, how does that affect its visibility?",answer:"That model's controlling player can draw line of sight from any part of that model that is not overhanging the edge of the battlefield. Their opponent can draw line of sight to any part of that model."},{id:"3da822cb-4a7c-44d2-8a9d-b867b4c4aed8",question:"When does a model's or unit's ability in an attached unit apply to all models in that unit?",answer:"A rule that applies to 'this/that unit' or 'models in this/that unit' applies to all models in an attached unit. Rules that just apply to one model in an attached unit (for example, a rule that grants a model Feel No Pain or Lone Operative) only apply to that model, not to all models in the attached unit."}],f={"10.07":[{title:"Indirect Fire",body:"When you select indirect shooting for a unit, its [INDIRECT FIRE] weapons can launch punishing barrages on targets that are not visible, but don’t forget that its other weapons can still target other visible targets."}],"12.04":[{title:"Do Units Have To Fight?",body:"Yes, you have to fight with all units that can, but you don’t have to pile in or consolidate with a unit if you don’t want to."}],"12.06":[{title:"Overrun Fights",body:"When a unit makes an overrun fight, its models can be moved such that enemy units that were unengaged become engaged. Such enemy units become eligible to fight this phase (and may even be able to fight next if they are Fights First units)."}],"12.08":[{title:"New Foes To Face",body:"While using the engaging consolidation mode, your unit can end its consolidation move engaged with enemy units that have not yet fought this phase. If so, each of those enemy units will have an opportunity to fight your unit, so think carefully about how aggressively you want to move your unit using this mode."}],"13.06":[{title:"Plunging Fire",body:"As well as gaining superior lines of sight, models that ascend tall terrain features can benefit from the Plunging Fire rule (22.05)."}],"14.03":[{title:"Hold At All Costs",body:"Some units have abilities that are triggered when they control an objective, or when they secure an objective for your army."}],"16.01":[{title:"Where To Find Actions",body:"The actions players can use can be found in other publications such as mission packs. All players can use core actions, while other actions may have restrictions such as army faction."}]},g=new Set(["01.07.01","03.03.01","03.04.01","04.01.01","04.01.02","04.02.01","04.03.01","04.03.02","05.01.01","05.04.01","08.02.01","09.02.01","11.02.01","13.02.01","13.06.01","18.04.01","19.04.01","04.00","05.00","07.00","08.00","09.00","10.00","11.00","12.00","01.01","01.02","01.03","01.04","01.05","01.06","01.07","02.01","02.02","02.03","02.04","02.05","02.06","02.07","03.01","03.02","03.03","03.04","04.01","04.02","04.03","05.01","05.02","05.03","05.04","06.01","06.02","06.03","07.01","07.02","07.03","08.01","08.02","08.03","08.04","08.05","09.01","09.02","09.03","09.04","09.05","09.06","09.07","10.01","10.02","10.03","10.04","10.05","10.06","10.07","11.01","11.02","11.03","11.04","12.01","12.02","12.03","12.04","12.05","12.06","12.07","12.08","12.09","13.01","13.02","13.03","13.04","13.05","13.06","13.07","13.08","13.09","13.10","13.11","14.01","14.02","14.03","15.01","15.02","15.03","15.04","15.05","15.06","15.07","15.08","15.09","15.10","15.11","15.12","16.01","17.01","17.02","17.03","18.01","18.02","18.03","18.04","18.05","19.01","19.02","19.03","19.04","20.01","20.02","20.03","20.04","21.01","21.02","21.03","22.01","22.02","22.03","22.04","22.05","23.01","23.02","23.03","23.04","24.01","24.02","24.03","24.04","24.05","24.06","24.07","24.08","24.09","24.10","24.11","24.12","24.13","24.14","24.15","24.16","24.17","24.18","24.19","24.20","24.21","24.22","24.23","24.24","24.25","24.26","24.27","24.28","24.29","24.30","24.31","24.32","24.33","24.34","24.35","24.36","24.37","24.38","24.39","25.01","25.02","25.03","25.04"]),b=/^\d{2}(\.\d{2}){0,2}$/;function y(e){return e&&b.test(e)?g.has(e)?"pdf":"app":null}let p=m.length>0?[{id:"faq",badge:"FAQ",eyebrow:"Core Rules",title:"Frequently Asked Questions",entries:m.map(e=>({id:"faq-".concat(e.id),title:"",text:["Q: ".concat(e.question," A: ").concat(e.answer)]}))}]:[];function w(){return(0,i.jsx)(h,{title:"Core Rules",description:"A simplified, searchable version of the free Warhammer 40,000 Core Rules.",searchPlaceholder:"Search the core rules…",eager:x,loaders:d,stratagemBodies:c,tableShapesByRef:u,pdfCalloutsByRef:f,extraGroups:p,sourceOf:y})}},8665:(e,t,a)=>{Promise.resolve().then(a.bind(a,3683))}},e=>{e.O(0,[4909,3451,7877,8441,1255,7358],()=>e(e.s=8665)),_N_E=e.O()}]);